export type ServiceLearningInsights={
  security:string[];
  optimization:string[];
  cost:string[];
  watchPoints:string[];
};

type Rule={match:RegExp;security:string[];optimization:string[];cost:string[];watchPoints:string[]};

const r=(match:RegExp,security:string[],optimization:string[],cost:string[],watchPoints:string[]):Rule=>({match,security,optimization,cost,watchPoints});

const rules:Rule[]=[
  r(/appsync/i,
    ["Authorize at the GraphQL field and resolver boundary: use Cognito, IAM, OIDC or Lambda authorizers deliberately instead of treating the API as one all-or-nothing permission surface.","Protect downstream data sources independently—AppSync authorization does not replace DynamoDB, Lambda, OpenSearch or HTTP endpoint permissions.","Use CloudTrail for control-plane changes and AppSync/CloudWatch logging selectively for resolver troubleshooting; avoid logging sensitive arguments or response data."],
    ["Choose direct data-source resolvers when possible; add Lambda only when business logic truly needs code, because it adds another scaling, latency and failure boundary.","Use pipeline resolvers for multi-step GraphQL logic, caching for repeatedly requested data, and subscriptions only for workloads that benefit from server-pushed updates.","Model GraphQL schemas around client access patterns so one request does useful work without creating resolver fan-out or N+1 access patterns downstream."],
    ["The important dimensions are GraphQL/API operations, real-time connection/update usage, caching where enabled, and the downstream services each resolver invokes.","A cheap AppSync request can still trigger expensive Lambda, DynamoDB, OpenSearch or cross-Region work; include those resolver-side costs in the design.","Reduce duplicate resolver work with better schema design, batching/caching and direct integrations before trying to optimize only the AppSync request charge."],
    ["Know the resolver chain: request mapping → resolver/pipeline functions → data source → response mapping.","Subscriptions use persistent real-time connections and are architecturally different from normal query/mutation request-response traffic.","When troubleshooting, first decide whether the failure is authorization, resolver logic, mapping, data-source permissions or the downstream service itself."]
  ),
  r(/\b(sqs|simple queue)\b/i,
    ["Grant producers SendMessage and consumers Receive/Delete permissions separately; queue policies matter when publishers or consumers are cross-account or service principals.","Encrypt queues with SSE when message bodies are sensitive and restrict KMS use to the principals that actually send or consume.","Monitor DLQ depth, age of oldest message and receive/delete behavior so poison messages and stalled consumers are visible."],
    ["Tune visibility timeout to exceed normal processing time and extend it for long jobs; an undersized timeout creates duplicate in-flight work.","Use long polling and sensible batch sizes to reduce empty receives and improve consumer efficiency.","Choose FIFO only when ordering/deduplication is required; Standard queues give broader throughput and at-least-once delivery semantics."],
    ["Requests are driven by API actions and payload chunks; batching can reduce request count substantially.","Include DLQ traffic, KMS requests, Lambda/ECS consumers and inter-Region or internet transfer where applicable.","Long polling and batching usually improve both efficiency and cost because they reduce empty or overly granular receive/send calls."],
    ["A message is not complete until the consumer deletes it; visibility timeout is temporary invisibility, not acknowledgement.","Standard queues can deliver duplicates and out of order, so consumers should be idempotent.","FIFO ordering is scoped by message group; use multiple groups when ordered streams can be processed independently."]
  ),
  r(/\b(sns|simple notification)\b/i,
    ["Restrict Publish separately from subscription administration, and use topic policies for service or cross-account publishers.","Use subscription filter policies to reduce unnecessary data exposure as well as unnecessary downstream processing.","Protect sensitive payloads with encryption where appropriate and remember that each subscriber must also secure its own destination."],
    ["Use one SQS queue per durable consumer when subscriber speed or failure should be isolated.","Filter at the topic/subscription instead of making every consumer receive and discard irrelevant messages.","Prefer event buses or queues when you need replay, durable backlog or workflow state; SNS is optimized for fan-out notification."],
    ["Cost follows publishes, deliveries and delivery protocol; one publish can multiply into many billed deliveries across subscribers.","Include SQS, Lambda, HTTP egress, SMS/email or other destination charges rather than counting only topic publishes.","Filtering before delivery can lower both SNS delivery volume and downstream compute/request cost."],
    ["SNS pushes; SQS is polled. That difference is often the quickest exam clue.","Fan-out is strongest when each independent consumer gets its own queue.","A topic does not hold a backlog for an unavailable HTTP/Lambda consumer in the same way a queue does—design retry/DLQ behavior explicitly."]
  ),
  r(/eventbridge/i,
    ["Use event-bus resource policies and least-privilege target roles so producers cannot publish to unintended buses and rules cannot invoke unintended targets.","Treat event payloads as shared contracts: avoid putting secrets or unnecessary regulated data into broadly routed events.","Audit rule, bus, schema, archive and target changes; failed target delivery should be observable through retries and DLQs where supported."],
    ["Filter on the bus so targets receive only relevant events; broad catch-all rules create needless invocations and coupling.","Use archives/replay for recoverability and testing instead of building custom event retention when the pattern fits.","Use Scheduler for time-based invocation and event buses for event routing; do not force cron semantics into domain-event rules."],
    ["Primary drivers include event ingestion, custom/partner events, archive storage/replay and target-side services.","A single event routed to many targets multiplies downstream Lambda, Step Functions, API or queue cost.","Precise event patterns reduce both unnecessary target invocations and operational noise."],
    ["EventBridge routes events; it does not provide a queue-like consumer backlog.","Rules are evaluated independently, so one event can match multiple rules and trigger multiple targets.","Archive/replay is a recovery tool, not a replacement for application idempotency."]
  ),
  r(/step functions/i,
    ["The state-machine execution role should be able to call only the services/actions used by the workflow.","Keep secrets out of execution input/history; pass references to Secrets Manager or Parameter Store instead of raw credentials.","Execution history can contain business data, so choose logging level and retention with data sensitivity in mind."],
    ["Use Standard workflows for durable, auditable long-running orchestration and Express for high-volume short-duration workloads where its execution model fits.","Prefer native service integrations over Lambda wrappers when the workflow only needs to call an AWS API.","Use retries with backoff, Catch paths, timeouts, Map/Parallel concurrency controls and callback tokens deliberately rather than relying on implicit application behavior."],
    ["Standard pricing is strongly tied to state transitions; Express follows executions, duration and memory usage.","Native integrations can remove Lambda runtime cost and an extra failure hop.","High-cardinality loops can multiply transitions quickly, so Map/Distributed Map design and item count matter to both performance and cost."],
    ["Step Functions stores workflow state; SQS stores messages and EventBridge routes events—do not treat them as interchangeable.","A retry repeats a state unless you design idempotency in the invoked operation.","Callbacks let workflows wait without holding compute, which is ideal for approvals and external asynchronous work."]
  ),
  r(/\blambda\b/i,
    ["Use a narrowly scoped execution role per function or workload boundary; do not give functions broad account permissions for convenience.","Keep secrets in managed secret stores and encrypt environment variables where needed; never bake credentials into deployment packages.","Control who can invoke the function with resource policies/API authorization and monitor asynchronous failures, destinations and DLQs."],
    ["Tune memory by measuring both duration and throughput because CPU/network scale with memory allocation.","Reuse SDK clients/connections outside the handler, control concurrency to protect downstream systems, and use provisioned concurrency only for latency-sensitive paths.","For streams/queues, tune batch size, partial-batch failure and event-source concurrency instead of scaling the function in isolation."],
    ["Core dimensions are invocations and GB-seconds; architecture can also add provisioned concurrency, ephemeral storage, logs, data transfer and downstream service calls.","More memory can cost more per millisecond but finish faster, so optimize measured total cost rather than choosing the smallest memory size.","Avoid chatty architectures where many tiny functions create extra requests, logs and orchestration overhead without a clear isolation benefit."],
    ["The 15-minute maximum duration is a design boundary, not merely a quota to raise.","Concurrency is shared capacity unless reserved; a hot function can affect others without deliberate concurrency controls.","Asynchronous invocation, event-source mapping and synchronous API invocation have different retry and failure semantics."]
  ),
  r(/api gateway/i,
    ["Authenticate and authorize at the API boundary with IAM, JWT/Cognito or Lambda authorizers as appropriate; combine that with least-privilege backend permissions.","Use throttling, quotas/WAF where appropriate and request validation to reduce abusive or malformed traffic before it reaches compute.","Do not expose backend credentials to clients; integration roles and private integrations should keep backend trust on the server side."],
    ["Choose HTTP APIs when their feature set is sufficient; use REST APIs when you need capabilities that HTTP APIs do not provide.","Cache only read-heavy responses with safe cache keys; incorrect cache-key design can leak data between callers.","Prefer direct AWS service integrations when they remove unnecessary Lambda code and latency."],
    ["Requests are a primary driver, with differences across REST, HTTP and WebSocket APIs; caching, data transfer and logging can add cost.","Backend Lambda/Step Functions/service calls are separate charges and often exceed the API front-door charge in complex workloads.","Select the API type from required features first, then optimize request volume, caching and payload size."],
    ["REST API, HTTP API and WebSocket API are different products with different capabilities and pricing models.","API Gateway throttling protects the API; it does not automatically make downstream databases safe from every burst.","Private APIs/private integrations solve network reachability, while authorization still controls who may perform an operation."]
  ),
  r(/cloudfront|lambda@edge/i,
    ["Keep origins private where possible using Origin Access Control for S3 and tightly scoped origin security controls for custom origins.","Use TLS, signed URLs/cookies or application authorization where content is restricted; caching must not bypass identity boundaries.","WAF and edge logs provide complementary protection/visibility—WAF filters requests while CloudFront controls delivery and caching."],
    ["Optimize cache keys so headers/cookies/query strings vary the cache only when the origin response truly changes.","Use origin request policies and compression to reduce origin traffic and transferred bytes.","For Lambda@Edge/CloudFront Functions, place only latency-sensitive lightweight logic at the edge and keep regional business logic regional."],
    ["Data transfer out and request volume dominate many distributions; invalidations, real-time logs and edge compute may add cost.","A higher cache-hit ratio reduces origin requests and can reduce both origin compute and data-transfer cost.","Forwarding unnecessary headers/cookies/query strings fragments the cache and can indirectly increase origin-side cost."],
    ["Cache policy controls the cache key; origin request policy controls what reaches the origin—those are related but not identical.","Viewer and origin request/response events occur at different phases; choose the edge trigger from the behavior you need.","A CDN improves delivery and origin protection, but it does not replace application authorization or origin resilience."]
  ),
  r(/\b(s3|simple storage service)\b/i,
    ["Block public access by default, use bucket/access-point policies deliberately and prefer temporary role-based access or presigned URLs over shared credentials.","Use SSE-S3 or KMS encryption according to key-control needs, and protect destructive operations with versioning/Object Lock where the requirement warrants it.","Use CloudTrail data events or S3 server access logs selectively when object-level audit is required; control access to the logs themselves."],
    ["Design prefixes/objects for the workload rather than emulating a filesystem; use multipart upload for large objects and lifecycle rules for aging data.","Use Intelligent-Tiering when access patterns are unknown or change, but use explicit classes/lifecycle when access and retention are predictable.","Keep analytics formats columnar/compressed and partitioned so Athena/Glue/Spark scan less data."],
    ["Storage GB-month, requests, retrievals, lifecycle transitions and data transfer vary by storage class.","Archive classes trade lower storage price for retrieval delay/fees; transition tiny short-lived objects only when the economics make sense.","Reducing scanned bytes, unnecessary GET/LIST activity and cross-Region/internet transfer can matter as much as raw storage size."],
    ["S3 is object storage: updates replace objects; there is no in-place block update semantics.","Versioning protects against overwrite/delete but still needs lifecycle management or old versions can accumulate indefinitely.","Replication is not backup by itself—replicated mistakes or deletions depend on the replication/versioning configuration."]
  ),
  r(/\b(ebs|elastic block store)\b/i,
    ["Encrypt volumes/snapshots with KMS and control snapshot sharing because snapshots can expose the full data set.","Restrict instance and backup roles; attach volumes only to workloads that require the block device.","Use CloudTrail plus EC2/EBS metrics to track administrative changes and performance saturation."],
    ["Choose gp3/io2 from required IOPS, throughput, latency and durability rather than only capacity.","Separate performance-intensive data/log workloads when independent IOPS/throughput tuning helps.","Use snapshots for recovery and AMIs for reusable boot images; they solve different lifecycle needs."],
    ["Provisioned GB-month is only one dimension; some volume types separately charge provisioned IOPS and throughput.","Unused oversized volumes and old snapshots are common hidden cost sources.","Right-size capacity/performance independently on gp3 instead of paying for excess capacity only to gain IOPS."],
    ["EBS is AZ-scoped block storage normally attached to EC2; it is not a regional shared filesystem.","Snapshots are incremental from a billing/storage perspective but each snapshot can restore a complete volume.","Multi-AZ database availability is an application/database architecture concern, not something EBS alone provides."]
  ),
  r(/\b(efs|elastic file system)\b/i,
    ["Use security groups plus IAM authorization/access points where appropriate; POSIX permissions remain part of the file-access model.","Encrypt data at rest/in transit and use access points to give applications isolated roots and identities.","Backups and filesystem policies should match the shared nature of the data because one mount can affect many clients."],
    ["Pick Regional vs One Zone and performance/throughput modes from availability and workload behavior.","Use lifecycle/tiering for cold files and watch metadata-heavy workloads because millions of small operations can behave differently from large sequential I/O.","Access points simplify multi-application mounts and reduce custom mount-time permission logic."],
    ["Storage class capacity plus throughput mode/usage are the main design dimensions; backups and cross-AZ access can add cost.","Lifecycle policies can move cold files to lower-cost classes automatically.","Shared file convenience can become expensive when large inactive datasets stay in the primary class indefinitely."],
    ["EFS is shared NFS file storage; choose EBS for single-instance block semantics and S3 for object semantics.","Throughput scales differently by throughput mode, so performance troubleshooting should inspect both I/O pattern and configured mode.","A shared filesystem can become a shared failure/performance dependency—monitor it as a platform component."]
  ),
  r(/dynamodb/i,
    ["Use IAM condition keys and fine-grained access patterns where useful; keep application authorization separate from table permissions.","Encrypt by default and protect exports/backups/streams with the same data-classification controls as the table.","CloudTrail covers control-plane activity; operational debugging also needs table/stream metrics and application-level request context."],
    ["Design partition and sort keys from access patterns first; avoid scans and hot partitions by distributing traffic across keys.","Use GSIs/LSIs only for real query patterns and remember each secondary index adds write/storage cost and its own scaling behavior.","Choose on-demand for unpredictable traffic and provisioned/autoscaling when traffic is predictable enough to benefit."],
    ["Read/write request units or on-demand requests, storage, backups, streams, global tables and indexes all contribute.","Strongly consistent reads cost more capacity than eventually consistent reads; item size directly affects consumed capacity.","Poor key/index design can multiply both latency and cost through scans, retries and write amplification."],
    ["DynamoDB scales partitions, but a single hot partition key can still throttle.","Transactions, strong consistency and global tables provide stronger semantics at additional capacity/replication cost.","Streams are change records for downstream processing; they are not a general-purpose queue for arbitrary producers."]
  ),
  r(/aurora|\brds\b|database/i,
    ["Place databases in private subnets, restrict security groups to application tiers and use Secrets Manager/IAM authentication where supported.","Encrypt storage, snapshots and replicas with KMS and control who can create/restore/share snapshots.","Audit administrative changes and monitor slow queries, connections, replication/failover and storage pressure—not just CPU."],
    ["Use reader endpoints/read replicas for read scaling and Multi-AZ/cluster replicas for availability according to the engine model.","Pool connections or use RDS Proxy for bursty serverless workloads when connection storms are the bottleneck.","Tune queries/indexes before scaling instance size; compute cannot fully compensate for inefficient access patterns."],
    ["Instance/ACU capacity, storage, I/O/requests, backup retention and data transfer vary by engine/deployment model.","Read replicas and Multi-AZ copies improve capability but add compute/storage cost; they should map to a real read-scale or resilience need.","Serverless capacity can lower idle cost for variable workloads but minimum capacity and sustained load still matter."],
    ["Multi-AZ is primarily availability; read replicas are primarily read scale (with engine-specific failover options).","Backups give point-in-time recovery; replicas are live copies and can replicate bad data changes.","Connection count can be the limiting resource before CPU, especially with highly concurrent Lambda/serverless clients."]
  ),
  r(/bedrock|amazon q|sagemaker|comprehend|rekognition|textract|transcribe|translate|polly|personalize|kendra|lex|machine learning|ai/i,
    ["Separate user/application authorization from model or AI-service permissions, and scope model/data access to the exact resources the workload needs.","Treat prompts, retrieved context, transcripts, documents and model outputs as potentially sensitive data; apply encryption, retention and logging controls accordingly.","For RAG/enterprise assistants, preserve source permissions during retrieval so the model cannot expose content a user was not allowed to read."],
    ["Measure quality, latency and cost together; optimize prompt/context size, retrieval quality, model choice and concurrency instead of only model speed.","Use asynchronous/batch inference for non-interactive work and smaller/specialized models where they meet the quality target.","Add evaluation and guardrails around the model boundary; deterministic business actions should remain explicit tools/workflows rather than hidden inside prompts."],
    ["Model/token/inference usage or provisioned capacity is only part of cost; vector search, storage, orchestration, logging and data transfer can be significant.","Long prompts and large retrieved contexts increase both latency and inference cost, so relevance filtering is a cost control as well as a quality control.","Provisioned capacity is useful only when utilization/latency requirements justify paying for reserved throughput."],
    ["Know which part of the AI system the service owns: model inference, retrieval/indexing, orchestration, training, feature processing or end-user assistant experience.","A successful model call is not proof of a good application—evaluate groundedness, safety, latency and business-task success.","Keep deterministic authorization and transactional rules outside probabilistic model reasoning."]
  ),
  r(/kinesis|firehose|msk|kafka|flink|stream/i,
    ["Use producer/consumer IAM or broker authentication and encrypt streams in transit/at rest; separate administrative permissions from data-plane read/write permissions.","Restrict cross-account/cluster connectivity deliberately and keep sensitive event payloads out of broad shared streams where possible.","Monitor consumer lag, failed delivery, throttling and retention pressure so data loss or stale processing is visible."],
    ["Partition/shard by a key that distributes load while preserving only the ordering you truly require.","Batch records and tune consumer concurrency/checkpointing to increase throughput without overwhelming downstream systems.","Choose managed delivery (Firehose) when you mainly need buffered delivery/transformation, and a stream/broker when consumers need independent real-time reads."],
    ["Capacity units/shards or broker compute, retained data, enhanced fan-out, transformations and destination services all contribute.","Tiny unbatched records can create inefficient request overhead; batching generally improves throughput and cost.","Retention and replica/broker count should be tied to replay/recovery requirements, not left oversized by default."],
    ["Ordering is normally partition/shard scoped, not global.","Consumer lag is often a more useful production signal than producer throughput alone.","Delivery services, durable streams and Kafka-compatible brokers solve different operational problems even if all move events."]
  ),
  r(/athena|glue|redshift|quicksight|open ?search|analytics/i,
    ["Use Lake Formation/IAM/resource policies to keep data authorization separate from query or visualization access.","Encrypt datasets, query results and catalog/warehouse storage, and restrict broad analyst access to sensitive columns/data sets.","Audit administrative/query activity as appropriate and keep result buckets/log destinations governed because they can contain the same sensitive data as sources."],
    ["Partition, compress and use columnar formats so engines scan/process only useful data.","Match engine to workload: serverless ad-hoc SQL, ETL/catalog, search, warehouse and BI each have different performance shapes.","Pre-aggregate/materialize repeated expensive computations when it improves both latency and scanned/processed volume."],
    ["Data scanned/processed, compute capacity, storage and concurrency vary by analytics service; downstream visualization/export/storage also count.","Poor partitioning and repeated full scans are common avoidable cost multipliers.","Reserved/provisioned analytics capacity pays off only when utilization and concurrency justify continuous capacity."],
    ["Cataloging data is not the same as transforming it, and transforming is not the same as querying it.","Serverless does not mean costless at scale—bytes processed and repeated queries can dominate.","For BI, semantic/data-set design can matter more to user performance than simply increasing backend compute."]
  ),
  r(/iam|identity center|access analyzer/i,
    ["Prefer federation and temporary credentials; reserve long-lived IAM users/access keys for exceptional machine cases with rotation and monitoring.","Separate identity policy, resource policy, permissions boundary, SCP and session policy responsibilities instead of assuming one policy type controls everything.","Use Access Analyzer/CloudTrail to detect unintended trust and verify who actually used privileged APIs."],
    ["Design roles around job functions and workload identities, then use groups/permission sets and automation rather than duplicating policies principal by principal.","Use conditions, tags and scoped resources to reduce policy size while keeping authorization understandable.","Test effective permissions and trust paths before adding broader wildcard actions to fix AccessDenied errors."],
    ["IAM itself is generally not priced per policy/user, but identity design drives costs in connected services such as Identity Center applications, logging or third-party federation.","The real optimization target is operational overhead and blast radius: simpler reusable roles reduce both administration effort and security risk.","Avoid creating separate bespoke identities where federation, roles or permission sets can reuse a governed access model."],
    ["Authentication answers who you are; IAM authorization answers what the principal may do.","A role trust policy controls who may assume the role, while identity/resource policies control what actions are allowed after assumption.","SCPs set organization guardrails; they do not grant permissions by themselves."]
  ),
  r(/kms|encryption sdk|cloudhsm|certificate manager/i,
    ["Treat key administration and key usage as separate duties; key policy plus IAM permissions define who can use KMS keys.","Use grants/resource policies carefully for AWS-service integrations and cross-account encryption.","Log key-management activity and watch for disable/schedule-deletion/policy changes because they can make large amounts of data unavailable."],
    ["Use envelope encryption so KMS protects data keys rather than encrypting large payloads directly.","Reuse data keys only within an acceptable security boundary and use service-integrated encryption instead of building custom crypto when possible.","Choose multi-Region keys or custom key stores only when their operational requirement is real; they add complexity."],
    ["KMS cost follows key inventory and API requests; high-frequency Encrypt/Decrypt calls can be reduced with envelope encryption/data-key caching where appropriate.","Custom key stores/CloudHSM introduce dedicated capacity costs and operational ownership.","Service-side encryption may trigger KMS calls at object/request scale, so request volume can matter more than key count."],
    ["KMS keys do not leave KMS in plaintext; envelope encryption moves protected data keys with the ciphertext.","Deleting or disabling a key can make otherwise healthy encrypted data unusable.","Encryption controls confidentiality; it does not replace authorization, backups or integrity controls."]
  ),
  r(/secrets manager|parameter store/i,
    ["Grant GetSecretValue only to workloads that need a secret and separate secret administration/rotation permissions.","Encrypt with KMS and use resource policies carefully for cross-account access; never copy secrets into source code or images.","Audit reads/changes and rotate credentials when the target system supports it."],
    ["Cache secrets in the application/extension for a controlled period instead of calling the service on every request.","Use managed rotation patterns for supported databases or implement tested custom rotation when required.","Store configuration that is not secret in configuration services rather than paying/operating a secret lifecycle for every parameter."],
    ["Secret storage and API calls are primary dimensions; frequent uncached reads can create unnecessary cost and latency.","Rotation can invoke Lambda and target-system operations, which should be included in the operational cost model.","Consolidate only when lifecycle and access boundaries match—do not reduce secret count by combining unrelated credentials."],
    ["Version stages such as AWSCURRENT/AWSPENDING are central to rotation workflows.","A secret store removes hard-coded credentials but applications still need an IAM identity to retrieve the secret.","Rotation is a distributed change across the secret and target credential, so test failure/rollback paths."]
  ),
  r(/waf|shield|network firewall|firewall manager|guardduty|security hub|inspector|macie|detective|security/i,
    ["Centralize security administration across accounts where supported, while keeping workload-specific response ownership clear.","Restrict who can suppress findings, change protection rules or modify logging because those actions can hide or weaken controls.","Send findings/logs to durable central destinations and automate only well-understood remediations with bounded permissions."],
    ["Tune rules/detections using observed traffic and false-positive data instead of enabling every control at maximum sensitivity.","Filter and aggregate findings before paging humans; use EventBridge/automation for deterministic low-risk responses.","Place preventive controls at the correct traffic/resource boundary so they block threats before expensive downstream processing."],
    ["Charges may follow protected resources, rules, requests inspected, logs/data analyzed or findings—security architecture shape determines the driver.","Verbose logging can become a material CloudWatch/S3/SIEM cost at high request volumes.","Central policies can reduce duplicated rule management but should not create unnecessary inspection paths for traffic that does not require them."],
    ["Differentiate prevention (WAF/firewall), detection (GuardDuty/Inspector/Macie), aggregation (Security Hub) and investigation (Detective).","A finding is evidence to evaluate, not proof that automated destructive remediation is always safe.","Logging destinations and retention are part of the security design because post-incident evidence is only useful if it still exists and is trustworthy."]
  ),
  r(/vpc|route 53|direct connect|vpn|transit gateway|private ?link|load balanc|global accelerator|network/i,
    ["Use security groups/NACLs/firewalls for authorization/inspection and route tables for path selection; do not confuse routing with permission.","Prefer private connectivity/endpoints for internal service access when it reduces public exposure and matches the architecture.","Enable flow/DNS/load-balancer logs where investigation needs them and protect network-control-plane changes with least privilege."],
    ["Design subnets/routes around failure domains and traffic paths; avoid centralized bottlenecks that force every packet through unnecessary hops.","Use the correct connectivity primitive—peering, Transit Gateway, PrivateLink, VPN or Direct Connect—based on transitivity, scale and ownership boundaries.","For load balancing/DNS, use health checks and independent targets so failover responds to application health rather than only infrastructure presence."],
    ["Hourly attachment/gateway/load-balancer charges plus processed bytes/data transfer are common networking dimensions.","Cross-AZ, cross-Region, NAT and inspection paths can create large data-processing/transfer bills even when compute is modest.","Keep traffic local/private when practical and remove avoidable hairpin routes before optimizing small per-hour resource charges."],
    ["Routing decides where traffic goes; security controls decide whether it is allowed.","PrivateLink is service-oriented private access, while Transit Gateway/peering connect networks—different ownership and routing semantics.","Multi-AZ does not guarantee application failover unless health checks and routing/load-balancing actually stop sending traffic to unhealthy targets."]
  ),
  r(/ecs|eks|fargate|ecr|container/i,
    ["Use task roles/pod identities for workload permissions and separate them from node/agent permissions.","Keep secrets outside images and scan/sign images in the registry/supply chain before deployment.","Restrict cluster/service network paths with security groups/network policies and log both control-plane and workload activity where needed."],
    ["Scale services from workload signals such as CPU, memory, queue depth or request rate—not only node count.","Right-size task/pod requests and limits so schedulers can pack capacity efficiently without causing throttling/OOM churn.","Use Fargate for reduced infrastructure management and EC2 capacity when specialized instances/daemon workloads/cost optimization justify node ownership."],
    ["Runtime vCPU/memory or EC2 capacity, load balancers, logs, image storage/scanning and data transfer all contribute.","Poor bin-packing/oversized requests waste node capacity; Fargate avoids idle nodes but can cost more for steady dense fleets.","Lifecycle old images/logs and use Savings Plans/Spot where workload interruption characteristics allow."],
    ["ECR stores images; ECS/EKS orchestrate workloads; Fargate supplies compute capacity—these are separate layers.","A healthy container process is not necessarily a healthy service endpoint; configure meaningful readiness/health checks.","Persistent state should live in purpose-built data/storage services unless the workload explicitly requires attached persistent volumes."]
  ),
  r(/ec2|auto scaling|beanstalk|app runner|lightsail|batch|compute/i,
    ["Use instance/task roles instead of static access keys and restrict inbound management access; prefer Systems Manager over broadly open SSH/RDP.","Harden AMIs, encrypt attached storage and separate public ingress from private application/data subnets.","Track OS/application logs and patch posture in addition to EC2 control-plane events."],
    ["Scale horizontally with load balancing/Auto Scaling when the workload allows it and right-size instance families from measured CPU, memory, network and storage needs.","Use Spot for interruptible capacity and Savings Plans/commitments for stable baseline usage.","Automate immutable image/deployment pipelines so replacement is safer than repairing snowflake instances manually."],
    ["Instance runtime is only the baseline: EBS, snapshots, load balancers, public IPv4, data transfer and logging often add meaningful cost.","Idle or oversized instances are the largest avoidable waste; scheduling non-production capacity and rightsizing usually beat micro-optimizing unit prices.","Commit discounts are valuable only for a stable baseline; keep variable/burst capacity flexible."],
    ["An Auto Scaling Group replaces/scales instances but does not make a stateful application stateless.","Instance family choice affects CPU architecture, memory, network and local storage—not just price.","Multi-AZ placement plus health-aware load balancing is what turns multiple instances into an available service."]
  ),
  r(/cloudwatch|cloudtrail|config|systems manager|control tower|organizations|trusted advisor|compute optimizer|service catalog|well-architected|management|governance/i,
    ["Separate central observability/governance administration from workload roles and use organization-wide delegation only for approved security/platform accounts.","Protect log/audit stores from deletion or tampering and encrypt sensitive operational data.","Use CloudTrail for API audit, Config for resource configuration/compliance and CloudWatch for runtime telemetry instead of expecting one signal source to do all three jobs."],
    ["Collect high-value metrics/logs at the required resolution and retention; noisy telemetry without ownership creates cost without operational value.","Automate repetitive remediation with Systems Manager/EventBridge/Lambda but require approval for high-blast-radius actions.","Use organization policies/baselines to prevent drift, then exception workflows for workloads that truly need deviation."],
    ["Logs ingested/stored/queried, custom metrics, alarms, traces, configuration items and automation executions are common cost dimensions.","High-cardinality custom metrics and verbose debug logs can grow faster than workload compute cost.","Retention, sampling and metric-filter design should follow investigation/SLO requirements rather than keeping every signal forever."],
    ["Metrics, logs, traces, audit events and configuration history answer different questions—know which evidence source fits the incident.","A dashboard is not an operational control unless someone/automation acts on the signal.","Central governance should reduce repeated account-by-account work without removing local workload ownership."]
  ),
  r(/codebuild|codepipeline|codedeploy|codeartifact|cloudformation|cdk|cli|sdk|developer/i,
    ["Use temporary roles for CI/CD and developer tooling; separate build permissions from production deployment permissions.","Protect artifact/package repositories and signing/encryption keys because a compromised supply chain can bypass runtime controls.","Audit pipeline, stack, package and deployment changes so you can reconstruct exactly what code/infrastructure reached production."],
    ["Build once and promote immutable artifacts between environments instead of rebuilding differently for production.","Use change sets/diffs, automated tests and staged/canary/blue-green rollout to reduce deployment blast radius.","Cache dependencies and keep build environments ephemeral so CI is fast without accumulating configuration drift."],
    ["Build minutes/compute, artifact/package storage and requests, pipeline actions and downstream deployment resources are the main dimensions depending on the tool.","Dependency caching and reusable artifacts reduce repeated compute/downloads.","Infrastructure-as-code tools themselves may be low/no direct cost, but every provisioned resource and CI action they create still matters."],
    ["CDK synthesizes CloudFormation; CloudFormation owns the stack deployment lifecycle.","CodePipeline orchestrates stages; CodeBuild builds/tests; CodeDeploy performs supported deployment strategies—do not collapse them into one service.","The safest production pipeline crosses an explicit permission boundary rather than giving the build environment permanent production credentials."]
  ),
  r(/dms|datasync|transfer|migration|snow/i,
    ["Authenticate source and target independently and use private connectivity/encryption for migration traffic where required.","Limit migration roles to the source/target objects they must move and protect staging areas because they may contain full production datasets.","Log transfer errors and validation mismatches so cutover decisions are evidence-based."],
    ["Separate initial bulk load from incremental/CDC synchronization when downtime must be minimized.","Size network paths and parallelism from real source/target throughput; the slowest endpoint often limits migration, not the service itself.","Validate checksums/row counts/application behavior before final cutover and keep rollback criteria explicit."],
    ["Migration-instance/runtime, transferred bytes, accelerated transfer, storage and network egress can all contribute.","Repeated failed/restarted transfers can cost more than one well-sized validated migration window.","Use incremental sync to avoid re-copying unchanged datasets when the service supports it."],
    ["A completed copy is not a completed migration until data is validated and applications are cut over.","Source and target change rates determine how long CDC catch-up takes.","Network bandwidth, source read limits and target write limits should all be measured before scheduling the migration window."]
  ),
  r(/iot/i,
    ["Use per-device identities/certificates and tightly scoped policies; one shared credential across a fleet creates an enormous blast radius.","Rotate/revoke device credentials and secure provisioning/firmware update channels.","Treat device telemetry and commands separately: command authorization can be more sensitive than telemetry ingestion."],
    ["Filter/aggregate at the edge when raw telemetry does not need cloud processing.","Partition topics/rules by device or workload semantics and buffer downstream processing so cloud consumers can scale independently.","Use fleet-management jobs/shadows only where their state model matches device connectivity patterns."],
    ["Message volume, rules/actions, device-management operations and downstream storage/analytics dominate at fleet scale.","Reducing message frequency/payload size or aggregating at the edge can produce larger savings than tuning individual cloud functions.","Always include downstream time-series/storage/stream-processing cost in an IoT design."],
    ["Devices can be intermittently connected, so desired/reported state and retry semantics matter.","MQTT topic design is both an application-routing and authorization decision.","At fleet scale, credential lifecycle and observability are first-class architecture components."]
  ),
  r(/connect|ses|customer engagement/i,
    ["Protect customer/contact data, recordings and message content with role-based access, encryption and retention controls.","Keep agent/operator permissions separate from administrative configuration and integration roles.","Audit configuration changes and access to sensitive interaction records."],
    ["Automate predictable routing/notification steps, but keep human escalation paths for exceptions.","Integrate customer context from authoritative systems rather than duplicating stale data into contact flows.","Measure queue/contact/message success, latency and abandonment/bounce metrics to find the actual bottleneck."],
    ["Usage often follows contact minutes, messages, channels or add-on AI/analytics features; storage/recording and telecom charges can be significant.","Automation can lower human handling cost but may add Lambda, Lex, Bedrock or analytics charges.","Retention of recordings/transcripts/messages should follow business/compliance needs rather than indefinite storage."],
    ["Channel delivery is only one layer; routing, identity, business data lookup and human handling remain separate concerns.","Customer interaction records often contain regulated/sensitive information and need explicit lifecycle rules.","Successful automation should have a deterministic fallback when the customer or downstream system cannot complete the automated path."]
  )
];

const serviceSpecificInsights:Record<string,ServiceLearningInsights>={
"Amazon Athena":{"cost":["Cost follows bytes scanned or capacity/engine usage, workgroup queries, Spark sessions, S3 requests/storage and transfer.","Unpartitioned data and SELECT * are direct cost drivers.","Include Glue, S3, KMS, Lambda, OpenSearch/Redshift and dashboard consumers."],"optimization":["Partition S3 data and use Parquet/ORC compression, projection and predicate pushdown so Athena scans only needed bytes.","Separate interactive SQL, scheduled queries and Spark applications with workgroups and quotas.","Use CTAS/UNLOAD and result reuse where appropriate, and clean result objects with lifecycle rules."],"security":["Use workgroups to restrict query-result locations, bytes-scanned limits, encryption and catalog access; analyst permissions must not imply raw S3 access.","Protect Glue catalog, S3 result buckets and KMS keys, and keep SQL/results logs from exposing sensitive data.","Audit workgroup, catalog, connector, prepared-statement and result-location changes."],"watchPoints":["Athena queries S3; stale catalog partitions or incomplete files can produce incorrect results.","Query results are S3 objects with their own access/retention.","SQL success does not prove the data is fresh or complete."]},
"AWS Data Exchange":{"cost":["Cost follows subscription/entitlement pricing, exports, transfer, S3 storage and downstream processing.","Repeated full revisions and unnecessary exports are common drivers.","Include Glue/Athena/Redshift/ML and cross-Region transfer."],"optimization":["Choose full, incremental or revision delivery from provider update cadence; validate schemas before consuming a new revision.","Use data products and assets with clear ownership, license and quality metadata rather than copying unmanaged files.","Filter/transform after delivery only when the downstream workload needs a smaller shape."],"security":["Separate provider/subscriber entitlement, subscription, export and data-product roles; licensed data needs governance after delivery.","Protect subscribed datasets, export buckets and data contracts with encryption, access and retention controls.","Audit subscriptions, grants, revisions, provider changes and exports."],"watchPoints":["Data Exchange distributes data; it does not guarantee provider accuracy, legality or fitness.","Revision timing, schema and license terms are production dependencies.","Subscription entitlement does not automatically grant access to the exported S3 objects."]},
"Amazon Data Firehose":{"cost":["Cost follows data volume, transformation/format conversion, delivery and destination processing; small objects and repeated retries add cost.","Dynamic partitioning can improve analytics but increases processing and prefix complexity.","Include S3, Lambda, Glue schema, KMS, OpenSearch/Redshift and transfer."],"optimization":["Choose Direct PUT, Kinesis source or supported connectors from producer backpressure and replay needs.","Tune buffer size/interval, compression, format conversion and dynamic partitioning to balance freshness, object count and destination efficiency.","Use transformation Lambda only for bounded enrichment; failed records and retries need a replay path."],"security":["Use delivery-stream roles with access only to the selected S3/Redshift/OpenSearch/HTTP destination and KMS key.","Protect buffering, transformation Lambda, backup and error-prefix buckets; records may contain raw event data.","Audit stream, destination, format-conversion, processor and error-output changes."],"watchPoints":["Firehose is managed delivery, not a general replayable stream; retention/replay depends on source and backup settings.","Delivery success can hide rejected records in an error prefix.","Buffering adds latency and object-size behavior changes with traffic volume."]},
"Amazon EMR":{"cost":["Cost follows instance/serverless vCPU/memory, EBS, S3, logs, data transfer and idle cluster time.","Spot fleets reduce cost for retryable stages; long-lived master/core nodes create fixed spend.","Include Glue catalog, KMS, NAT, ECR/containers and downstream analytics."],"optimization":["Choose EMR on EC2, EMR Serverless or EMR on EKS from cluster lifetime, framework, startup and isolation needs.","Tune executor memory, shuffle, partitioning, instance fleet and Spot capacity from the Spark/Hadoop workload.","Use managed scaling and transient clusters for burst processing, and write checkpoint/output data in recoverable formats."],"security":["Use EMR service, EC2/instance profile, step, notebook and data-lake permissions separately; cluster roles should not expose every S3 prefix.","Encrypt local disks, EBS, S3 data and logs, and protect bootstrap actions and cluster credentials.","Audit cluster, release label, step, security configuration and notebook changes."],"watchPoints":["A cluster can be RUNNING while a step is stalled on skew, shuffle, permissions or external data.","Release labels and framework versions change defaults and compatibility.","Spot interruption and executor loss require checkpoint/retry-aware jobs."]},
"AWS Glue":{"cost":["Cost follows DPU/worker/session time, crawlers, data catalog requests, data quality and storage/transfer.","Small files, repeated crawls and long interactive sessions are common drivers.","Include S3, Lake Formation, CloudWatch, KMS, endpoints and downstream query engines."],"optimization":["Choose Glue ETL, streaming, Data Catalog, Data Quality or interactive sessions from the pipeline decision; do not use crawlers as a substitute for schema governance.","Use pushdown, partition pruning, job bookmarks, worker types and autoscaling from observed Spark stages.","Version scripts and schemas, and design retries/idempotency around bookmarks and sinks."],"security":["Separate catalog, crawler, job, connection, workflow and data-location permissions; Lake Formation grants and IAM can intersect.","Encrypt job scripts, bookmarks, temporary data and logs, and keep connection credentials in Secrets Manager.","Audit catalog/table/schema, crawler, job, trigger and connection changes."],"watchPoints":["A crawler can infer a schema that is syntactically valid but operationally wrong.","Job bookmarks and sink idempotency determine duplicate behavior on retry.","Glue catalog visibility does not automatically grant data access."]},
"Amazon Kinesis Data Streams":{"cost":["Cost follows shard/stream capacity or requests, extended retention, enhanced fan-out and transfer.","Hot partitions create retries and lag without increasing total stream utilization.","Include Lambda, Flink, Firehose, S3, KMS and consumer compute."],"optimization":["Partition keys determine shard distribution; use aggregation/batching and on-demand/provisioned capacity from traffic volatility.","Choose enhanced fan-out for isolated low-latency consumers and standard shared throughput for less demanding consumers.","Design retention, replay, resharding and checkpoint behavior together."],"security":["Separate producer, consumer, enhanced-fan-out and resharding permissions; encrypt records and checkpoint stores with controlled KMS use.","Protect consumer applications and checkpoint tables because records may be replayed by multiple consumers.","Audit stream, shard, consumer, retention and capacity changes."],"watchPoints":["Ordering is per partition key, not global.","Expired records indicate consumer lag has exceeded retention and can become irreversible loss.","Resharding and consumer registration change throughput/ordering assumptions."]},
"AWS Lake Formation":{"cost":["Lake Formation governance cost is expressed through Glue catalog, analytics scans, S3, CloudTrail and sharing resources.","Fine-grained filters may shift cost to query/processing rather than storage.","Include cross-account sharing, KMS, Athena/EMR/Redshift and audit retention."],"optimization":["Use LF-tags and data filters for scalable governance, and keep Glue catalog/schema ownership separate from data access.","Grant table/column/row access at the lake boundary so Athena/EMR/Redshift consumers do not each implement inconsistent controls.","Centralize governance while assigning data-owner stewardship and approval workflows."],"security":["Use Lake Formation data-location, database/table, LF-tag and IAM permissions together; do not grant broad S3 access that bypasses governance.","Register locations and KMS keys deliberately, and protect cross-account resource shares and audit logs.","Audit grants, revokes, tag expressions, data filters, registrations and sharing changes."],"watchPoints":["IAM/S3 access can bypass Lake Formation if the architecture grants direct object access.","A catalog-visible table may still be inaccessible because of location/KMS/role permissions.","Cross-account grants, LF-tags and row filters have different propagation and troubleshooting paths."]},
"Amazon Managed Service for Apache Flink":{"cost":["Cost follows KPU/application runtime, storage/checkpoints, source/sink streams and transfer; idle applications are a fixed driver.","State size, checkpoint frequency and backpressure affect both cost and recovery.","Include Kinesis/MSK, S3, CloudWatch and downstream sink charges."],"optimization":["Choose parallelism, operator chaining, checkpoints, state backend and autoscaling from event rate and state size.","Design watermarks, windows, late-event handling and exactly-once/at-least-once sinks explicitly.","Use savepoints for controlled upgrades and test state compatibility before changing application code or runtime."],"security":["Use application role permissions narrowly for sources, sinks, checkpoints and snapshots; separate operator actions from runtime data access.","Encrypt checkpoints, snapshots, logs and stream data, and protect savepoint locations from accidental deletion.","Audit application code/version, runtime properties, scaling, snapshots and maintenance changes."],"watchPoints":["A running application can have growing backpressure or checkpoint failures.","Event time, processing time and late-data policy change result correctness.","State restoration and runtime-version upgrades are separate failure risks."]},
"Amazon Managed Streaming for Apache Kafka (Amazon MSK)":{"cost":["Cost follows broker/serverless usage, storage, requests, data transfer, MSK Connect and monitoring; replicas multiply storage.","Cross-AZ traffic, retention and high partition counts add cost.","Include KMS, Secrets Manager, PrivateLink, Connect workers and downstream processing."],"optimization":["Choose provisioned or Serverless MSK from traffic predictability and partition/throughput requirements.","Partition keys, replication factor, retention, compression, consumer groups and broker storage determine behavior; tune the partition model before broker size.","Use MSK Connect or Flink for integration when it reduces custom consumer operations, but isolate connector permissions."],"security":["Use cluster, client, topic and IAM/SCRAM/TLS permissions separately; topic authorization must match producer/consumer ownership.","Encrypt data at rest and in transit, protect Secrets Manager credentials and broker logs, and restrict cluster configuration changes.","Audit cluster, broker, topic, ACL, configuration and connectivity changes."],"watchPoints":["Kafka ordering is per partition and consumer lag is the key freshness signal.","Broker health can be green while a consumer group is stalled or rebalancing.","Partition count, quotas, retention and storage throughput constrain scaling."]},
"Amazon OpenSearch Service":{"cost":["Cost follows instance/storage nodes, UltraWarm/Cold, EBS, snapshots, data transfer, requests and logs.","Replica/shard choices multiply storage and indexing work.","Include Kinesis/Firehose, VPC endpoints, KMS, dashboards and cross-Region replication."],"optimization":["Choose instance/storage tier, shard/replica count, refresh interval and lifecycle policy from document/query/indexing behavior.","Use ISM and hot/warm/cold tiers for retention, bulk indexing and compression; avoid oversharding.","Use slow logs, circuit-breaker and heap metrics to tune queries before adding nodes."],"security":["Use fine-grained access, domain access policy, node-to-node encryption and encryption at rest together.","Separate dashboard, ingestion, query, snapshot and administrator roles; protect snapshot repositories and logs.","Audit domain, index, security-plugin, snapshot and access-policy changes."],"watchPoints":["Shard skew and heap pressure can cause tail latency while aggregate CPU looks normal.","Index lifecycle and snapshot retention determine recoverability and cost.","Query DSL, refresh and replica settings affect both correctness and performance."]},
"Amazon QuickSight":{"cost":["Cost follows users/reader sessions, author capacity, SPICE, queries, dashboards and underlying source; embedding has its own usage model.","Idle capacity, excessive refresh and direct-query scans are common drivers.","Include Athena/Redshift/RDS/S3, KMS, logs and embedding services."],"optimization":["Choose SPICE versus direct query from freshness, concurrency and source-load requirements; optimize source queries before adding capacity.","Use row-level security and folder ownership for tenant separation, and schedule refreshes from source change cadence.","Reduce visual/filter fan-out and use calculated fields/materialized data where it improves repeatability."],"security":["Use namespaces, groups, dataset permissions, row-level security, embedding sessions and data-source credentials as separate boundaries.","Protect SPICE, registered credentials, embedded tokens and dashboard exports.","Audit sharing, refresh, embedding, dataset and account configuration."],"watchPoints":["A dashboard can be usable but stale when SPICE refresh fails.","Embedded-session authorization and dashboard sharing are different controls.","Direct-query performance depends on the source engine and network path."]},
"Amazon AppFlow":{"cost":["Cost follows flow runs, data processed, connector/API usage, destination storage and transfer.","Full exports, retries and high-frequency schedules increase both AWS and SaaS cost.","Include S3, Redshift, EventBridge, KMS and downstream transformations."],"optimization":["Choose scheduled, event or on-demand flows from source-change behavior; use incremental fields to avoid full extracts.","Filter/projection and validation reduce transfer and destination processing; separate migration from recurring integration flows.","Design retries and idempotent upserts for SaaS rate limits and partial runs."],"security":["Use flow source/destination roles and connector credentials separately; protect SaaS tokens and field mappings.","Encrypt transferred data, destinations and logs, and restrict connector access to required objects/fields.","Audit flow, connector profile, mapping, trigger and run changes."],"watchPoints":["Flow completion can hide rejected records or destination mapping errors.","SaaS API limits and token expiry are separate from AppFlow service health.","Incremental cursor state must be preserved for correct replay."]},
"AWS AppSync":{"cost":["Cost follows GraphQL operations, real-time connections/messages, caching and downstream Lambda/DynamoDB/OpenSearch/HTTP work.","Subscriptions multiply persistent connection and update delivery costs.","Include logging, resolver retries and data-source charges."],"optimization":["Use direct data-source resolvers when possible; add Lambda only for logic that needs code and accept the extra latency/failure boundary.","Use pipeline resolvers for deliberate multi-step operations, batching/caching for repeated reads and subscriptions for real-time requirements.","Shape the schema around client access patterns to avoid resolver fan-out and N+1 downstream calls."],"security":["Authorize at GraphQL field/resolver boundaries using Cognito, IAM, OIDC or Lambda as appropriate; downstream data sources require their own permissions.","Protect schemas, resolver mappings, API keys, subscriptions and logs; do not log sensitive arguments or response data by default.","Audit API, data-source, resolver, function and authorization-mode changes."],"watchPoints":["A GraphQL failure can be authorization, mapping, resolver, data-source permission or downstream failure.","Subscriptions are persistent real-time connections, not normal request/response traffic.","AppSync authorization does not replace data-source authorization."]},
"Amazon EventBridge":{"cost":["Cost follows event ingestion, custom/partner events, archive storage/replay and target-side services.","One event matching several rules multiplies Lambda, Step Functions, API and queue cost.","Include schema registry, API destinations, KMS, logs and cross-Region routing."],"optimization":["Filter at the rule so irrelevant events never invoke targets; use archives/replay for recovery with idempotent consumers.","Use Scheduler for time-based invocation and buses for domain events; use Pipes when source filtering/enrichment is the actual pattern.","Set retries, DLQs and target timeouts from the downstream service's idempotency and backpressure behavior."],"security":["Use event-bus resource policies, rule roles, API destination connections and target permissions separately.","Keep secrets and regulated payloads out of broadly routed events, archives and replays.","Audit rules, schemas, archives, connections, schedulers and target failures."],"watchPoints":["EventBridge routes but does not provide a queue consumer backlog or global ordering.","Rule patterns are evaluated independently; a producer schema change can fan out unexpectedly.","Replay intentionally repeats events and must be safe."]},
"Amazon MQ":{"cost":["Cost follows broker instance hours, storage, data transfer, EBS and cross-AZ traffic; standby capacity increases fixed cost.","Persistent messages and long queues consume storage.","Include TLS, monitoring, client compute and cross-Region replication."],"optimization":["Choose ActiveMQ or RabbitMQ from protocol, plugin, topology and client compatibility; the managed broker does not remove messaging semantics.","Use multi-AZ, failover URLs, persistent messages, prefetch and acknowledgement settings from recovery and throughput requirements.","Tune queues/exchanges, dead-lettering and consumer concurrency instead of simply increasing broker size."],"security":["Use broker users, destinations, security groups, TLS certificates and IAM/service roles separately; broker access is not application identity.","Encrypt storage and connections, protect credentials and logs, and restrict cross-account network paths.","Audit broker, configuration, users, destinations and maintenance changes."],"watchPoints":["Broker availability does not guarantee consumer acknowledgement or message processing.","ActiveMQ and RabbitMQ differ in topology, failover and protocol semantics.","Redelivery, poison messages and durable subscriptions need explicit policies."]},
"Amazon SNS":{"cost":["Cost follows publishes, deliveries, protocol and fan-out; downstream subscriber charges multiply the publish.","Filtering lowers SNS delivery and consumer compute.","Include SQS, Lambda, HTTP egress, SMS/email and KMS."],"optimization":["Use one durable SQS queue per independent consumer when isolation/backlog matters; use direct Lambda/HTTP only for suitable push semantics.","Filter at subscription rather than receiving and discarding irrelevant payloads.","Use FIFO topics only when ordering/deduplication constraints and throughput fit the fan-out design."],"security":["Separate publish, subscribe and topic-administration permissions; use topic policies for cross-account/service publishers.","Use subscription filters to reduce data exposure and delivery, and encrypt topics where message content requires key control.","Secure each destination separately; SNS authorization does not grant access to an SQS queue or HTTP endpoint."],"watchPoints":["SNS pushes and SQS polls, so retry/backlog behavior differs.","Fan-out multiplies delivery work; one publish is not one end-to-end operation.","Destination-specific failure/DLQ behavior must be designed per subscription."]},
"Amazon SQS":{"cost":["Cost follows requests, payload chunks, FIFO throughput, storage and data transfer; long polling/batching reduce request waste.","DLQ retention and KMS requests add cost.","Include Lambda/ECS consumers, EventBridge, logs and cross-Region transfer."],"optimization":["Set visibility timeout above processing time and extend it for long jobs; use long polling and batch operations to reduce empty calls.","Choose Standard for broad throughput and FIFO for required ordering/deduplication; FIFO message groups control parallelism.","Use redrive policies and partial-batch failure handling with idempotent consumers."],"security":["Separate producer SendMessage and consumer Receive/Delete permissions; queue policies matter for cross-account and service principals.","Use SSE-SQS/KMS for sensitive messages and restrict KMS grants to actual producers/consumers.","Monitor DLQ, oldest-message age, receives without deletes and redrive activity."],"watchPoints":["Visibility timeout is temporary invisibility, not acknowledgement.","Standard queues can duplicate/reorder; FIFO ordering is scoped to message group.","A DLQ without a replay/poison-message procedure only hides failures."]},
"AWS Step Functions":{"cost":["Standard cost follows state transitions; Express follows executions, duration and memory; integrated services are separate.","Map/Distributed Map item count and retries can multiply transitions.","Include Lambda, EventBridge, SQS, service APIs, logs and callback systems."],"optimization":["Choose Standard for durable/auditable long-running workflows and Express for high-volume short executions when semantics fit.","Prefer native integrations over Lambda wrappers, and use Retry/Catch/Timeout/Map concurrency deliberately.","Use callback tokens for approvals/async work and make invoked operations idempotent before retries."],"security":["Use state-machine execution roles with only the integrated APIs/actions required; keep secrets out of input and execution history.","Protect logs, history, task tokens and callback endpoints; choose logging level from payload sensitivity.","Audit state-machine definition, alias/version, execution and IAM changes."],"watchPoints":["Step Functions stores workflow state; SQS queues and EventBridge routes—these are not interchangeable.","Retry repeats a state and can repeat side effects.","Execution history and payload limits affect design."]},
"Amazon Managed Blockchain":{"cost":["Cost follows network/member/node resources, requests, storage, data transfer and off-chain services.","Peer-node count and cross-account/Region access drive fixed and transfer costs.","Include certificates, APIs, Lambda, databases and audit storage."],"optimization":["Choose the supported blockchain network and node topology from consensus, member governance and application query requirements.","Use peer nodes and managed endpoints for the required read/write path; keep off-chain data in a purpose-built store.","Design transaction submission for confirmation delay, retries and idempotency rather than treating a request as committed immediately."],"security":["Separate network/member/node, voting, peer and application credentials; ledger access is not the same as AWS account access.","Protect network endpoints, certificates/keys and transaction data, and encrypt exported ledger data.","Audit network, member, peer-node, proposal and export changes."],"watchPoints":["Transaction acceptance and ledger commit are different states.","Network governance/proposals can delay changes even when the application is healthy.","Supported networks, Regions and node capabilities constrain portability."]},
"Amazon SES":{"cost":["Cost follows messages, recipients, attachments, dedicated IPs and data transfer; downstream Kinesis/SNS/CloudWatch adds cost.","Large attachments and repeated retries increase usage.","Include DNS, KMS, S3, event destinations and bounce processing."],"optimization":["Choose API/SMTP, configuration sets, dedicated IPs, event publishing and templates from deliverability and volume requirements.","Use suppression lists, bounce/complaint handling, rate controls and feedback loops to protect sender reputation.","Separate transactional and bulk streams and monitor domain/IP reputation before increasing sending rate."],"security":["Use identity verification, sending authorization, configuration sets and feedback permissions separately; restrict cross-account sending.","Protect email content, templates, contact lists and event destinations, and use DKIM/DMARC alignment for domain trust.","Audit identity, suppression, configuration-set, template and sending-limit changes."],"watchPoints":["A successful send API response does not guarantee delivery or inbox placement.","Sandbox/production access, regional identity verification and sending limits are separate gates.","Bounces, complaints and suppression state affect future sends."]},
"AWS Budgets":{"cost":["Budgets itself is a control; the resource consumption and notification/action services create the cost.","Granular budgets improve ownership but increase management noise.","Include SNS, Lambda, Organizations and Cost Explorer/CUR."],"optimization":["Use cost, usage, RI/Savings Plans and operational budgets for defined owners; tag/account/service filters must match the allocation model.","Set alert thresholds with billing-data delay in mind and use budget actions only for deterministic guardrails.","Pair budgets with Cost Explorer/CUR and anomaly detection for diagnosis rather than treating one alert as complete governance."],"security":["Restrict budget, action, notification, subscriber and account-scope permissions; budget actions can alter resources.","Protect email/SNS destinations and action roles with approval and least privilege.","Audit thresholds, filters, actions and notification changes."],"watchPoints":["Budget alerts are delayed relative to real-time usage.","A budget action can block legitimate growth or fail because permissions/SCPs deny it.","Shared/unallocated costs can make team budgets appear inaccurate."]},
"AWS Cost and Usage Report":{"cost":["CUR delivery is not the main cost; S3 storage, Athena scans, Glue catalog, Redshift/BI and processing drive the analytics bill.","Resource IDs and hourly granularity increase volume.","Include KMS, cross-account sharing, dashboards and data retention."],"optimization":["Choose hourly/daily granularity, resource IDs, split cost allocation and refresh options from the analysis need; not every dimension is free operationally.","Partition and compress CUR data and use Athena/Glue/Redshift views rather than copying raw files repeatedly.","Keep allocation/tag/category logic versioned so month-over-month comparisons remain explainable."],"security":["Restrict report definition, S3 bucket, KMS, Athena/Glue and BI access; CUR contains account/resource and spend detail.","Protect the central bucket, report prefixes, manifests and cross-account analytics roles.","Audit report, delivery, bucket, schema and data-sharing changes."],"watchPoints":["CUR is delayed/batch data, not real-time spend telemetry.","Schema and manifest changes require resilient ingestion.","Unallocated/shared costs and credits can be misinterpreted without billing-domain knowledge."]},
"AWS Cost Explorer":{"cost":["Cost Explorer usage is about cost visibility; savings or spend are driven by the resources/commitments it analyzes.","High-volume exports and downstream dashboards add cost.","Include CUR, S3, Athena, BI and notification tooling."],"optimization":["Use group/filter dimensions that match ownership and decision needs; save reports around recurring questions instead of broad exploratory scans.","Use amortized/uncategorized/forecast views deliberately and validate tag/account coverage.","Use Cost Explorer to investigate and CUR for repeatable large-scale analytics."],"security":["Restrict cost/usage queries, reservations, savings-plan and rightsizing visibility; billing data is organizationally sensitive.","Protect exports and reports and separate billing administrator from workload operator.","Audit cost-category, report, reservation and access changes."],"watchPoints":["Billing data latency and allocation updates affect recent-period conclusions.","Forecasts are estimates and can change with usage/credits/commitments.","Rightsizing and commitment recommendations need workload validation."]},
"Savings Plans":{"cost":["Cost is the hourly commitment plus uncovered usage; unused commitment is a real waste even when discount percentage looks attractive.","Amortize commitment across accounts and Regions using actual eligible usage.","Include RI interactions, credits, taxes, transfer and non-eligible services."],"optimization":["Choose Compute, EC2 Instance or SageMaker Savings Plans from stable eligible usage and flexibility requirements.","Model baseline versus burst/Spot usage; do not commit interruptible or uncertain workloads just to maximize discount.","Use sharing/consolidated billing intentionally and review utilization/coverage after architecture changes."],"security":["Restrict purchase, recommendation, commitment and billing visibility; commitment changes affect multiple accounts and workloads.","Protect payer-account access and approval workflows for purchases/changes.","Audit purchase, exchange, payment-option and sharing changes."],"watchPoints":["Savings Plans reduce eligible usage price; they do not guarantee capacity or availability.","Commitment utilization/coverage can diverge when workloads migrate or scale down.","Purchase recommendations depend on historical patterns and can lag a future architecture change."]},
"AWS App Runner":{"cost":["App Runner billing follows provisioned/active compute and memory consumption plus the source/image and networking resources it uses; it has no separate EC2 fleet to manage.","Scale-down settings can reduce idle cost but may increase cold-start latency and connection churn.","Include ECR storage/transfer, CloudWatch logs, NAT/VPC connector processing and downstream database calls in the service estimate."],"optimization":["Set the minimum and maximum provisioned instances and per-instance concurrency from measured request load; scale-to-zero behavior changes cold-start expectations.","Use App Runner's managed deployment lifecycle for simple web services, and move to ECS/EKS when you need sidecars, daemon control, custom networking or complex rollout orchestration.","Health checks must test the application path that proves readiness, not merely that the process has opened a port."],"security":["Deploy from a source repository or container image through an App Runner service; its instance role and ECR/source access role have different responsibilities.","Use VPC connectors for outbound private access, but remember that the public service endpoint and ingress configuration remain separate security decisions.","Restrict automatic-deployment and service-update permissions; application secrets belong in Secrets Manager or SSM Parameter Store, not source or image configuration."],"watchPoints":["A deployment can be successful while the new revision cannot reach a private dependency through the VPC connector.","Automatic deployment is triggered by repository/image changes; protect the pipeline because a pushed artifact can become production.","The service's managed abstraction hides infrastructure, but quotas, instance concurrency and health-check behavior still constrain production."]},
"AWS Auto Scaling":{"cost":["AWS Auto Scaling itself has no separate charge; the cost is the resources and monitoring signals it scales.","Predictive scaling can add capacity before a forecasted peak, so compare forecast error and idle hours against the availability objective.","Include CloudWatch alarms, EC2/ECS/DynamoDB/Aurora capacity and scale-out transfer effects in the estimate."],"optimization":["Use target tracking for a measurable utilization or throughput signal; step and scheduled scaling fit discrete events and known demand windows better.","Register only resources that share a scaling objective; mixing unrelated workloads in one plan produces misleading capacity decisions.","Set cooldown/warm-up behavior around the real startup time of the resource, otherwise the controller reacts to capacity that is not usable yet."],"security":["Use separate permissions for scaling plans, policies, resource registration and CloudWatch alarm changes; scaling authority can indirectly create or remove capacity.","Restrict service-linked roles and tag-based resource selection so a plan cannot change an unintended application fleet.","Audit policy, target-tracking, predictive-scaling and scheduled-action changes because they directly alter availability and spend."],"watchPoints":["AWS Auto Scaling is a control plane across services, not one universal fleet manager; each target has its own scaling semantics.","A policy can be healthy while the target resource is blocked by quota, placement capacity or a dependency bottleneck.","Check whether the signal is utilization, backlog, request rate or schedule before diagnosing a scaling failure."]},
"AWS Batch":{"cost":["Batch has no additional service fee; compute, storage, networking, logs and any Spot interruption/retry work determine cost.","Spot capacity can lower compute cost for checkpointable jobs, but retries and longer queue time must be priced against the saving.","Large images, NAT paths, ECR transfer, S3 I/O and retained CloudWatch logs are frequent hidden batch costs."],"optimization":["Use job queues and scheduling policies to express priority and fair-share rather than creating a separate cluster for every team.","Select EC2, Fargate, EKS or managed instances from runtime duration, privileged/container requirements, startup time and interruption tolerance.","Use array jobs, dependencies, retries and multi-node parallel jobs for the workload shape; avoid treating every item as an independent manually submitted job."],"security":["Give job roles access only to the input/output buckets, registries, secrets and AWS APIs required by the container; the service role is not the job role.","Use queue, compute-environment and job-definition permissions separately so submitters cannot change privileged container settings.","Protect job logs and artifacts because batch workloads often process large datasets and credentials."],"watchPoints":["Queue priority affects start order, not guaranteed completion time when the compute environment has no capacity.","A retry can repeat side effects; job containers must be idempotent or use checkpoints.","The job definition, execution role, compute environment and queue are separate objects; changing one does not automatically change the others."]},
"AWS Elastic Beanstalk":{"cost":["Beanstalk has no additional service charge; EC2, EBS, load balancer, CloudWatch, S3 source bundles and data transfer are billed underneath.","Worker environments add SQS request/storage and consumer capacity costs; idle web capacity remains an EC2 cost even when request traffic is low.","Include deployment artifacts, log retention and NAT/endpoint traffic in the environment estimate."],"optimization":["Choose web environments for request/response traffic and worker environments for SQS-backed asynchronous processing; the worker model changes failure and scaling behavior.","Use immutable or rolling deployments based on rollback tolerance, and configure enhanced health reporting with application-aware signals.","Treat platform version, AMI, load balancer, Auto Scaling and worker queue settings as one release design, not isolated toggles."],"security":["Elastic Beanstalk creates EC2, load-balancing and scaling resources in the customer's account; protect the service role and the underlying resources separately.","Use instance profiles for application runtime and service roles for environment operations; never place database credentials in configuration files or source bundles.","Restrict environment configuration, platform updates and saved-configuration access because they can alter the complete runtime."],"watchPoints":["Environment health can be green while the application returns valid but incorrect responses; health checks need meaningful URLs and dependencies.","A platform update can replace or restart instances and change runtime behavior; test it as a release.","Worker messages require idempotent processing and visibility-timeout alignment with job duration."]},
"Amazon EC2":{"cost":["EC2 cost depends on instance type, tenancy, Region, operating system, purchase option, EBS, public IPv4, transfer and monitoring.","Reserved Instances/Savings Plans, Spot and On-Demand solve different commitment and interruption problems; mix them only with a recovery design.","Stopped instances still retain billable EBS and some address/storage resources, so lifecycle policies must cover the whole instance footprint."],"optimization":["Select instance family from CPU, memory, network, EBS and accelerator needs; the cheapest vCPU is not necessarily the best price/performance.","Use placement groups only for a specific latency, throughput or spread requirement, and design user data/AMI bootstrapping for repeatability.","Separate ephemeral instance state from durable EBS, EFS, S3 or database state so replacement and AZ recovery are safe."],"security":["Use IAM instance profiles, IMDSv2, security groups, EBS encryption and SSM access instead of distributing SSH keys and static credentials.","Separate launch, stop/terminate, AMI, snapshot and security-group permissions; those actions have different blast radii.","Restrict AMI and snapshot sharing because copies preserve the workload's data and installed software."],"watchPoints":["An instance can be running while the application is unreachable because of routes, security groups, OS firewall, listener or dependency failure.","Reboot, stop/start, retirement, hibernation and host failure have different state and persistence consequences.","Account quotas, AZ capacity, ENI limits and EBS attachment limits can block scale-out before CPU becomes a problem."]},
"Amazon EC2 Auto Scaling":{"cost":["The Auto Scaling service has no additional fee, but each EC2, EBS, load balancer, CloudWatch alarm and transfer resource is billed.","Spot diversification, instance refresh and warm pools trade capacity cost against startup time and interruption risk.","Scale-out can increase NAT, EBS snapshot, log, public IPv4 and database-connection costs even when the group itself is free."],"optimization":["Use mixed instances policy and capacity-optimized Spot allocation when interruption tolerance allows it; use instance refresh for controlled AMI/launch-template rollout.","Set minimum, desired and maximum capacity from the real availability target, then use warm-up and cooldown values that reflect boot and registration time.","Use scale-in protection or lifecycle hooks only for bounded state handoff; durable state should live outside the instance."],"security":["Protect launch templates, instance profiles, lifecycle hooks and termination policies separately; a scaling role should not automatically modify application images or security groups.","Use ELB health checks in addition to EC2 health checks when process-level readiness matters, and restrict who can change the health-check source.","Secure lifecycle-hook destinations and notifications because they can receive instance metadata and termination events."],"watchPoints":["Desired capacity can be met while all instances fail the application health check; capacity count is not service health.","Lifecycle hooks can hold instances in a transition state and exhaust usable capacity if callbacks fail or time out.","AZ rebalance, Spot interruption, instance refresh and scale-in events can overlap; observe activity history before changing policies."]},
"AWS Fargate":{"cost":["Fargate cost follows requested vCPU and memory duration, platform/ephemeral-storage choices and data transfer; ECS/EKS control-plane costs are separate.","Fargate Spot can reduce cost for interruptible tasks but requires capacity-provider strategy and retry/drain handling.","Include NAT or interface-endpoint traffic, ECR transfer, logs, load balancers and task-to-database network costs."],"optimization":["Set CPU/memory at task level and container-level reservations/limits from measured behavior; Fargate pricing follows provisioned task resources.","Choose ECS or EKS orchestration based on operational model, and use capacity providers/Spot only when interruption handling is explicit.","Keep image sizes small, use graceful shutdown and tune deployment minimum/maximum percentages so replacement capacity fits the subnet and quota."],"security":["Use separate task-execution and task roles; the execution role pulls images and writes logs, while the task role accesses application data.","Use private subnets and VPC endpoints/NAT deliberately, encrypt ephemeral storage where required and restrict ECS/EKS control-plane permissions.","Do not treat a task definition as a secret store; inject sensitive values through Secrets Manager or SSM with narrow access."],"watchPoints":["A task can be RUNNING while its container is failing readiness or cannot resolve/reach a dependency.","ENI/IP exhaustion and platform quotas commonly block launches even when regional compute appears available.","Fargate task replacement is not durable state recovery; persist state and make shutdown/retry idempotent."]},
"AWS Lambda":{"cost":["Lambda cost follows requests, duration, architecture, memory, ephemeral storage, provisioned concurrency, logs and data transfer.","More memory can reduce duration enough to lower total cost; benchmark cost per successful business operation rather than price per millisecond.","Include API Gateway, EventBridge, SQS/Kinesis, NAT, KMS, Step Functions and downstream database charges."],"optimization":["Tune memory from measured duration and CPU/network scaling, and reuse SDK clients/connections outside the handler to reduce cold-start overhead.","Use reserved/provisioned concurrency only for a clear isolation or latency objective; configure event-source batch size and partial failure for streams/queues.","Choose synchronous, asynchronous, or poll-based invocation from the retry and backpressure semantics, not only from coding convenience."],"security":["Use a dedicated execution role per function, keep secrets in managed stores, and restrict resource-based invocation policies to the intended service/account.","Encrypt environment variables, layers and deployment artifacts, and control who can publish versions, aliases and event-source mappings.","Set DLQs/destinations and inspect asynchronous failure paths; a successful invocation response does not cover retries or downstream side effects."],"watchPoints":["The 15-minute execution ceiling is a design boundary; long work belongs in orchestration or batch patterns.","Concurrency controls protect downstream systems but can also create queue/backlog growth and throttled retries.","At-least-once event processing means idempotency is required even when the function code appears stateless."]},
"Amazon Lightsail":{"cost":["Lightsail bundles combine capacity and transfer allowances, while snapshots, databases, disks, static IPs and overage have separate cost behavior.","An idle unattached static IP or oversized bundle can remain billable without serving traffic.","Include export to other AWS services and cross-Region transfer when Lightsail is used as a migration starting point."],"optimization":["Use Lightsail for predictable small workloads and simple stacks; move to VPC-native EC2/ECS or managed databases when traffic, topology or governance becomes complex.","Choose bundles from measured CPU, memory, disk and transfer needs, and separate static IP/DNS/database components when their lifecycle differs.","Use snapshots and blueprints for repeatable rebuilds, but test application bootstrapping and secret rotation after restoration."],"security":["Use Lightsail firewall rules, instance keys, static IPs and snapshots as separate controls; the simplified console does not remove exposure decisions.","Use IAM to restrict instance, database, snapshot and networking administration, and avoid sharing the default SSH key.","Protect snapshots and exported resources because they can contain complete application data and credentials."],"watchPoints":["Lightsail's convenience boundary hides network and OS choices that still affect patching and incident response.","Bundle upgrades can change resource limits; validate the application before resizing production.","Snapshot restore proves recoverability only if DNS, certificates, secrets and external dependencies are restored too."]},
"AWS Outposts":{"cost":["Outposts pricing combines hardware/service commitment with local compute, EBS, data transfer and any supported service charges.","Underutilized fixed capacity is a major driver; forecast workload growth and replacement/maintenance needs before sizing.","Include facility, power, network circuits, support and data-transfer costs that are outside the AWS console estimate."],"optimization":["Place workloads on Outposts only when local latency, data residency or disconnected operation justifies the capacity commitment.","Plan rack/server capacity, instance families, local networking and service-linked dependencies before deployment; capacity cannot be treated like unlimited regional EC2.","Use local gateway connectivity and Region control-plane behavior deliberately, and keep a placement/failover plan for site or service-link loss."],"security":["Outposts racks/servers extend AWS infrastructure into a customer facility; physical, IAM, network, power and local operator responsibilities must be separated.","Restrict Outposts, site, capacity-task, instance and local gateway permissions, and protect the service link to the AWS Region.","Encrypt local EBS/S3-on-Outposts data and document how CloudTrail, monitoring and support evidence leave the site."],"watchPoints":["Outposts workload availability depends on facility power, local networking and the AWS service link, not only AZ-style software redundancy.","Supported services and instance families vary by Outposts type and version; validate the exact hardware catalog.","A Region control-plane outage and a local data-plane outage have different operational responses."]},
"AWS Wavelength":{"cost":["Wavelength adds the selected EC2/EBS/networking and carrier data-transfer economics; regional dependencies and mobile-network charges are additional.","Low latency can justify local capacity, but duplicated regional failover capacity increases total cost.","Include inter-zone/Region transfer, carrier egress, NAT/endpoints, monitoring and duplicated control-plane resources."],"optimization":["Use Wavelength for latency-sensitive mobile/5G paths where the user-to-carrier round trip is the bottleneck; it is not a generic replacement for an AZ.","Keep latency-critical processing local and place durable regional services behind an intentional interface; measure the extra dependency before deployment.","Design around supported instance types, carrier availability, IP addressing and failover to a Regional path."],"security":["Wavelength Zones place supported AWS resources in carrier locations; secure the VPC, carrier connectivity, subnet, application and operator paths separately.","Use IAM and security groups with the same least-privilege discipline as regional workloads, and protect traffic crossing the carrier/mobile network.","Audit Wavelength zone, subnet, carrier, route and workload changes, and confirm where logs and data are stored."],"watchPoints":["A Wavelength Zone failure can require application-level failover to the parent Region or another supported zone.","Carrier route, mobile attachment and AWS VPC health are different signals; monitor all three.","Service availability and supported features are carrier/Region-specific, so architecture assumptions cannot be copied between locations."]},
"Amazon ECR":{"cost":["ECR charges for private image storage and data transfer; compute platforms and cross-Region replication are separate costs.","Unused layers, old tags and replicated images accumulate; lifecycle policies need exceptions for rollback and compliance images.","Include ECR-to-runtime transfer, scanning, KMS, logs and CI build/publish charges."],"optimization":["Use immutable tags or digests in deployments, lifecycle policies for unreferenced layers and pull-through cache for controlled upstream reuse.","Keep images small and layered to reduce pull time, storage and transfer; separate build, release and production repositories when trust boundaries differ.","Use cross-Region/account replication for a defined deployment or recovery objective and test digest consistency."],"security":["Use repository policies and IAM separately for push, pull, lifecycle, replication and deletion; task execution roles should pull only required repositories.","Enable image scanning/signing controls and encrypt repositories with KMS where independent key control is required.","Protect immutable tags, lifecycle policies, replication configuration and registry credentials; audit image deletion and policy changes."],"watchPoints":["A successful image push does not prove the image is deployable on the target architecture or runtime.","Tag mutability can cause a deployment to resolve different code without a manifest change; digests avoid that ambiguity.","Scanning results, replication lag, registry quotas and image pull throttles can delay a rollout."]},
"Amazon ECS":{"cost":["ECS has no cluster-control-plane fee; EC2/Fargate, EBS, ECR, load balancer, logs, NAT and service-discovery resources determine cost.","Capacity-provider weighting and Spot usage can lower cost but change interruption and placement behavior.","Include idle cluster capacity, cross-AZ data transfer, image pulls, CloudWatch logs and task-to-service traffic."],"optimization":["Choose EC2, Fargate or external/managed capacity from daemon, privileged, GPU, startup and cost requirements; capacity providers express the placement policy.","Tune desired count, deployment percentages, health checks, circuit breakers, service discovery and task placement together.","Use rolling or blue/green deployment according to connection-drain and rollback behavior, and externalize state from tasks."],"security":["Separate ECS cluster/service/task-definition/deployment permissions from task-role permissions; the ECS control plane should not receive application data access.","Use task roles, execution roles, private networking, security groups and encrypted logs; service discovery and load balancer access are distinct controls.","Audit task-definition revisions, deployment circuit breakers, capacity providers and service-linked roles."],"watchPoints":["Service desired count can be met while tasks fail readiness or repeatedly restart; inspect deployment and container events.","Task placement can fail from ENI/IP, instance resource, AZ or capacity-provider constraints.","Task-definition revision, service deployment and image digest must be correlated during rollback."]},
"Amazon ECS Anywhere":{"cost":["ECS Anywhere has the ECS control-plane/service costs plus customer infrastructure, SSM, network, logging and operational labor costs.","Internet/VPN/Direct Connect paths and outbound traffic can dominate when tasks exchange data with AWS services.","Include host capacity, patching, image transfer, local storage and connectivity redundancy."],"optimization":["Use ECS Anywhere when workloads must remain on customer-managed infrastructure but benefit from ECS task/service control; it does not remove host patching responsibility.","Plan agent heartbeat, SSM connectivity, local capacity, task placement and drain behavior for intermittent connectivity.","Keep durable state and secrets external to ephemeral tasks, and define how deployments roll back when the external host is unavailable."],"security":["External instances run the ECS agent and require activation credentials, SSM connectivity and IAM roles; protect those credentials like fleet enrollment secrets.","Separate ECS control-plane permissions from SSM/operating-system administration and restrict which external hosts may join a cluster.","Encrypt and protect task logs, host metadata and activation records; audit deregistration and remote-command access."],"watchPoints":["An external host can appear registered while the agent is stale and unable to place or stop tasks.","Loss of the SSM/service-link path affects control and observability differently from the running container.","The customer owns OS, runtime, hardware and network failure domains; ECS does not provide EC2-style host replacement."]},
"Amazon EKS":{"cost":["EKS control-plane pricing is separate from node/Fargate, EBS, load balancer, NAT, ECR, logs and observability costs.","Unused node headroom and cross-AZ pod traffic are common drivers; measure bin-packing and network placement.","Include add-ons, control-plane logging, public IPv4, storage and telemetry in the cluster estimate."],"optimization":["Choose managed node groups, Fargate or autoscaled self-managed capacity from workload shape, daemon requirements, startup time and interruption tolerance.","Tune requests/limits, topology spread, disruption budgets, CNI/IP capacity, ingress and cluster autoscaling as one scheduling design.","Keep durable databases and object data in purpose-built services unless Kubernetes ownership is an explicit requirement."],"security":["Separate cluster-admin, Kubernetes RBAC, node, pod identity and add-on permissions; Kubernetes authorization does not replace AWS IAM.","Use private endpoints, encrypted secrets, pod security, network policies and image provenance controls, and restrict access to the API server.","Audit API-server, admission, node, add-on and AWS IAM events together because one layer alone cannot explain a pod's effective access."],"watchPoints":["A healthy EKS control plane does not mean pods are schedulable, ready or authorized to call AWS APIs.","Version skew, add-on compatibility, CNI IP exhaustion and node draining are recurring upgrade risks.","Pod identity, security groups for pods and network policies create different failure and authorization paths."]},
"Amazon EKS Anywhere":{"cost":["EKS Anywhere adds subscription/support and customer infrastructure costs on top of networking, storage, registry, observability and operations.","Disconnected or air-gapped environments need local artifact mirrors and capacity; those copies increase storage and maintenance cost.","Estimate hardware lifecycle, support, backup, power, connectivity and platform-engineering effort."],"optimization":["Choose EKS Anywhere when Kubernetes must run on customer-controlled infrastructure and the operational trade-off is acceptable; it is not a managed regional control plane.","Plan hardware/VM capacity, management-cluster placement, upgrades, CNI, storage and disconnected image distribution before creating workload clusters.","Test upgrade and replacement procedures with the actual infrastructure provider; preserve a reachable management path."],"security":["EKS Anywhere adds customer-managed infrastructure, OS, bootstrap, identity and registry responsibilities; protect the management cluster and workload clusters separately.","Use signed/approved bundles, secrets encryption and least-privilege credentials for bare-metal, VMware or other supported infrastructure providers.","Audit cluster lifecycle, bundle, machine, registry and remote-management changes; central AWS logs may not contain every local event."],"watchPoints":["The management cluster is a dependency for lifecycle operations; losing it does not necessarily stop running workloads but blocks safe changes.","Provider-specific failures, IPAM, load balancing and storage behavior differ from AWS EKS.","Bundle/version compatibility and local registry availability must be checked before upgrades."]},
"Amazon EKS Distro":{"cost":["EKS Distro itself is not the workload compute platform; price the underlying nodes, storage, registry, network, observability and support.","Artifact mirrors and retained versions add storage and transfer cost, especially in disconnected environments.","Include the engineering and maintenance effort required to operate the control plane and add-ons."],"optimization":["Use EKS Distro when you need AWS-aligned Kubernetes components outside the managed EKS control plane; select the distribution because of lifecycle and compatibility needs.","Treat Kubernetes version, container runtime, CNI, CSI and ingress compatibility as one tested matrix.","Automate upgrades through a staged cluster pipeline and keep a rollback-compatible image/artifact set."],"security":["EKS Distro supplies Kubernetes components and security updates; the consumer still owns cluster identity, API access, node roles and policy enforcement.","Verify provenance and signatures of EKS Distro artifacts, protect release metadata and restrict who can promote components into the cluster registry.","Audit component versions, admission configuration, image sources and upgrade approvals; distro content does not replace runtime logging."],"watchPoints":["Distro release availability does not guarantee that every add-on or provider is compatible with the selected version.","Security patches require an operational rollout; downloading a new distro release alone does not patch running nodes.","The distinction between upstream Kubernetes, EKS Distro and managed EKS matters when troubleshooting ownership."]},
"Amazon Aurora":{"cost":["Aurora cost combines instance/serverless capacity, I/O or I/O-Optimized economics, storage, backups, replicas, transfer and monitoring.","Serverless scaling and reader duplication can reduce idle capacity or increase it depending on workload volatility.","Cross-Region global databases, snapshot retention and logs belong in the estimate."],"optimization":["Choose provisioned, Serverless v2 or I/O-Optimized from connection patterns, burst behavior, I/O profile and failover objectives.","Use writer/reader/custom endpoints deliberately; connection pools must recover after writer failover.","Tune indexes, query plans, storage growth and reader scaling before increasing instance size."],"security":["Use cluster, database, Secrets Manager/IAM authentication and network permissions separately; writer/reader access should not share one administrator credential.","Encrypt cluster storage, snapshots, replicas and logs with KMS, and restrict clone/restore/share operations.","Audit parameter, failover, security-group, backtrack and global-database changes."],"watchPoints":["Writer failover changes the target behind the endpoint; applications need retry and connection recovery.","Aurora storage replication is not the same as cross-Region disaster recovery.","Serverless capacity and connection limits can be the bottleneck when average CPU is low."]},
"Amazon Aurora Serverless":{"cost":["Serverless pricing follows ACU time plus storage, I/O, backups, transfer and monitoring; minimum ACU is an idle-cost floor.","Capacity spikes, minimum capacity and connection proxies can dominate cost more than average request volume.","Include cross-Region replicas, snapshots and data transfer in the estimate."],"optimization":["Use Aurora Serverless v2 for variable database capacity when connection behavior and scaling granularity fit; it is not an excuse to ignore connection pooling.","Set minimum/maximum ACUs from latency and cost objectives, then test scale-up time under concurrent transactions.","Use reader/writer endpoints and transaction timeouts that tolerate capacity changes and failover."],"security":["Use the cluster security group, Secrets Manager/IAM authentication and database roles separately; automatic capacity does not change database authorization.","Encrypt storage, snapshots, logs and cross-Region copies, and protect pause/resume configuration from unauthorized changes.","Audit scaling configuration, parameter groups, endpoints, failover and restore operations."],"watchPoints":["Capacity can scale while a connection pool, lock or query plan remains the real bottleneck.","Pause/resume behavior, cold start and transaction semantics must be tested for the chosen engine mode.","Aurora Serverless v2 and legacy v1 have materially different scaling and availability behavior."]},
"Amazon DocumentDB":{"cost":["DocumentDB charges for instance hours, storage, I/O, backup storage and transfer; replicas multiply instance cost.","Unused replicas, indexes and backup retention grow cost without improving the target workload.","Cross-AZ and cross-Region traffic, monitoring and snapshot export add separate drivers."],"optimization":["Choose instance class, replica count, indexes and query patterns from document workload; MongoDB API compatibility does not mean identical engine behavior.","Use replicas for read scaling and failover, and monitor replication lag and storage growth rather than only CPU.","Design indexes and document shapes to avoid collection scans and oversized records."],"security":["Keep clusters private, use TLS and Secrets Manager, and separate cluster administration from application database users.","Encrypt clusters, snapshots and instances with KMS; restrict snapshot sharing and export destinations.","Audit parameter, instance, network, user and snapshot changes without exposing query payloads."],"watchPoints":["DocumentDB compatibility is API-level; operators must validate unsupported features, query plans and consistency behavior.","Failover and replica lag affect read-after-write expectations.","Storage autoscaling does not remove the need to monitor index and document growth."]},
"Amazon DynamoDB":{"cost":["Cost follows read/write request units or on-demand requests, item size, storage, indexes, backups, streams and global replication.","A scan, oversized item or write-amplifying index can dominate cost despite low application request count.","Global tables add replicated writes and cross-Region transfer; include them explicitly."],"optimization":["Design partition/sort keys from access patterns; hot keys throttle one partition even when aggregate capacity is available.","Choose on-demand or provisioned/autoscaling from traffic predictability, and use GSIs, projections, batching and write sharding deliberately.","Use transactions and strong consistency only where the application semantics justify their extra capacity and latency."],"security":["Use table/index/stream/export permissions separately and apply IAM conditions for tenant or partition boundaries where appropriate.","Encrypt tables, PITR backups, exports and streams with controlled KMS access; protect destination buckets as copies of the table.","Audit key-schema, index, backup, stream and global-table changes."],"watchPoints":["Streams are partition-ordered change records, not a general-purpose queue.","Transactions, strong reads, TTL and global tables change behavior and cost independently.","PITR protects recovery but restore/export destinations need their own access and retention controls."]},
"Amazon ElastiCache":{"cost":["Cost follows node hours, reserved capacity, data transfer, snapshots and cross-AZ/Region replication; replicas and shards multiply node cost.","Oversized memory, low hit ratio and cross-AZ client traffic are common drivers.","Include origin database load and invalidation/rebuild compute when evaluating cache economics."],"optimization":["Choose Redis/Valkey or Memcached from persistence, replication, failover, data structures and cluster-mode needs.","Set eviction policy, maxmemory, shard/replica topology and connection pooling from the workload; adding nodes does not fix a bad key distribution.","Use cache-aside/write-through or session patterns with explicit invalidation and stale-data behavior."],"security":["Use subnet groups, security groups, TLS/auth tokens and IAM/Redis or Memcached permissions according to engine; cache access is still data access.","Encrypt nodes, snapshots and transit where supported, and restrict snapshot/export and user-group changes.","Audit parameter, user, subnet, replication-group and failover changes."],"watchPoints":["A cache hit is not a consistency guarantee; stale or evicted data must be safe to recompute.","Failover, resharding and maintenance can change connections and key placement.","Memcached and Redis-compatible engines differ in persistence and recovery; do not transfer assumptions between them."]},
"Amazon Keyspaces":{"cost":["Cost follows read/write capacity or on-demand requests, storage, backups, multi-Region replication and transfer.","Poor partition-key distribution creates throttling and retries that increase both latency and cost.","Cross-Region writes and replicated storage must be priced separately from the local table."],"optimization":["Model partition keys and clustering columns from Cassandra-style query patterns; Keyspaces does not make arbitrary queries efficient.","Choose on-demand or provisioned capacity from traffic shape, and use multi-Region tables only when write locality and conflict semantics are understood.","Use prepared statements, page sizes, retries and connection pooling appropriate to the managed Cassandra API."],"security":["Use service-specific IAM and keyspace/table resource policies, encrypt data with KMS where required, and isolate application roles by keyspace.","Control client certificates/credentials, VPC endpoints and export/backup destinations; CQL access still needs least privilege.","Audit keyspace, table, capacity and backup changes."],"watchPoints":["Cassandra compatibility does not mean every driver feature or consistency pattern behaves like a self-managed cluster.","Partition hot spots and large partitions are the primary scaling traps.","Multi-Region last-writer/conflict behavior must be part of application correctness, not just availability planning."]},
"Amazon Neptune":{"cost":["Cost follows instance hours, storage, I/O, replicas, backups, loader data transfer and cross-Region replication.","Graph indexes and high-degree traversals increase memory/CPU and can require larger instances.","Include replica, snapshot retention and application-side graph caching in the estimate."],"optimization":["Choose Neptune engine/query model from property-graph or RDF workload; Gremlin, openCypher and SPARQL have different query patterns.","Design vertex/edge properties and indexes around traversals, avoid unbounded fan-out, and use replicas for read-heavy graph exploration.","Use bulk loader and maintenance windows for ingestion rather than sending large graph loads through interactive queries."],"security":["Keep Neptune in private subnets, use IAM/TLS and database roles appropriately, and separate graph administration from query access.","Encrypt clusters, snapshots, logs and replicas with KMS; restrict snapshot sharing and export operations.","Audit cluster, parameter, endpoint, security-group and loader changes."],"watchPoints":["A graph query can explode from one high-degree vertex; limit traversal depth and result shape.","Failover and replica lag affect read routing and graph freshness.","Engine version and query language support should be checked before porting a graph workload."]},
"Amazon RDS":{"cost":["RDS charges for instance, storage, provisioned IOPS/throughput, backups, Multi-AZ, replicas, transfer and licenses for some engines.","Oversized storage, idle read replicas and long snapshot retention are common cost drivers.","Cross-AZ database traffic and export/log processing belong in the total cost."],"optimization":["Select engine, instance class, storage type/IOPS, Multi-AZ, read replicas and Proxy from workload and recovery objectives.","Use RDS Proxy or pooling to protect connection limits, and tune indexes/query plans before scaling compute.","Separate backups, reporting and analytical extraction from the primary transaction path."],"security":["Use private subnets, security groups, Secrets Manager/IAM authentication where supported, and separate master, application and read-only database users.","Encrypt storage, snapshots, replicas and logs with KMS and restrict restore/share operations.","Audit parameter groups, option groups, failover, maintenance and network changes."],"watchPoints":["Multi-AZ standby is for availability/failover, not read scaling.","Engine-specific parameter, replication and backup behavior matters more than the generic RDS label.","Storage autoscaling and instance scaling do not fix connection leaks or lock contention."]},
"Amazon Redshift":{"cost":["Redshift cost depends on provisioned node-hours or serverless processing, managed storage, snapshots, data transfer and concurrency features.","Poor sort order, vacuum/rewrite work and repeated scans increase compute and storage cost.","Cross-Region data sharing, Spectrum scans and S3 staging charges must be included."],"optimization":["Choose provisioned RA3 or Serverless from workload predictability, managed storage and concurrency requirements.","Use sort/distribution keys, automatic table optimization, materialized views, workload management and COPY/UNLOAD formats from observed queries.","Separate BI concurrency, ETL windows and ad-hoc users with workgroups/queues and appropriate workload isolation."],"security":["Use cluster/workgroup IAM, database roles, VPC security groups, encryption and Secrets Manager separately; restrict COPY/UNLOAD locations.","Encrypt data, snapshots and audit logs, and control data sharing, cross-account namespaces and external schema access.","Audit resize, pause/resume, user/role, spectrum, data-sharing and snapshot operations."],"watchPoints":["A query can be queued or spill to disk while cluster health is green.","Distribution skew and stale statistics create performance issues that resizing alone may not solve.","Pause/resume, snapshot restore and serverless capacity have different availability and startup behavior."]},
"Amazon Timestream":{"cost":["Cost follows writes, memory/magnetic storage, queries, scheduled queries and data transfer; cardinality and retention drive the long tail.","Long memory retention and repeated unbounded queries can cost more than ingestion.","Include S3 exports, dashboards, Lambda and cross-Region transfer in the pipeline estimate."],"optimization":["Design dimensions and measures for the query patterns; excessive cardinality increases storage and query work.","Set memory-store and magnetic-store retention from freshness and access needs, and use scheduled queries for recurring aggregates rather than rescanning raw data.","Use batching and timestamp ordering at ingestion and avoid querying raw high-resolution history when an aggregate is sufficient."],"security":["Use database/table IAM and KMS controls separately, and restrict write/query roles to the time-series domains they need.","Protect magnetic-store retention, memory-store data, scheduled queries and S3 exports; time-series data can reveal sensitive operations.","Audit retention, table, scheduled-query and export changes."],"watchPoints":["Late-arriving data, versioned records and measure conflicts affect the final time-series result.","Memory-store availability and magnetic-store query behavior differ; retention transitions are not instantaneous.","Query time range and bin size are major performance and cost controls."]},
"AWS CDK":{"cost":["CDK itself is a development tool; cost comes from CloudFormation resources, asset buckets, build pipelines and deployed infrastructure.","Asset bundling, Docker builds and multi-environment pipelines add build/storage/transfer cost.","Include bootstrap stacks, staging buckets and retained artifacts in cleanup and cost reviews."],"optimization":["Use constructs and stages to reuse patterns without hiding environment-specific security or replacement behavior.","Synthesize and diff in CI, pin dependencies and context, and keep logical IDs stable when stateful resources must survive refactoring.","Use escape hatches only with explicit review; direct CloudFormation overrides can bypass construct-level assumptions."],"security":["Treat CDK source, context, synthesized templates and bootstrap roles as deployment artifacts; protect the bootstrap trust boundary.","Use separate deploy roles and permissions boundaries for environments, and do not put secrets in context, constructs or synthesized templates.","Review CloudFormation diffs and asset hashes in CI, and audit bootstrap, pipeline and stack changes."],"watchPoints":["A code change can synthesize a destructive replacement even when TypeScript compiles successfully.","Context values and feature flags can make two environments synthesize different templates.","The CDK app, bootstrap version, CloudFormation stack and deployed assets must be versioned together for reliable rollback."]},
"AWS CodeArtifact":{"cost":["Cost follows package storage, requests, data transfer and upstream/external retrieval; old versions and replicated domains accumulate.","Cross-Region/account package pulls and CI fan-out add transfer and request cost.","Include CodeBuild/CodePipeline, scanning and artifact retention in the package supply-chain estimate."],"optimization":["Use upstream repositories and external connections to avoid duplicating package mirrors, but apply approved-package and dependency controls.","Use immutable package versions where possible, retention policies and domain/repository layout that matches promotion boundaries.","Cache dependencies in builds while preserving provenance and vulnerability scanning before production use."],"security":["Use domain/repository policies, package permissions and upstream connections separately; developers should not have delete/overwrite rights by default.","Store tokens in managed credential mechanisms and encrypt package domains; restrict cross-account package sharing to named principals.","Audit package publishing, deletion, upstream configuration and repository policy changes."],"watchPoints":["Deleting a package version can break reproducible builds even when source code is unchanged.","Upstream availability and package-resolution rules can change the dependency graph.","A successful publish does not mean the artifact passed license, vulnerability or provenance checks."]},
"AWS CodeBuild":{"cost":["CodeBuild charges build minutes by compute type plus storage, logs, artifacts, cache, network and downstream pipeline services.","Over-provisioned compute and Docker-in-Docker builds can dominate; benchmark build minutes per artifact.","Retained logs, S3 artifacts, ECR pushes, NAT and dependency downloads belong in the estimate."],"optimization":["Choose compute type, build image, privileged mode, batch build and local cache from the build's actual compiler/container needs.","Use dependency caching and buildspec phases to reduce repeated work, but invalidate caches when lockfiles or base images change.","Use separate projects/roles for untrusted pull requests and trusted release builds."],"security":["Use a narrowly scoped service role and separate source, build, artifact and deployment permissions; do not grant project roles account-wide admin access.","Keep secrets in Secrets Manager/Parameter Store, encrypt artifacts and logs, and prevent build commands from echoing credentials.","Audit project environment, image, webhook, cache, artifact and privileged-mode changes."],"watchPoints":["A build can pass while publishing an incorrect artifact if tests, provenance or environment parity are missing.","Privileged mode expands the blast radius of a compromised build; use it only for container builds that require it.","Queued builds, account concurrency and cache corruption can look like source or compiler failures."]},
"AWS CodeDeploy":{"cost":["CodeDeploy has no separate deployment fee; EC2/ECS/Lambda, load balancers, artifacts, hooks, logs and test environments drive cost.","Blue/green temporarily doubles capacity and can increase load-balancer/data-transfer cost.","Include rollback retention, canary test traffic and idle deployment groups."],"optimization":["Choose in-place, blue/green, ECS, Lambda or EC2 deployment from connection draining, rollback speed and infrastructure ownership.","Use lifecycle hooks, deployment alarms and traffic shifting to verify application health, not just process startup.","Keep revisions immutable and make hooks idempotent; a retry or rollback can invoke them more than once."],"security":["Separate deployment, instance/service, artifact-bucket, load-balancer and rollback permissions; deployment roles should not own application data.","Protect deployment hooks, agent credentials, revision artifacts and lifecycle logs, and limit who can skip validation.","Audit application, deployment group, traffic-shift, alarm and rollback changes."],"watchPoints":["Deployment success is a control-plane result; alarm configuration decides whether bad application behavior is detected.","A hook timeout can leave mixed versions or trigger rollback while old capacity is draining.","Agent version, platform support and artifact permissions are common reasons a deployment never reaches the host."]},
"Amazon CodeGuru":{"cost":["Cost follows analyzed code/repositories and profiler runtime/usage; CI frequency and profiling coverage affect the estimate.","Repeated analysis of unchanged branches and always-on profiling can add cost without new signal.","Include storage, repository hosting, CI and remediation engineering effort."],"optimization":["Use CodeGuru Reviewer for change-time feedback and Profiler for runtime hotspot analysis; they answer different optimization questions.","Prioritize findings by reachability and business impact, and use profiling on representative workloads rather than constant broad collection.","Integrate findings into pull requests and operations without automatically blocking every low-confidence recommendation."],"security":["Separate profiler/reviewer access, repository integration and findings export permissions; source code and profiling data are sensitive.","Protect code-review, security-analysis and profiler artifacts, and control repository connections and token scopes.","Audit repository association, analyzer configuration, findings status and export changes."],"watchPoints":["A recommendation is evidence for review, not proof of a defect or performance regression.","Profiler data reflects the selected runtime window and traffic shape; idle or synthetic workloads can mislead.","Repository branch mapping and analyzer language support determine coverage."]},
"AWS CodePipeline":{"cost":["CodePipeline charges per active pipeline/month in the relevant pricing model; actions, CodeBuild, artifacts, logs, approvals and deploy targets add costs.","Unused or duplicate pipelines and retained artifacts create recurring cost.","Include cross-Region artifact stores, KMS, NAT, build minutes and test environments."],"optimization":["Use stages and action groups to express release gates, parallel tests and environment promotion; avoid serial stages that add no assurance.","Keep artifact names/versioning immutable and configure failure/rollback behavior for each deploy target.","Use cross-account roles and centralized pipelines only with clear ownership of the artifact and target account."],"security":["Use separate source, build, deploy and approval roles; a pipeline should not use one broad role for every action.","Protect connection tokens, artifact buckets, KMS keys and manual approval metadata, and use artifact encryption across accounts.","Audit pipeline, stage, action, connection, variable and execution changes."],"watchPoints":["A pipeline can be green while the deployed service is unhealthy if the action has no application-level validation.","Manual approvals can stall artifact retention and environment capacity.","Connections, webhook events, artifact permissions and cross-account role trust are separate failure points."]},
"AWS Tools and SDKs":{"cost":["The tools themselves may be free, but API calls, data transfer, build runners, logs, retries and downstream resources are not.","Aggressive retries can multiply API usage and create duplicate side effects.","Include artifact/package distribution, CI runners and observability in automation cost."],"optimization":["Reuse SDK clients, configure timeouts/retries/backoff from each service's idempotency and throttling behavior, and avoid creating a client per request.","Use paginators, waiters and batch APIs where provided; handle partial failures instead of assuming one API call is atomic.","Pin versions and test Region/partition endpoint behavior before upgrading a shared toolchain."],"security":["Use short-lived roles and credential providers, verify SDK signing/configuration and keep credentials out of source, profiles and CI logs.","Pin and scan dependencies, verify package provenance and restrict CLI/SDK permissions to the commands the automation needs.","Audit credential issuance, client configuration, dependency changes and automation execution."],"watchPoints":["SDK retry behavior differs by service and operation; idempotency tokens are not universal.","Credential provider order and environment/profile configuration can silently select the wrong account or Region.","A successful API response may represent an asynchronous operation that still needs polling and validation."]},
"AWS X-Ray":{"cost":["Cost follows traces/segments recorded and retrieved, plus CloudWatch/service integrations; sampling directly affects cost.","High-cardinality annotations and broad retrieval queries increase storage/query work.","Include agent overhead, log correlation, OpenTelemetry/ADOT components and downstream observability costs."],"optimization":["Use sampling rules to retain representative traces rather than tracing every request, and tune reservoir/rate by service criticality.","Instrument business-critical segments and downstream calls; adding SDK patching without interpreting async/queue boundaries creates misleading traces.","Use groups and annotations for targeted troubleshooting, not as a replacement for metrics and logs."],"security":["Use sampling and encryption/trace access policies to limit sensitive request metadata, and separate trace read, write and configuration roles.","Propagate trace headers only across trusted boundaries and redact user data from annotations/metadata.","Audit sampling rules, groups, encryption, service-map and trace-export changes."],"watchPoints":["X-Ray shows sampled traces, not every request; absence of a trace is not proof of absence of a failure.","Async queues and retries can create separate trace contexts and duplicate-looking segments.","Service-map edges depend on instrumentation and propagation, so investigate missing edges before blaming the dependency."]},
"Amazon AppStream 2.0":{"cost":["Cost follows fleet instance hours, user sessions, app blocks, storage, data transfer and directory services.","Always-on fleets trade launch latency for idle cost.","Include WorkSpaces/AD, S3, VPC endpoints, logs and application licensing."],"optimization":["Choose always-on, on-demand or elastic fleets from launch latency and utilization; use image builders and app blocks for repeatable delivery.","Tune instance type, fleet size, session timeout, user storage and autoscaling from concurrency and application behavior.","Separate persistent user settings from ephemeral session hosts."],"security":["Use fleets, stacks, user settings, image-builder, directory and S3 access roles separately; virtual sessions expose user data.","Encrypt application/user storage and restrict clipboard, file transfer, printing and network access according to data policy.","Audit image, fleet, stack, user-assignment and session-policy changes."],"watchPoints":["A healthy fleet can still fail launch because of image, entitlement, directory or subnet dependencies.","Session disconnect, user storage and termination behavior affect data loss.","Clipboard/file-transfer policy changes can alter the security boundary without changing the image."]},
"Amazon WorkSpaces":{"cost":["Cost follows desktop instance/running mode, storage, directory, public/private connectivity and data transfer.","Always-on and oversized bundles are common drivers.","Include WorkSpaces Web/AppStream, AD, NAT, CloudWatch and licensing."],"optimization":["Choose personal/pools, WorkSpaces type, running mode and bundle from persistence, concurrency and user experience.","Use auto-stop/always-on schedules, WorkSpaces Pools or application streaming where session behavior permits.","Separate profile/user data from desktop rebuild and test client/network latency."],"security":["Use directory, bundle, user, IP/access-control and client permissions separately; persistent desktops contain user data.","Encrypt volumes, snapshots and user storage and restrict restore/share operations.","Audit directory, bundle, user, connection and maintenance changes."],"watchPoints":["Desktop health does not guarantee access to corporate apps or directories.","Auto-stop, reconnect and user-volume behavior affect user experience and cost.","Directory/region availability and client network are separate failure domains."]},
"AWS Amplify":{"cost":["Cost follows build minutes, hosting/storage, data transfer, auth users and backend resources; previews multiply hosting/build use.","Large assets and frequent builds add transfer/storage.","Include CloudFront/S3, Cognito, AppSync/API Gateway, Lambda and databases."],"optimization":["Use Amplify Hosting for branch-based CI/CD and preview environments, but define promotion and rollback boundaries before connecting production domains.","Keep frontend assets cached and APIs/data services separately scalable; avoid hiding backend capacity behind a frontend deployment abstraction.","Use build caches, artifact retention and environment cleanup for ephemeral branches."],"security":["Separate Amplify project/deployment, hosting, build, auth and backend resource roles; frontend clients must not hold deployment credentials.","Protect environment variables, artifacts, branches, domain certificates and generated backend resources.","Audit app, branch, build, redirect, auth and environment changes."],"watchPoints":["A successful frontend build does not validate backend authorization or data contracts.","Environment variables and branch configuration can point a preview at production.","Generated infrastructure remains governed by the underlying service."]},
"Amazon API Gateway":{"cost":["Cost follows API type, requests, cache, WebSocket connections/messages, data transfer and logs; backend services are separate.","Authorizer/Lambda, Step Functions, DynamoDB and CloudWatch charges often exceed the API front door.","Include WAF, custom domains, certificates and private connectivity."],"optimization":["Use HTTP APIs when their feature set is sufficient and REST APIs when usage plans, transformations or advanced features are required.","Cache safe read responses with correct keys; use direct AWS service integration when it removes unnecessary Lambda work.","Tune payload size, authorizer caching, integration timeouts and route granularity from measured latency."],"security":["Choose IAM, JWT/Cognito, Lambda authorizer or resource policy deliberately; backend IAM permissions remain separate from client authorization.","Use throttling, quotas, request validation, WAF and private endpoints to protect the API boundary and backend.","Protect stage variables, authorizer caches, access logs and integration credentials."],"watchPoints":["REST, HTTP and WebSocket APIs have different features and pricing.","Throttling protects the gateway but does not automatically protect a database from every burst.","Private API reachability does not remove the need for authorization."]},
"AWS Device Farm":{"cost":["Cost follows device/browser minutes, test execution, concurrency, artifacts and network profiles; video/log retention adds storage.","Retries and broad device matrices multiply minutes.","Include CI, S3, device data transfer and backend test environments."],"optimization":["Choose real devices, remote browser or automated tests from coverage/risk; shard tests and select device pools intentionally.","Use test specs, retries and video/log capture only where they improve diagnosis; parallelism should match application/backend capacity.","Keep test environments isolated from production data and use representative but sanitized fixtures."],"security":["Protect device sessions, test artifacts, screenshots, app binaries and project access; test data may contain customer information.","Restrict device-pool, upload, network-profile and remote-access roles, and delete artifacts according to retention.","Audit project, test-run, device-pool, network and artifact changes."],"watchPoints":["A passing device test may reflect a fixture/backend state rather than production readiness.","Network profiles, device OS versions and app install state affect reproducibility.","Artifact retention and sensitive screenshots need privacy controls."]},
"Amazon Pinpoint":{"cost":["Cost follows messages/channel delivery, events, campaigns, segments and downstream analytics; SMS/email providers add separate cost.","High-frequency event ingestion and multi-channel fan-out multiply usage.","Include SES/SNS, Kinesis, S3, Lambda, analytics and consent systems."],"optimization":["Use event-driven journeys and segments from actual engagement signals; avoid broadcasting to stale endpoints.","Separate transactional from promotional messaging and tune frequency, quiet hours and channel fallback.","Use event metrics and suppression handling to close the delivery loop."],"security":["Separate project, endpoint, campaign, journey, template, segment and sending roles; customer attributes and events are sensitive.","Protect message templates, event streams, endpoints and channel credentials, and apply opt-out/consent controls.","Audit campaign, journey, segment, endpoint and event-destination changes."],"watchPoints":["Endpoint validity, consent, bounce and complaint state determine delivery.","Campaign success is not the same as message delivery or user engagement.","Region/channel availability and data residency affect design."]},
"AWS IoT Core":{"cost":["Cost follows messages, connections, rules, registry operations, shadows and downstream delivery; payload/frequency dominate.","Edge filtering and compact schemas reduce IoT Core and downstream cost.","Include Kinesis, Timestream, Lambda, S3, logs and carrier/network charges."],"optimization":["Choose MQTT/HTTP/WebSocket, QoS, retained messages, shadows and rules from device connectivity and command semantics.","Filter/enrich at the rule or edge and batch telemetry before sending; use device groups for fleet operations.","Design reconnect/backoff/offline behavior around intermittent networks and device resource limits."],"security":["Use per-device certificates, policies, thing groups, shadows and rules roles separately; never share a fleet credential.","Protect MQTT/TLS endpoints, retained messages, shadows and rule destinations with least privilege and encryption.","Audit certificate, policy, thing, rule and endpoint changes."],"watchPoints":["IoT Core routes device traffic; it does not make downstream databases or commands idempotent.","Certificate rotation, reconnect storms and retained-message behavior need testing.","Rules can fan out one message to many paid destinations."]},
"AWS IoT Device Defender":{"cost":["Cost follows audit checks, device metrics, detection data and downstream notification/remediation.","High-frequency metrics across large fleets increase ingestion and analysis cost.","Include IoT Core, EventBridge, Lambda, Security Hub and ticketing."],"optimization":["Use audits for configuration/policy posture and Detect for runtime anomalies; route each to a suitable owner.","Tune metrics and mitigation actions from fleet behavior to avoid blocking legitimate devices.","Automate certificate quarantine only with tested recovery and fleet-ownership workflows."],"security":["Protect audit configurations, detect metrics, mitigation actions and device certificates; Defender access must not grant device-control permissions.","Restrict ML detect data and findings, and audit who can suppress or remediate device violations.","Encrypt exported findings and control cross-account security operations."],"watchPoints":["A finding identifies anomalous behavior; it does not prove compromise without investigation.","Mitigation can disconnect or revoke a device and create an operational outage.","Device clock, certificate state and network path affect evidence."]},
"AWS IoT Device Management":{"cost":["Cost follows registry/index operations, jobs, commands, fleet provisioning and downstream data; fleet size/rollout frequency matter.","Repeated job retries and large artifacts add network/storage cost.","Include S3/CloudFront, IoT Core, KMS, Lambda and device connectivity."],"optimization":["Use dynamic thing groups and jobs for fleet-scale rollout, with rollout rates, abort criteria and retry behavior tied to device capacity.","Use secure provisioning and staged firmware deployment rather than manual per-device operations.","Design jobs for intermittent connectivity and resume behavior."],"security":["Separate fleet indexing, thing groups, jobs, provisioning templates and command permissions; operators should not control every device.","Protect job documents, firmware URLs, certificates and device metadata with signed artifacts and encryption.","Audit fleet, group, job, provisioning and command changes."],"watchPoints":["A job accepted by the service is not firmware installed; track device execution status.","Abort thresholds and rollout groups determine blast radius.","Certificate/provisioning and device time drift can block jobs."]},
"AWS IoT Events":{"cost":["Cost follows messages/inputs, detector evaluations, alarm actions and downstream services.","High-frequency noisy telemetry multiplies evaluations and notifications.","Include IoT Core, Lambda, SNS, SQS, Timestream and logs."],"optimization":["Model state machines with explicit thresholds, timers, acknowledgements and reset paths; use IoT Events for event-state logic rather than generic stream processing.","Filter and aggregate at the edge/rule path when raw telemetry is too noisy, and set detector instances from asset identity.","Use alarm actions that are idempotent and observable."],"security":["Protect detector models, input assets, alarm actions and rule destinations; detector state can represent operational conditions.","Separate authoring, runtime input and action permissions, and encrypt/limit event data/logs.","Audit detector, input, alarm and action changes."],"watchPoints":["Detector state can become stale when messages are lost or delayed.","Alarm acknowledgement/reset is separate from the physical condition returning to normal.","Input attributes and detector model versions must remain compatible."]},
"AWS IoT Greengrass":{"cost":["Cost includes device hardware, Greengrass cloud operations, IoT messaging, artifacts, S3/CloudFront and downstream services.","Frequent deployments and large component/model artifacts add transfer cost.","Include fleet monitoring, certificates, local storage and carrier connectivity."],"optimization":["Choose local shadow, stream manager, component, Lambda/container and ML runtime based on disconnected operation and edge latency.","Use local processing/filtering to reduce cloud traffic and continue safely offline, then reconcile when connected.","Stage component deployments with rollout/rollback configuration and device health signals."],"security":["Protect core-device provisioning, component artifacts, local secrets, token exchange and cloud roles; edge devices need isolated identities.","Sign/version component artifacts and encrypt local/cloud data; restrict component privileges and inter-component IPC.","Audit deployments, component versions, device groups and local debug access."],"watchPoints":["A device can be online to Greengrass while disconnected from AWS control services.","Component dependency/version and IPC permissions create local failure paths.","Offline state reconciliation and clock drift affect jobs and certificates."]},
"AWS IoT SiteWise":{"cost":["Cost follows measurements ingested, storage, queries, gateways, portal users and exports; asset/property count matters.","High-frequency raw retention and redundant telemetry are common drivers.","Include IoT Core, S3, Timestream, Kinesis, dashboards and gateway hardware."],"optimization":["Use asset models, transforms, aggregates and hierarchies to compute industrial KPIs near the source instead of repeatedly scanning raw telemetry.","Set gateway buffering, sync and data-quality behavior from plant connectivity; use portal/dashboard queries for operator needs.","Separate high-frequency measurements from long-term aggregates and alarms."],"security":["Protect asset models, gateways, measurements, dashboards and export roles; industrial telemetry can reveal plant operations.","Encrypt gateway/store data and restrict who can query, model or export measurements.","Audit asset/model/property/gateway and dashboard changes."],"watchPoints":["Gateway connectivity and measurement quality determine whether a KPI is trustworthy.","Asset-model changes can affect transforms and historical interpretation.","Timestamp, unit, quality and late-data behavior must be validated."]},
"AWS IoT Things Graph":{"cost":["Cost follows workflow executions, messages, integrations and connected device/cloud services.","Polling and retries multiply execution cost.","Include IoT Core, Lambda, Step Functions, S3 and device connectivity."],"optimization":["Use Things Graph for modeled device/workflow orchestration where supported; keep high-volume telemetry in purpose-built stream/time-series services.","Define device models, capabilities, steps, retries and timeouts explicitly and keep physical actions idempotent.","Separate orchestration from analytics and use event filtering before invoking flows."],"security":["Protect flow templates, device models, integrations and execution roles; a graph can invoke physical operations.","Restrict action endpoints, secrets and device credentials, and audit model/flow changes.","Protect workflow logs and state from broad access."],"watchPoints":["A graph step can succeed at the API level while the physical device has not completed the action.","Model/integration compatibility and timeout behavior define failure recovery.","The service is not a general substitute for all IoT orchestration patterns."]},
"AWS IoT 1-Click":{"cost":["Cost follows device/service usage, Lambda, IoT messaging, logs and downstream actions.","Repeated clicks/retries and retained logs add operational cost.","Include Lambda, EventBridge/SNS/SQS and connectivity."],"optimization":["Use 1-Click for simple managed-button actions, not fleet telemetry or complex stateful workflows.","Keep target Lambda actions short/idempotent and route longer work asynchronously.","Group placements and target ownership so operations can replace a device without changing business logic."],"security":["Protect device templates, placements, Lambda targets and user administration; a physical click can trigger cloud actions.","Restrict device ownership and target functions, and secure logs containing location/operational context.","Audit placement, device, project and target changes."],"watchPoints":["A click can be delivered more than once; target code must deduplicate.","Physical device battery/connectivity and Lambda permissions are separate failure points.","Device placement and target function mapping must be verified after replacement."]},
"Amazon Augmented AI":{"cost":["Cost follows human review tasks, workforce type, model invocations, S3/Lambda/SNS and task storage.","Large images/documents and low thresholds multiply human tasks.","Include Rekognition/Textract/SageMaker/Comprehend and reviewer operations."],"optimization":["Use A2I for defined low-confidence/exception paths rather than sending every inference to humans; threshold selection controls quality and cost.","Choose private, vendor or Cognito workforce from data sensitivity and review speed.","Make human-loop output idempotent and preserve model result, reviewer decision and provenance."],"security":["Protect human-loop input/output, worker access, task templates, Lambda triggers and SNS/S3 destinations; reviewed data may contain sensitive content.","Use private workforces, encryption and least privilege for work-team/task assignments.","Audit flow definitions, workforce, human-loop activation and output changes."],"watchPoints":["A human loop is asynchronous; inference acceptance and review completion are separate states.","Template/instruction quality directly affects label reliability.","Reviewer access and output retention need privacy controls."]},
"Amazon Comprehend":{"cost":["Cost follows text units, inference endpoints, training, asynchronous jobs, storage and data transfer; document size and page count matter.","Repeated preprocessing and always-on custom endpoints are common drivers.","Include S3, KMS, Lambda, Step Functions and redaction workflows."],"optimization":["Choose synchronous APIs for small text and asynchronous jobs for document collections; custom models need training/evaluation data representative of production.","Use batch APIs and language detection/segmentation before analysis to avoid repeatedly processing the same text.","Use custom entity/classifier endpoints only when managed model quality is insufficient, and scale endpoint capacity from traffic."],"security":["Use data-access roles and KMS controls for documents, endpoints, custom models and asynchronous output; redact sensitive text from logs.","Separate custom classification/entity-recognition training roles from runtime analysis roles.","Audit model, endpoint, job and output-bucket changes."],"watchPoints":["Supported languages, input-size limits and model versions differ by API.","Entity output can be probabilistic and should not become an authorization decision without validation.","Asynchronous job status and output location are separate from request acceptance."]},
"Amazon Comprehend Medical":{"cost":["Cost follows text units, asynchronous jobs, storage and downstream review/integration; long clinical notes and repeat processing drive usage.","Retention, de-identification, audit and secure transfer add cost beyond inference.","Include S3, KMS, EventBridge, Lambda and case-review systems."],"optimization":["Choose entity detection, protected-health-information detection, ICD/RxNorm linking and async processing from the clinical workflow; do not use generic Comprehend assumptions.","Batch documents and normalize formats before analysis, but preserve source offsets and provenance for review.","Use human validation for clinical decisions; the service extracts/links information and does not provide medical judgment."],"security":["Treat input, output and custom terminology as protected health information; restrict roles, encryption, retention and export destinations accordingly.","Use audit trails and access controls appropriate to HIPAA/regulated processing, and avoid sensitive text in application logs.","Separate service invocation from downstream clinical review and record access."],"watchPoints":["Medical terminology, confidence and linked-code availability vary by input and language.","PHI can persist in output files and logs even after the source is deleted.","Model output is assistive extraction, not a diagnosis or treatment decision."]},
"Amazon Fraud Detector":{"cost":["Cost follows training, batch/real-time predictions, storage and downstream review; event volume drives inference cost.","Frequent retraining and broad variable collection add cost.","Include Kinesis/S3, Lambda, API Gateway, DynamoDB and case management."],"optimization":["Choose supervised model, rules, outcomes and detector versions from the fraud decision process; separate investigation from automated decline.","Use entity/event variables that are available at decision time and monitor drift as fraud patterns change.","Version rules/models and stage thresholds before changing customer-impacting decisions."],"security":["Protect event datasets, labels, models, detector versions, outcomes and real-time prediction roles; fraud signals are sensitive.","Encrypt training/inference data and restrict model/deploy/variable permissions by business role.","Audit detector, model version, batch prediction and variable changes."],"watchPoints":["Model score is evidence for a decision, not a guarantee of fraud.","Label delay and concept drift make recent performance look incomplete.","Threshold changes can alter decline/approval rates and customer harm."]},
"Amazon Kendra":{"cost":["Cost follows index edition/capacity, query and connector activity, storage and data transfer; index size and refresh cadence are material.","Repeated full crawls and unused indexes create persistent cost.","Include S3/SharePoint connectors, KMS, CloudWatch and downstream Q Business/Bedrock."],"optimization":["Choose Kendra GenAI Enterprise/Developer edition and connector sync cadence from corpus size, query concurrency and freshness requirements.","Use relevance tuning, facets, metadata filters and user-context tokens before adding custom downstream generation.","Separate ingestion and query paths and monitor failed documents, ACL sync and answer quality."],"security":["Use index, data-source, query, feedback and experience roles separately; document ACLs must be synchronized for security-trimmed answers.","Protect index content, query logs, feedback and connector credentials with KMS and controlled storage.","Audit index, data-source, query, relevance and access changes."],"watchPoints":["Kendra can return no answer or the wrong answer when ACLs, metadata or connectors are stale.","Connector-specific crawling, parsing and permission behavior differs.","Index capacity and query latency are separate from source-system availability."]},
"Amazon Lex":{"cost":["Cost follows text/audio requests, streaming duration, Lambda fulfillment, CloudWatch logs and connected backend services.","Long audio sessions and repeated fallback/reprompt loops increase usage.","Include Connect, Kendra, Bedrock, Polly, Transcribe and backend API costs."],"optimization":["Use intents, slots, confirmation prompts, fallback and conversation branching to keep the dialog deterministic before adding Lambda logic.","Choose text/audio/streaming APIs from channel needs and design session timeout/reprompt behavior explicitly.","Use aliases and staged bot versions for rollback; keep fulfillment idempotent."],"security":["Separate bot build, alias deployment, runtime invocation, Lambda fulfillment and user data permissions.","Protect slot values, conversation logs, audio/text input and session attributes; redact PII before logging.","Audit bot version, locale, intent, slot, alias and fulfillment changes."],"watchPoints":["Bot confidence and fallback behavior determine customer experience more than raw invocation success.","Locale, slot elicitation and Lambda timeout differences can create unexpected branches.","Session attributes may carry sensitive or stale context between turns."]},
"Amazon Nova":{"cost":["Cost follows input/output tokens or modality-specific units, model choice, customization, guardrails and transfer.","Large media and repeated context can dominate text-token assumptions.","Include S3, Bedrock orchestration, KMS, logs and downstream review."],"optimization":["Choose Nova model/modality from latency, reasoning, text/image/video/audio quality and context needs; benchmark the actual task.","Use multimodal input only where it improves the workflow, and limit context/media resolution to the decision need.","Separate model evaluation, routing, guardrails and application tools."],"security":["Apply model invocation, customization, guardrail, knowledge and logging controls to the specific Nova model and modality used.","Protect prompts, images, video, audio, training data and outputs; restrict cross-Region/model-access roles.","Audit model/version, inference-profile, customization and evaluation changes."],"watchPoints":["Model/version behavior and modality support can vary by Region.","Multimodal output needs validation for grounding and sensitive content.","Nova response success does not establish business correctness."]},
"Amazon PartyRock":{"cost":["Cost/usage follows underlying model inference and shared app activity; uploaded data, storage and downstream services may add cost.","Public/shared experimentation can multiply unpredictable calls.","Include Bedrock, S3, logs and production migration work."],"optimization":["Use PartyRock for rapid prototyping and learning; move production workloads to governed Bedrock applications with explicit IAM and deployment controls.","Keep app inputs bounded and test prompt injection, output quality and model behavior before reuse.","Capture useful prompt/model configuration as versioned application artifacts rather than relying on an interactive prototype."],"security":["Treat PartyRock apps, prompts, uploaded data, sharing and generated outputs as potentially public/user-visible; avoid confidential data.","Restrict sharing and inspect app access, content filters and data retention before demonstrating externally.","Audit app, prompt, data and share changes."],"watchPoints":["PartyRock prototype sharing is not equivalent to enterprise application authorization.","Generated content still requires review and data-classification controls.","Model availability and app behavior can change as the platform evolves."]},
"Amazon Personalize":{"cost":["Cost follows data import, training, campaign capacity, inference requests, event ingestion and storage.","Always-on campaigns and frequent retraining can dominate low-volume workloads.","Include Kinesis/streams, S3, Lambda, API integration and experiment analysis."],"optimization":["Choose user-personalization, item recommendation, ranking or related-items recipe from the decision problem; recipe selection changes data requirements.","Use event tracking for fresh signals, batch inference for offline catalogs and filters for business constraints without retraining.","Retrain and deploy versions from measured interaction quality; do not scale campaign capacity before checking data sparsity."],"security":["Restrict dataset groups, schemas, import roles, campaigns, filters and recommendation APIs; training data and user events can be sensitive.","Encrypt datasets, solutions, campaigns and event data and control S3 import/export roles.","Audit dataset, solution-version, campaign, filter and event-tracking changes."],"watchPoints":["Cold-start users/items and sparse feedback produce different quality problems than serving latency.","Filters can remove all candidates even when the model is healthy.","Solution version, campaign deployment and event schema must align."]},
"Amazon Polly":{"cost":["Cost follows characters synthesized, engine/voice and asynchronous storage/transfer; repeated dynamic text drives usage.","Audio caching and batch generation can reduce repeated calls.","Include S3, CloudFront, Connect, KMS and transcription/translation pipelines."],"optimization":["Choose standard/neural/generative/conversational voice and synchronous/asynchronous API from quality, latency and text length.","Cache reusable speech and select codec/sample rate to match the channel; do not synthesize the same static prompt per request.","Use SSML and lexicons for pronunciation control, but validate that markup does not create unsafe or incorrect output."],"security":["Protect text, lexicons, generated audio and asynchronous S3 outputs; restrict speech synthesis roles and redact sensitive text from logs.","Use IAM and KMS for lexicon/object access and separate application invocation from audio distribution.","Audit lexicon, voice, engine, output-format and task changes."],"watchPoints":["Voice, language, engine and SSML support vary; fallback voices can change pronunciation.","Generated audio is an output asset with its own retention and access policy.","Speech synthesis does not verify the truth or sensitivity of input text."]},
"Amazon Rekognition":{"cost":["Cost follows images, video minutes, face storage/search, custom training/inference and streaming; resolution/frame rate affect usage.","Repeated frame analysis and retaining collections/media can dominate cost.","Include S3, Kinesis Video Streams, Lambda, CloudFront, KMS and review tooling."],"optimization":["Choose image APIs, Custom Labels, Face Liveness, stored video or streaming analysis from latency and evidence requirements.","Use quality filters, region-of-interest, confidence thresholds and human review rather than processing every frame at maximum scope.","Store only the face/label metadata needed for the use case and expire source media according to policy."],"security":["Separate collection/index, image/video analysis, face-search and project roles; biometric data requires strict purpose and retention controls.","Encrypt collections, face metadata, source media and outputs, and restrict cross-account access and logs.","Audit collection, model/project, stream, label and deletion changes."],"watchPoints":["Recognition confidence is not identity proof or authorization by itself.","Face collection quality, false matches and demographic performance require evaluation for the use case.","Video stream lag, dropped frames and model/version changes affect findings."]},
"Amazon SageMaker AI":{"cost":["Cost follows training/processing instance time, endpoint capacity, serverless requests, storage, data transfer and monitoring.","Idle endpoints, large model loading and repeated preprocessing are frequent drivers.","Include S3, ECR, CloudWatch, VPC endpoints, Feature Store and orchestration."],"optimization":["Choose processing, training, batch transform, real-time/serverless inference and async inference from latency and volume.","Tune instance type, autoscaling, multi-model endpoints, data formats and distributed training from measured utilization.","Use registry/pipeline approval gates and version data, code, model and inference image together."],"security":["Separate data, processing, training, model registry, endpoint and monitoring roles; notebook users should not receive production deployment authority.","Use VPC-only networking where required, encrypt volumes/artifacts/endpoints and keep secrets out of notebooks.","Audit jobs, lineage, models, endpoints, Studio and pipeline changes."],"watchPoints":["A healthy endpoint does not prove model quality, feature freshness or drift control.","Startup/image-pull/model-load time can dominate tail latency.","Reproducibility fails when data, code, model artifact and container versions are not linked."]},
"Amazon Textract":{"cost":["Cost follows pages and feature APIs; queries, adapters and video/async processing have additional dimensions.","High-resolution multi-feature analysis and retries increase page cost.","Include S3, SNS/SQS, Lambda, KMS and human review."],"optimization":["Choose synchronous Detect APIs for small pages and asynchronous Analyze/Start APIs for multi-page documents; use Queries/Adapters only when the form/domain requires them.","Preprocess page images for orientation/quality and use feature-specific APIs rather than sending every document through every analysis.","Validate bounding boxes, confidence and table/form structure before writing extracted values to systems of record."],"security":["Restrict document buckets, asynchronous jobs, queries, adapters and output roles; scanned documents can contain identity and financial data.","Encrypt input/output and redact sensitive content from logs; use least privilege for SNS/SQS job notifications.","Audit adapter, job, query, bucket and output changes."],"watchPoints":["OCR confidence is not business validation; totals, IDs and signatures require rule or human checks.","Asynchronous job completion and output delivery are separate from request acceptance.","Page limits, file formats, rotation and adapter versions affect extraction."]},
"Amazon Transcribe":{"cost":["Cost follows audio seconds, streaming duration, language/model features and storage/transfer; long silence and reprocessing increase usage.","Call analytics and medical features add distinct pricing and retention requirements.","Include S3, Kinesis/Connect, Lambda, KMS, Comprehend and search."],"optimization":["Choose batch, streaming, call analytics or medical transcription from latency, speaker and domain requirements.","Use channel identification, speaker labels, custom vocabulary and language identification only when their quality benefit is demonstrated.","Store audio/transcripts with lifecycle rules and validate timestamps before downstream indexing or sentiment analysis."],"security":["Protect audio, transcripts, custom vocabularies/models and output buckets; recordings can contain regulated personal data.","Use KMS, bucket policies and redaction controls and separate streaming from batch invocation roles.","Audit vocabulary/model, job, channel-identification and output changes."],"watchPoints":["Transcript confidence and diarization vary with noise, overlap and language; do not treat text as exact evidence without validation.","Vocabulary/model changes can alter historical comparability.","Streaming partial results and final results have different completeness semantics."]},
"Amazon Translate":{"cost":["Cost follows characters translated, batch documents, custom terminology/parallel data and storage/transfer.","Repeated translation of unchanged content and verbose source formats increase usage.","Include S3, Step Functions/Lambda, Comprehend, KMS and review systems."],"optimization":["Choose real-time or batch translation from latency and document volume; custom terminology should solve domain terms rather than replace language quality evaluation.","Detect source language and preserve markup/formatting deliberately; validate supported language pairs before designing fallback.","Cache stable translations and use human review for regulated or customer-facing text."],"security":["Restrict document, real-time, custom terminology and parallel-data permissions; translated text may contain sensitive business content.","Encrypt batch inputs/outputs and terminology assets and control S3/Lambda integration roles.","Audit terminology, parallel-data, batch job and output changes."],"watchPoints":["Language support, dialect and terminology behavior vary by direction.","Translation preserves meaning imperfectly; it is not a legal/medical approval control.","Batch job acceptance, completion and output validation are separate states."]},
"Amazon Elastic Transcoder":{"cost":["Cost follows transcoded minutes/resolution, presets, storage, requests, transfer and distribution; outputs multiply storage.","High-resolution multi-bitrate ladders can dominate processing/storage.","Include S3, SNS, Lambda, Media services and CloudFront."],"optimization":["Choose preset/container/codec/resolution from playback devices and bandwidth; use the current media-service alternative where its feature set fits.","Batch jobs and output naming should be idempotent, with thumbnails/captions/audio tracks managed as related artifacts.","Use S3 lifecycle and CloudFront distribution for output retention/delivery rather than keeping all transcodes hot."],"security":["Protect pipelines, presets, input/output buckets and SNS notifications; media often contains customer or licensed content.","Encrypt media and restrict bucket/preset access, and keep output distribution separate from processing roles.","Audit pipeline, preset, job and notification changes."],"watchPoints":["Job acceptance and playable output validation are separate states.","Codec/container compatibility and source corruption create failures outside the pipeline API.","Service availability/feature direction should be reviewed before new platform dependency."]},
"Amazon Kinesis Video Streams":{"cost":["Cost follows video ingestion, storage/retention, playback/streaming, signaling and transfer; camera count/bitrate dominate.","Long retention and repeated playback increase storage/egress.","Include Rekognition, S3, Lambda, Media services and network."],"optimization":["Choose media retention, fragment duration, WebRTC signaling and HLS/DASH consumption from real-time versus playback needs.","Use producer timestamps, codecs and fragment sizing appropriate to camera/network behavior; avoid storing raw video indefinitely.","Separate live viewing, analytics and archive paths so each uses the right consumer and retention."],"security":["Use stream, producer, consumer, parser and archived-media permissions separately; video may contain sensitive imagery/audio.","Encrypt streams, fragments and archived media, and restrict WebRTC signaling and endpoint access.","Audit stream, retention, signaling and consumer changes."],"watchPoints":["Fragment gaps, clock drift and codec incompatibility affect playback/analytics.","WebRTC signaling success does not guarantee media path connectivity.","Retention and consumer lag determine whether a camera incident remains recoverable."]},
"AWS CloudFormation":{"cost":["CloudFormation has no general template charge; resource, artifact-bucket, logs and deployment pipeline costs apply.","Nested stacks, retained artifacts and repeated failed changes add storage/compute cost.","Include custom resources, Lambda, CodeBuild, S3, KMS and cross-account execution."],"optimization":["Use nested stacks/modules for clear boundaries, but avoid tightly coupled stacks that prevent independent rollback.","Use change sets and drift detection to expose replacement risk; model dependencies explicitly.","Set retain/delete policies deliberately and use stack policies for stateful resources."],"security":["Use change sets, stack policies, service roles and least-privilege deployment roles; protect termination protection for data resources.","Keep parameters, templates, nested-stack outputs and artifact buckets free of secrets; use dynamic references.","Audit stack, drift, change-set and replacement events and retain the exact template/parameters that created each resource."],"watchPoints":["CREATE_COMPLETE is not application health.","A property change can replace a resource and data.","Custom-resource timeouts and drift can leave infrastructure in a partial state."]},
"AWS CloudTrail":{"cost":["Cost follows management/data/network events, CloudTrail Lake ingestion/storage/query and S3/KMS; data events are the common driver.","Broad organization-wide S3/Lambda data-event logging can multiply volume.","Include EventBridge, Security Hub, SIEM and query/retention storage."],"optimization":["Use organization trails for governance, add high-value data events and Insights where they answer a detection question.","Lifecycle S3 logs and centralize only required events; use Lake when query/retention benefits justify the model.","Partition evidence and correlate with service-native logs rather than enabling every event everywhere."],"security":["Use organization trails and event selectors deliberately; protect the S3 destination, log-file validation and KMS key from workload administrators.","Separate management, data, network and Insights events based on investigation needs and sensitive-data exposure.","Restrict CloudTrail Lake event-store queries and retention, and audit trail/configuration changes."],"watchPoints":["A healthy trail can still omit the data event needed to explain an object/function change.","Region, account, event selector and service support determine evidence coverage.","Delivery delay and digest validation matter during incident response."]},
"Amazon CloudWatch":{"cost":["Cost follows custom metrics, logs ingestion/storage/query, alarms, dashboards, traces and synthetics; cardinality/retention matter.","Verbose application logs and long retention dominate many accounts.","Include subscription filters, Firehose, OpenSearch, S3 and alert destinations."],"optimization":["Use high-cardinality dimensions only for an operational decision; otherwise cost and query complexity grow.","Choose alarms, anomaly detection, dashboards and Logs Insights queries around actionable signals.","Use cross-account observability to centralize views while keeping source-account ownership."],"security":["Separate metric/alarm/dashboard/log/trace administration from viewing and data access; dashboards can expose sensitive operational details.","Encrypt and retain telemetry according to sensitivity and restrict cross-account observability links.","Audit alarm, metric-filter, dashboard, agent, subscription and log-group changes."],"watchPoints":["A missing metric or disabled alarm creates false confidence without changing workload behavior.","Namespace/dimensions must match alarm queries exactly.","Logs, metrics, traces and synthetics have different latency and retention semantics."]},
"Amazon CloudWatch Logs":{"cost":["Cost follows ingestion, storage, Logs Insights scans, Live Tail, subscriptions and export destinations.","High-cardinality verbose logs and indefinite retention are common drivers.","Include KMS, Firehose, OpenSearch, S3 and SIEM processing."],"optimization":["Set retention by investigation/compliance need, use metric filters only for actionable patterns and route high-value logs to a suitable analytics store.","Use structured logs and correlation IDs instead of duplicating large payloads across every line.","Subscription filters, Firehose and Logs Insights should be designed from the incident/query workflow."],"security":["Use log-group resource policies, KMS keys, subscription destinations and cross-account observability roles separately.","Redact credentials/PII before ingestion and restrict who can query/export log groups.","Audit retention, subscription, metric-filter, resource-policy and data-protection changes."],"watchPoints":["A log group can receive records while a subscription or metric filter is failing.","Retention deletion and export are separate lifecycle behaviors.","A log query scans stored data; query volume can become a material cost."]},
"AWS CLI":{"cost":["CLI is not normally billed; API calls, data transfer, logs, build runners and created resources are.","Polling loops and aggressive retries increase API traffic.","Include CI agents, S3 downloads/uploads, CloudTrail and downstream services."],"optimization":["Use paginators, waiters, JMESPath filtering and idempotency-aware retries; do not assume a CLI command means the resource is ready.","Pin CLI versions and profiles, specify Region/account explicitly and use `--dry-run`/change sets where supported.","Move repeatable multi-resource work to reviewed IaC or scripts with tests."],"security":["Use named profiles/roles, SSO and credential-process controls; never store long-lived keys in scripts or shell history.","Restrict command permissions, protect output files and disable debug logging when payloads contain secrets.","Audit CloudTrail API actions and CI runner identity/source."],"watchPoints":["CLI success often means request accepted, not asynchronous completion.","Profile/Region/account context is a common operator error.","Output schemas and option behavior can change between versions."]},
"AWS Compute Optimizer":{"cost":["Optimizer itself has feature/scope considerations; savings or costs come from the resource changes, monitoring, storage and test capacity.","Rightsizing can reduce cost but increase throttling, cold starts or recovery time.","Include CloudWatch metrics, Savings Plans, Auto Scaling and rollback capacity."],"optimization":["Use recommendations for EC2, EBS, Lambda, ECS/Fargate and related resources only after validating workload seasonality and performance objectives.","Compare utilization, memory, I/O, throttling and latency rather than accepting the cheapest recommendation blindly.","Stage changes and monitor after resize; recommendations are advisory and depend on collected metrics."],"security":["Limit organization-wide inventory, recommendation and export access; recommendations expose utilization and resource configuration.","Protect recommendation exports and automation roles; do not allow an optimizer role to resize production without approval.","Audit enrollment, preference, export and resource-change actions."],"watchPoints":["Sparse or unrepresentative metrics produce misleading recommendations.","A smaller instance can improve price but violate latency or failover objectives.","Recommendations can lag after a workload or architecture change."]},
"AWS Config":{"cost":["Cost follows configuration items, rule evaluations, conformance packs, aggregators and S3/SNS delivery; recording scope is the main driver.","Duplicate rules and frequent changes increase evaluations.","Include remediation Lambda/SSM, CloudTrail, S3 and notification costs."],"optimization":["Record only required resource types/Regions and use conformance packs for repeatable governance; broad recording has cost and noise implications.","Use proactive rules/templates where available and route noncompliance to owners before enabling remediation.","Aggregate organization data centrally while preserving account-level remediation ownership."],"security":["Separate recorder, delivery channel, rule, conformance-pack and remediation permissions; Config data can reveal full resource topology.","Protect configuration snapshots/history and remediation roles; auto-remediation must not have unrestricted destructive permissions.","Audit recorder, rule, aggregator and delivery changes."],"watchPoints":["A compliant Config rule does not prove application behavior or data correctness.","Missing recorder permissions or delivery failures create silent compliance gaps.","Auto-remediation can conflict with deployment or break dependencies if ownership is unclear."]},
"AWS Control Tower":{"cost":["Control Tower has service and underlying Organizations/Config/CloudTrail/S3/IAM Identity Center costs; every enrolled account multiplies telemetry.","Control execution and log retention grow with account/Region scope.","Include shared services, audit account, network, support and remediation automation."],"optimization":["Use Control Tower for governed multi-account baseline and Account Factory; keep workload-specific resources in member-account IaC.","Choose preventive/detective controls from a real policy objective and test exceptions before organization-wide rollout.","Use lifecycle events and drift remediation rather than manually editing enrolled accounts."],"security":["Protect landing-zone, guardrail, account-factory, IAM Identity Center and delegated-administrator roles; central governance can affect every account.","Secure audit/log archive accounts and organizational policies, and restrict changes to landing-zone configuration.","Audit controls, account enrollment, drift and lifecycle changes."],"watchPoints":["Landing-zone drift can make new accounts appear governed while controls are incomplete.","Control Tower guardrails can block valid deployments when OU scope is too broad.","Account enrollment, Region governed list and identity provisioning are separate phases."]},
"AWS Cost Anomaly Detection":{"cost":["The service analyzes cost/usage data; charges and savings depend on the resources and notification/storage path it covers.","Granular monitors and broad subscriber fan-out increase operational noise and integration cost.","Include SNS, email, Lambda, EventBridge and CUR/analytics."],"optimization":["Create monitors around meaningful linked accounts, services, cost categories or tags; one giant monitor obscures ownership.","Use alert thresholds and feedback windows suited to billing latency, then route anomalies to an accountable owner.","Combine anomaly detection with Cost Explorer/CUR investigation rather than automating destructive remediation."],"security":["Restrict monitor, subscription, forecast and alert-recipient permissions; cost data can reveal account/workload activity.","Protect alert destinations and do not put sensitive resource dimensions into broad notifications.","Audit monitor, dimension, threshold and subscriber changes."],"watchPoints":["Billing data is delayed and anomaly detection is not a real-time budget guard.","A cost spike can be legitimate growth, commitment purchase or delayed allocation.","Dimensions/tags and shared costs affect attribution."]},
"AWS Health Dashboard":{"cost":["Health Dashboard itself is an operational signal; notification, EventBridge, logs and incident systems create indirect cost.","Broad organizational exports and retention add storage/processing.","Include support plan and incident tooling."],"optimization":["Use account/organization events, affected resources and planned lifecycle events to prioritize workload-specific response; do not treat every public event as an account outage.","Integrate EventBridge/notifications with incident ownership and suppress duplicate pages.","Use service/Region/account context to correlate Health with CloudWatch and application evidence."],"security":["Restrict organizational Health access and event-view/export permissions; events expose account/service availability context.","Protect event exports, affected-resource lists and notification destinations.","Audit delegated administration, organizational view and event subscriptions."],"watchPoints":["AWS Health event visibility and application impact are different questions.","Planned lifecycle events require action before the event time.","Account/organization scope and permissions determine what operators can see."]},
"AWS License Manager":{"cost":["Cost follows License Manager features and underlying licensed resources, discovery, reporting and remediation; commercial license fees dominate.","Unused or mis-scoped entitlements create compliance and spend risk.","Include discovery agents, SSM, Organizations, reporting and vendor audits."],"optimization":["Use license configurations and automated discovery to prevent unmanaged consumption; model host/resource association from the product terms.","Set hard/soft limits and notification/remediation according to business tolerance.","Integrate with EC2, RDS, Systems Manager and Organizations for actual inventory."],"security":["Protect license configurations, grants, associations, user subscriptions and delegated administration; licensing data is contractual.","Encrypt/report license inventories and restrict cross-account sharing and automation roles.","Audit license rules, entitlements, associations and compliance changes."],"watchPoints":["Inventory can lag resource creation or fail when tags/agents are missing.","A compliance violation may require legal/vendor action, not automatic termination.","License rules differ by product metric, Region and host tenancy."]},
"Amazon Managed Grafana":{"cost":["Cost follows workspace hours/edition, users, data sources, query/alert traffic and underlying telemetry storage.","Unused workspaces and verbose dashboards create fixed and query cost.","Include AMP/CloudWatch/OpenSearch, VPC endpoints, logs and notification services."],"optimization":["Use AMP, CloudWatch, X-Ray, OpenSearch or other sources according to query/retention needs; do not duplicate telemetry unnecessarily.","Use folders/teams/permissions and recording rules to control query load and ownership.","Tune dashboards and alerts to actionable signals; high-cardinality panels can overload sources."],"security":["Use workspace SSO, data-source permissions, IAM roles and dashboard sharing separately; a dashboard can expose data across accounts.","Protect API keys, secrets, alert contact points and workspace logs with KMS/Secrets Manager.","Audit workspace, plugin, data-source, folder, dashboard and alert changes."],"watchPoints":["Grafana visualizes source data; source permissions, freshness and retention remain authoritative.","A dashboard can be stale while workspace health is green.","Plugin/version and cross-account role changes affect query failures."]},
"Amazon Managed Service for Prometheus":{"cost":["Cost follows metric samples ingested, storage/retention, queries, alerts and collectors; label cardinality drives ingestion.","Cross-account/Region querying and long retention add transfer/storage cost.","Include EKS/ECS collectors, Grafana, CloudWatch and notification paths."],"optimization":["Use service discovery/collectors, recording rules and label hygiene to control cardinality; do not remote-write every ephemeral label.","Choose retention, workspace topology and query federation from the monitoring need; use AMP for Prometheus semantics, not every log/event.","Set scrape intervals and shard/collector capacity from target count and metric volume."],"security":["Use workspace IAM/resource policies, SigV4/agent roles, collector permissions and alert/recording-rule access separately.","Protect metrics, remote-write credentials, alert destinations and cross-account queries.","Audit workspace, collector, rule, alert-manager and logging changes."],"watchPoints":["Prometheus samples are time-series observations; missing scrape data can look like zero unless queries account for absence.","High-cardinality labels can create cost and query instability.","Alert rules, recording rules and Alertmanager delivery have different failure paths."]},
"AWS Management Console":{"cost":["The console has no generic resource charge; actions initiated through it create the same service, data, logging and transfer costs as APIs.","Manual exploration can create forgotten resources and spend.","Include CloudTrail, MFA/IdP and support operations."],"optimization":["Use the console for exploration and controlled operations, but move repeatable changes to reviewed IaC/CLI/SDK workflows.","Use resource views/tags and service-specific dashboards to reduce manual drift.","Keep break-glass procedures tested and time-bound."],"security":["Use federation, IAM Identity Center, MFA and permission boundaries; never treat console access as a separate authorization model.","Restrict console session duration, browser/device access, support/billing roles and CloudShell/embedded service actions.","Audit sign-in, console actions and assumed-role sessions with CloudTrail."],"watchPoints":["Console success can hide asynchronous service failure; check the underlying resource state and events.","Browser session, Region and account context are common operator errors.","Manual changes create drift from IaC unless captured."]},
"AWS Organizations":{"cost":["Organizations itself may have limited direct cost, but account/OU-wide Config, CloudTrail, Control Tower, Backup and security services multiply spend.","Unused accounts and duplicated shared services create recurring governance cost.","Include management, audit, log archive and network-account resources."],"optimization":["Design OUs around policy boundaries and lifecycle, not only business reporting; keep SCPs narrow and testable.","Use tag policies and backup/access policies where they solve a defined governance problem, and stage SCP changes with simulation.","Centralize controls while allowing workload teams to own resource configuration within the boundary."],"security":["Use SCPs, delegated administration, account tags, root controls and management-account access separately; SCPs do not grant permissions.","Protect the management account, break-glass roles, billing access and organization-wide CloudTrail/log archives.","Audit account, OU, policy, delegated-service and tag changes."],"watchPoints":["SCPs limit maximum permission but do not grant actions.","A policy applied to an OU can break dependencies across many accounts.","Management-account and delegated-admin failure paths need independent recovery."]},
"AWS Proton":{"cost":["Proton itself has no generic application capacity cost; provisioned ECS/EKS/Fargate, pipelines, artifacts, logs and networking are billed.","Template updates can trigger fleet-wide rollout and temporary duplicate capacity.","Include CodePipeline/CodeBuild, ECR, CloudFormation, KMS and observability."],"optimization":["Use Proton templates for standardized infrastructure/app patterns while exposing only safe configurable parameters.","Version templates and environment definitions, validate rollbacks and keep platform upgrades separate from service deployment.","Use deployment pipelines and environment groups that match ownership and failure domains."],"security":["Separate template, environment, service, deployment and pipeline roles; tenant teams should not alter platform guardrails.","Protect templates, source repositories, pipeline artifacts, environment variables and secrets.","Audit template versions, service instances, deployments and environment changes."],"watchPoints":["A template can render valid infrastructure but still violate application SLOs.","Environment and service deployments have separate state and rollback behavior.","Template compatibility and parameter defaults affect every consumer."]},
"AWS Service Catalog":{"cost":["Service Catalog cost is mostly the provisioned products and their CloudFormation/resources; portfolios, artifacts, logs and approvals add indirect cost.","Old product versions, retained artifacts and unused provisioned products accumulate.","Include CloudFormation, S3, KMS, CodePipeline and support workflows."],"optimization":["Use products/portfolios to offer governed patterns instead of copying templates across teams; version products and retire unsafe versions.","Use launch constraints and tag options to separate end-user permission from provisioning permission.","Design update/terminate behavior and resource ownership before allowing self-service."],"security":["Use portfolios, products, constraints, launch roles and tag options to control who can deploy which approved resources.","Protect product templates, artifact buckets and launch constraints; product access must not expose template secrets.","Audit product versions, associations, constraints, provisioned products and termination changes."],"watchPoints":["A product can launch successfully while the application pattern is operationally wrong.","Constraint resolution and launch-role trust can fail separately from end-user access.","Updating a product version does not automatically update existing provisioned products."]},
"AWS Service Quotas":{"cost":["Service Quotas has little direct cost; quota-driven overprovisioning, support workflows and idle capacity affect spend.","Quota requests can enable larger architecture cost, so approvals need capacity/cost review.","Include CloudWatch alarms and inventory automation."],"optimization":["Review quotas before deployment and design around regional/resource-specific limits rather than assuming account-wide capacity.","Request increases early and build graceful backpressure/partitioning where increases are unavailable.","Track quotas for APIs, ENIs, IPs, endpoints, instances, Lambda concurrency and managed services relevant to the workload."],"security":["Restrict quota-view/request permissions and protect support/approval workflows; quota data reveals account scale and architecture.","Audit quota requests, increases and service-linked changes.","Use least privilege for automation that requests or consumes quota changes."],"watchPoints":["A quota increase is not guaranteed and may differ by Region or account.","Service default quotas change and some limits are not adjustable.","Quota utilization can be hidden behind a managed service abstraction."]},
"AWS Systems Manager":{"cost":["Cost varies by advanced parameters, automation/ops items, messages, hybrid activations and underlying logs/compute; many core capabilities are not billed separately.","High-frequency associations, command output and cross-account operations add cost.","Include CloudWatch, S3, KMS, Lambda, hybrid connectivity and patch repositories."],"optimization":["Use State Manager/Automation for repeatable configuration and Session Manager instead of inbound SSH; scope documents and targets by tags.","Choose patch baselines, maintenance windows and concurrency/error thresholds from fleet criticality.","Use Parameter Store for configuration/standard parameters and Secrets Manager for secrets/rotation requirements."],"security":["Separate managed-node, Run Command, Automation, Patch Manager, Parameter Store and Session Manager permissions; operators should not receive unrestricted shell access.","Encrypt parameters, session data, command output and automation artifacts, and restrict documents and attachments.","Audit documents, associations, commands, sessions, patch baselines and parameter changes."],"watchPoints":["A command can be delivered but fail at the OS/application layer.","Automation concurrency and approvals affect blast radius.","Parameter versioning, agent health, IAM instance profile and network endpoint access are separate dependencies."]},
"AWS Trusted Advisor":{"cost":["Availability and depth of checks depend on support/feature plan; remediation services and resources create the actual cost.","Cost optimization recommendations may require commitments or resizing that alter availability.","Include Cost Explorer, Compute Optimizer, Security Hub, Config and ticketing."],"optimization":["Use Trusted Advisor for account-level checks and prioritize by business impact; it is not a substitute for service-specific metrics or Well-Architected review.","Group recommendations by owner and use automation only for deterministic low-risk cleanup.","Recheck after architecture changes and document accepted risk/exceptions."],"security":["Restrict checks, recommendations, support-plan data and notification access; recommendations expose account configuration and spend.","Protect exports and automation that acts on recommendations; a cost/security recommendation should not directly mutate production without review.","Audit check configuration, exclusions, notifications and delegated access."],"watchPoints":["Recommendation freshness and support-plan scope affect confidence.","A recommendation is not an automatic change plan; validate dependencies and utilization.","Account/Region visibility can make an apparently complete review incomplete."]},
"AWS Well-Architected Tool":{"cost":["The tool itself is not the workload cost; review effort, labs, remediation resources, monitoring and service changes are.","Repeated reviews and exported evidence create operational/document storage cost.","Include the services required to implement each improvement item."],"optimization":["Use lenses and workload definitions that match the architecture; record decisions, risk owners and improvement actions rather than collecting unanswered questions.","Review after material changes and close improvement items through tracked implementation, not by editing the answer.","Use account/organization sharing deliberately so central architecture teams can review without owning workload resources."],"security":["Restrict workload, lens, review, improvement-item and share permissions; reviews can contain sensitive architecture and risk details.","Protect workload notes, improvement plans and exports, and separate reviewer access from workload mutation.","Audit workload, lens, milestone and sharing changes."],"watchPoints":["A review is a constructive assessment, not proof that a workload is secure or compliant.","Lens version and workload scope affect comparability over time.","Improvement items need owners and due dates or the review becomes static documentation."]},
"AWS Application Discovery Service":{"cost":["Cost follows discovery connectors/agents, data storage, export/analytics and migration services; the major cost is often remediation effort.","Repeated scans and long retention of obsolete inventory add noise/cost.","Include Migration Hub, DMS, MGN, S3, Athena and network."],"optimization":["Use agentless discovery for broad inventory and agents/connectors when process/dependency detail is needed; choose based on migration decision.","Normalize server/application/dependency data before sizing or wave planning.","Limit collection to migration scope and establish ownership for stale systems."],"security":["Protect discovery agents, inventory data, credentials, tags and export destinations; infrastructure inventory exposes topology and software details.","Encrypt discovery data and restrict migration-project access and cross-account sharing.","Audit agent, connector, import, export and discovery-configuration changes."],"watchPoints":["Inventory presence does not prove application dependency completeness.","Agent health, credentials and network reach determine discovery coverage.","Stale host/application mappings can produce unsafe migration waves."]},
"AWS Application Migration Service":{"cost":["Cost follows source-server replication, staging/EBS, recovery instances, snapshots, transfer and testing.","Long-running replication and repeated drills add cost.","Include DNS, IAM, licenses, networking and target observability."],"optimization":["Use continuous replication and test launches to migrate heterogeneous servers with minimal downtime; configure right-sized target instances and disks.","Group applications and sequence cutover by dependencies, not by server count alone.","Use post-launch validation, rollback and decommission steps as part of the migration runbook."],"security":["Protect source-server replication, launch, conversion, snapshot and recovery roles; replicated disks contain complete workload data.","Encrypt replication/staging data and restrict launch templates, security groups and recovery accounts.","Audit agent registration, replication, launch, cutover and cleanup changes."],"watchPoints":["Replication healthy does not mean application-consistent recovery.","Launch/cutover changes identity, network, hostname and storage assumptions.","Agent version, source log/disk state and dependency order affect migration."]},
"AWS DMS":{"cost":["Cost follows replication instance hours, storage, data transfer, validation and source/target database resources.","Long-running CDC, LOB handling and multi-task replication increase capacity.","Include CloudWatch, KMS, network, staging and target tuning."],"optimization":["Choose full load, CDC or full-load-plus-CDC from downtime and source-change requirements; size replication instance from LOB/CDC workload.","Use table mappings, parallel load, batch apply and validation according to engine behavior, and monitor source log retention.","Keep source/target engine limitations and cutover sequencing explicit."],"security":["Separate replication-instance, endpoint, task and source/target database permissions; credentials belong in Secrets Manager.","Encrypt endpoints, replication storage and logs; protect CDC data and target schemas.","Audit endpoint, task, table-mapping, transformation and replication changes."],"watchPoints":["CDC can lag while tasks remain running; source log retention can become the failure point.","Schema conversion, transformation and target constraints can make load success incomplete.","Cutover requires application quiescence, validation and rollback planning."]},
"AWS DataSync":{"cost":["Cost follows data transferred, task executions, agent/endpoints, requests and destination storage; repeated verification adds work.","Cross-Region/internet paths and small-file workloads can increase time and transfer cost.","Include S3/EFS/FSx, VPC endpoints, logs and destination processing."],"optimization":["Choose DataSync agent, task mode, verification, filters and scheduling from file count, change rate and RPO.","Use incremental transfer, bandwidth limits, manifests and verification intentionally; small-file metadata can dominate.","Separate migration, recurring replication and one-time archival tasks."],"security":["Restrict locations, tasks, agents, manifests and destination roles; transfer access should be narrower than full source/destination administration.","Encrypt traffic and protect task reports, manifests and logs; use private endpoints where the path requires it.","Audit task, location, filter, schedule and agent changes."],"watchPoints":["Task success can hide skipped/failed files; inspect reports and verification results.","Agent connectivity and source permissions are separate from destination access.","File metadata, ownership, symlinks and consistency behavior differ by location type."]},
"AWS Migration Hub":{"cost":["Migration Hub cost is primarily underlying discovery/migration/transfer/storage and program operations.","Duplicate imports and stale inventory increase planning effort.","Include Migration Evaluator, DMS, MGN, DataSync, Snow and networking."],"optimization":["Use Migration Hub as portfolio/wave visibility and integrate discovery/migration tools; keep execution semantics in MGN/DMS/Refactor services.","Group servers by application dependency and readiness, not simply by account or OS.","Use application status, blockers and cutover evidence to drive sequencing."],"security":["Restrict discovery, migration-project, import, orchestration and tracking access; migration inventory is sensitive architecture data.","Protect application groups, progress data and exports with controlled access.","Audit project, application, source, wave and orchestration changes."],"watchPoints":["A tracked application can be marked migrated while validation or traffic cutover remains incomplete.","Source data quality and dependency mapping determine wave safety.","Tool integration status and application status are different signals."]},
"AWS Schema Conversion Tool":{"cost":["SCT itself may be free in some use cases; source/target databases, DMS, compute, storage, transfer and validation create cost.","Repeated assessments and test environments add operational cost.","Include DMS, S3, EC2, KMS and database licensing."],"optimization":["Use SCT assessment reports to identify engine incompatibilities before DMS migration; preserve manual conversion decisions in version control.","Choose conversion settings and extensions from the source/target engine pair, not generic SQL equivalence.","Separate schema conversion, data migration, validation and cutover stages."],"security":["Protect source/target connection profiles, schema metadata, assessment reports and converted scripts; credentials belong in managed stores.","Encrypt project files and reports and restrict access to conversion artifacts.","Audit project, connection, assessment and conversion changes."],"watchPoints":["Converted SQL can be syntactically valid but semantically/performance incorrect.","Unsupported features/extensions require manual remediation.","Assessment output and final schema version must be tied to the migration wave."]},
"AWS Snow Family":{"cost":["Cost follows device/job, shipping, storage/compute, transfer, local operations and destination ingestion; schedule/region affect logistics.","Partial loads, repeat shipments and temporary storage add cost.","Include S3, DataSync, Glacier, KMS and chain-of-custody operations."],"optimization":["Choose Snowcone/Snowball/Snowmobile or online transfer from data volume, bandwidth, isolation and deadline.","Use local compute/storage only where edge processing or disconnected operation justifies operational complexity.","Validate checksums, manifests, encryption and transfer completion before deleting the source."],"security":["Protect device ordering, unlock codes, data encryption, export jobs and chain-of-custody; devices carry complete datasets.","Use KMS/import/export roles and physical handling controls, and sanitize devices according to the product process.","Audit job, manifest, device, transfer and return status."],"watchPoints":["Job/device status and data availability are separate until destination validation completes.","Physical loss/damage and network/manifest errors need recovery procedures.","Device capacity, supported features and Region/shipping constraints affect plan."]},
"AWS Transfer Family":{"cost":["Cost follows server hours, users/requests, data transfer, workflows and S3/EFS storage/requests.","Idle endpoints and cross-AZ/Region transfer can dominate low-volume transfers.","Include Lambda, Step Functions, KMS, CloudWatch and partner network."],"optimization":["Choose SFTP/FTPS/FTP/AS2 and S3/EFS storage from partner protocol and file semantics; use workflows for post-upload processing.","Use logical directories, session policies, throttling and event-driven workflows to isolate tenants.","Design idempotent processing for retries and partial uploads; validate file completion before consuming."],"security":["Use server, user, role, logical directory and protocol permissions separately; each user should map to the minimum S3/EFS path.","Protect SSH keys, certificates, secrets, workflows and uploaded data with KMS and controlled logging.","Audit user, server, endpoint, workflow and host-key changes."],"watchPoints":["A successful upload does not mean downstream processing or partner acknowledgement succeeded.","Host keys/certificates, identity provider and logical-directory mapping fail independently.","Partial uploads and retry behavior require file-completion checks."]},
"Amazon CloudFront":{"cost":["Cost follows requests, data transfer, cache invalidations, real-time logs and edge compute; cache hit ratio affects origin and transfer cost.","Forwarding unnecessary cookies/query strings fragments the cache and increases origin charges.","Include WAF, origin compute/storage, invalidations, logs and cross-Region origin traffic."],"optimization":["Separate cache policy from origin request policy; vary the cache only on values that change the response.","Use compression, sensible TTLs, versioned object names and origin shielding/connection reuse to reduce origin work.","Put lightweight viewer logic in CloudFront Functions and use Lambda@Edge only when its event phase/runtime is required."],"security":["Use Origin Access Control for private S3 origins and restrict custom origins to CloudFront; do not expose a bypassable origin.","Use signed URLs/cookies or application authorization for restricted content and keep cache keys aligned with identity boundaries.","Protect TLS policies, WAF associations and edge/origin logs; redact sensitive query strings, cookies and headers."],"watchPoints":["A cache hit can serve stale or cross-user data if the cache key omits an identity-relevant value.","Viewer and origin events occur at different phases; the wrong trigger produces subtle behavior.","Invalidation, versioned names and origin failover solve different freshness/resilience problems."]},
"AWS Direct Connect":{"cost":["Cost includes port hours, data transfer, hosted/partner fees, virtual interfaces and redundant links.","Cross-Region, Transit Gateway and AWS service traffic has different transfer paths and charges.","Include carrier circuits, colocation, routers, support and backup VPN capacity."],"optimization":["Choose private, transit or public virtual interfaces from destination ownership and routing scope; do not advertise more prefixes than required.","Use LAG, redundant locations and BGP communities where availability and traffic engineering require them.","Keep route propagation and MTU testing explicit; a circuit can be up while application prefixes are unavailable."],"security":["Use dedicated/hosted connection, virtual interface, BGP, route-filter and gateway permissions separately; carrier and AWS account ownership must be explicit.","Encrypt sensitive traffic at the application layer because Direct Connect is private connectivity, not automatic payload encryption.","Protect LOA/CFA, router configuration, BGP authentication and CloudWatch/connection logs."],"watchPoints":["BGP session state, virtual interface state and application reachability are separate signals.","A route learned in one direction does not prove the return path is correct.","Failover timers, route filtering and carrier maintenance affect recovery time."]},
"Elastic Load Balancing":{"cost":["Cost follows load-balancer hours, capacity units/LCU, processed bytes, listeners, public IPv4, logs and data transfer.","Cross-zone traffic and TLS/WAF processing can add cost beyond the hourly load balancer.","Include targets, NAT, WAF, certificates and observability."],"optimization":["Choose ALB, NLB or GWLB from protocol, routing, static-IP, TLS, inspection and latency needs.","Tune health checks, deregistration delay, slow start, cross-zone behavior and target capacity together.","Use listener rules for request routing, but keep service discovery and autoscaling signals independent."],"security":["Separate listener, target-group, security-group, certificate and WAF permissions; the load balancer is not complete application authorization.","Restrict access/connection logs and protect TLS certificates and listener changes.","Audit listeners, target attributes, health checks, certificates and target registration."],"watchPoints":["A target can pass a shallow health check while a dependency or business operation is failing.","ALB/NLB/GWLB have different connection, protocol and scaling semantics.","Cross-zone, client-IP preservation and TLS termination affect troubleshooting and cost."]},
"AWS Global Accelerator":{"cost":["Cost follows accelerator hours, listener/endpoint resources and data transfer; cross-Region traffic and origin services are additional.","Traffic dials can shift cost as well as availability between Regions.","Include WAF, TLS, load balancer, health-check and backend processing charges."],"optimization":["Use Global Accelerator for static anycast entry points, cross-Region routing and fast health-based failover; use CloudFront when caching/edge content is the primary need.","Tune traffic dials and endpoint weights from tested capacity, not merely geographic preference.","Use health checks that test application readiness and preserve client IP only when the backend can handle it."],"security":["Restrict accelerator, listener, endpoint-group and health-check administration; endpoint access controls remain separate.","Use TLS at the appropriate layer and protect client-IP preservation assumptions and logs.","Audit listener/endpoint changes and health-check configuration."],"watchPoints":["Global Accelerator health checks can remove an endpoint while the application is locally reachable but not healthy for the tested path.","Anycast entry and DNS control have different convergence behavior.","Client-IP preservation changes security-group/logging/troubleshooting assumptions."]},
"AWS PrivateLink":{"cost":["Cost follows endpoint hours, endpoint data processing, provider resources and cross-AZ/Region transfer.","Many consumer endpoints can create recurring fixed cost even at low traffic.","Include NLB, DNS, NAT avoidance, logging and provider compute."],"optimization":["Use interface endpoints for service-oriented private access, with clear ownership and DNS boundaries.","Design provider NLB health and zonal behavior for endpoint failure; do not treat PrivateLink as a transitive network bridge.","Remove unused endpoints and consolidate where service ownership permits to avoid persistent hourly cost."],"security":["Control endpoint-service principals, endpoint policies, NLB targets and acceptance independently; private publication does not authorize backend actions.","Use private DNS deliberately and restrict provider-side target reachability to the intended service.","Audit endpoint, service, connection and acceptance changes in both provider and consumer accounts."],"watchPoints":["PrivateLink exposes a service, not a network; routing and authorization remain separate.","Troubleshooting requires evidence from provider and consumer control planes.","Private DNS can hide the actual endpoint path during incidents."]},
"Amazon Route 53":{"cost":["Cost follows hosted zones, queries, health checks, Resolver endpoints/rules and traffic policy features.","Public/private query volume and Resolver forwarding have different drivers.","Include DNSSEC, logging, endpoint hours, health-check regions and dependent services."],"optimization":["Choose simple, weighted, latency, geolocation, failover or multivalue routing from the actual decision signal.","Use alias records and TTLs that balance failover speed with resolver caching; health checks should test application readiness.","Centralize Resolver endpoints/rules only with clear ownership and failure-domain design."],"security":["Protect hosted-zone delegation, registrar, DNSSEC key material, resolver rules and health-check permissions separately.","Restrict private-zone associations and forwarding rules because DNS access exposes internal topology.","Audit record, health-check, resolver, delegation and DNSSEC changes."],"watchPoints":["DNS chooses an answer; it does not guarantee the selected target remains healthy.","TTL/cache delay means clients may continue using an old record after a control-plane change.","Split-horizon zones and resolver forwarding can return different answers for the same name."]},
"AWS Transit Gateway":{"cost":["Cost follows TGW attachment hours and data processing, plus cross-AZ/Region, VPN, Direct Connect and inspection charges.","Centralized routing simplifies operations but can increase processed bytes and transfer.","Include route appliances, Network Firewall, logs and inter-Region peering."],"optimization":["Use separate TGW route tables for production, shared services, inspection and isolated environments; avoid one flat routing domain.","Choose appliance mode, Connect peers, peering or Cloud WAN-style design from traffic symmetry and ownership.","Summarize prefixes where possible and avoid unnecessary hairpinning across AZs/Regions."],"security":["Use separate route-table association/propagation, attachment, VPC, VPN and peering permissions; TGW routing is not a security policy by itself.","Use security groups, Network Firewall and appliance-mode routing where inspection/segmentation is required.","Audit route tables, attachments, propagation, multicast and sharing changes across accounts."],"watchPoints":["A route-table association without propagation or a return route creates asymmetric reachability.","TGW does not automatically provide east-west authorization or DNS resolution.","Attachment limits, route scale and appliance mode affect design before bandwidth does."]},
"Amazon VPC":{"cost":["Cost follows NAT gateways, endpoints, IP addresses, data transfer, flow logs and attached services; VPC itself has no generic hourly fee.","Cross-AZ/Region and internet egress often dominate application traffic cost.","Include Network Firewall, Transit Gateway, DNS Resolver, load balancers and logging."],"optimization":["Plan CIDR, AZ subnets, route domains, DNS and MTU before deployment; overlapping ranges are expensive to fix later.","Choose NAT, gateway/interface endpoints, peering, Transit Gateway, VPN or Direct Connect from ownership, transitivity and scale.","Keep failure domains explicit and avoid forcing every packet through a centralized bottleneck without measuring it."],"security":["Treat route tables, security groups, network ACLs, endpoints, DNS and firewall policies as separate controls; reachability is not permission.","Use private subnets and VPC endpoints for internal AWS API paths where they reduce exposure and egress.","Protect Flow Logs, DNS logs and network telemetry with defined retention and access controls."],"watchPoints":["A VPC is a network boundary, not application authorization.","Overlapping CIDRs, asymmetric routes, MTU and DNS forwarding failures appear when new networks are added.","Multi-AZ placement helps only when routes, endpoints and dependencies fail over together."]},
"AWS VPN":{"cost":["Cost follows tunnel/client endpoint hours, connections, data transfer, certificates and attached TGW/CloudWatch resources.","Idle Client VPN endpoints and cross-AZ/Region transfer create recurring cost.","Include customer gateway, ISP, logging, authentication and backup connectivity."],"optimization":["Choose Site-to-Site, Client VPN or Transit Gateway integration from user/site scale and routing ownership.","Use redundant tunnels and dynamic routing where recovery requires it, and tune MTU/MSS for encapsulation overhead.","Separate client authorization rules from network routes; one determines who may connect, the other where they may go."],"security":["Use customer-gateway, tunnel, route, certificate and shared-secret permissions separately; protect secrets and router configuration.","Use IKE/IPsec settings and monitoring appropriate to the data sensitivity; private tunnel does not replace application encryption.","Audit tunnel, route, customer-gateway and CloudWatch log changes."],"watchPoints":["Tunnel UP only confirms negotiation, not end-to-end application reachability.","Route propagation, authorization rules, security groups and return routes are separate failure points.","Rekey, idle timeout, client version and MTU behavior affect intermittent failures."]},
"AWS Artifact":{"cost":["Artifact access is not the workload cost; storage, legal/compliance workflow and evidence-management systems are.","Repeated downloads and duplicated retention create operational cost rather than stronger assurance.","Include document review, contract workflow and customer-control evidence."],"optimization":["Use Artifact as evidence about AWS's controls and agreements, not as a substitute for evaluating customer workload controls.","Map each report/agreement to the service, Region and compliance question it actually supports.","Automate document inventory and expiry/review reminders without copying sensitive reports into broad repositories."],"security":["Artifact provides AWS compliance/security documents; restrict document access to authorized compliance and procurement roles.","Protect downloaded reports and agreements in controlled storage because they may contain confidential organizational/compliance material.","Audit agreement acceptance, document downloads and delegated access."],"watchPoints":["AWS compliance reports describe AWS controls; customer responsibility remains service- and workload-specific.","Report scope, period, Region and service applicability must be checked before citing it.","Agreement acceptance and report access are different operations."]},
"AWS Audit Manager":{"cost":["Audit Manager cost follows assessments/evidence and underlying Config, CloudTrail, S3, KMS and log collection; evidence retention is a major driver.","Duplicate assessments across accounts can multiply storage and review effort.","Include auditor workflow, exports, immutable retention and remediation tracking."],"optimization":["Select standard/custom frameworks that map to a real compliance objective; enabling every control creates review noise.","Automate evidence collection from supported sources, then assign manual evidence requests to accountable owners with due dates.","Use shared assessments and delegated administration only when account/Region scope and evidence ownership are clear."],"security":["Separate framework/control-set administration, evidence collection, assessment ownership and evidence review; assessors should not rewrite their own evidence.","Protect evidence folders, delegated administration and custom controls, and restrict S3/KMS destinations.","Audit assessment, evidence, framework, control and export changes with immutable retention where required."],"watchPoints":["A control can have evidence without proving the workload is compliant; interpretation and exceptions remain human responsibilities.","Evidence collection depends on source-service permissions and configuration.","Framework version, control mapping and evidence date must be preserved for audit defensibility."]},
"AWS Certificate Manager":{"cost":["Public ACM certificates have no separate charge, while Private CA, issued certificates, HSM-backed keys and related resources do.","Private CA hierarchy and certificate volume create recurring cost even when the leaf certificate is inexpensive.","Include Route 53 queries, load balancers, CloudFront, private endpoints and renewal automation."],"optimization":["Use regional ACM certificates with the services that consume them; CloudFront certificates have a specific Region requirement.","Automate renewal and validate DNS/HTTP ownership before production, and choose public ACM versus Private CA from trust-boundary needs.","Remove unused certificates and standardize naming/tags to prevent an unnoticed expired or duplicate certificate."],"security":["Separate certificate request/import, validation, association and private-CA permissions; protect private keys and export rights.","Use DNS validation and Route 53 permissions narrowly, and keep ACM private-CA issuance policies distinct from public certificate use.","Audit certificate issuance, renewal, export, association and private-CA changes."],"watchPoints":["Certificate renewal can fail because validation records or ownership changed.","Certificate region, domain name, chain and trust store must match the consumer.","Revocation and replacement do not automatically update every listener or client trust store."]},
"AWS CloudHSM":{"cost":["CloudHSM cost follows HSM hours, backups and network/Region placement; minimum HA capacity creates a fixed floor.","Cross-Region clusters and backups add transfer and operational cost.","Include client instances, monitoring, support, key ceremony and replacement procedures."],"optimization":["Use CloudHSM when single-tenant hardware-backed key custody or supported cryptographic operations justify the operational burden.","Size HSMs, client connections, HA members and backup procedures from crypto throughput and failure-domain requirements.","Use client-side connection pooling and test failover/reconnect; cryptographic latency can become an application bottleneck."],"security":["CloudHSM cluster, HSM user, client, partition and application permissions are distinct; protect quorum and crypto-user credentials.","Use network isolation, backup/restore controls and tamper-resistant key handling; CloudHSM does not remove application key-lifecycle responsibility.","Audit cluster, HSM, user, key-operation and backup changes with controls that cannot be altered by one operator."],"watchPoints":["HSM cluster health does not prove the client SDK can authenticate or reach every member.","Key material and user credentials can be unavailable during quorum or client failures.","CloudHSM ownership differs from KMS; applications must implement more lifecycle and availability handling."]},
"Amazon Cognito":{"cost":["Cognito cost follows active users, MAU, SMS/email delivery, advanced security and trigger resources; identity-pool AWS usage is separate.","MFA messaging and federation scale differently from user authentication itself.","Include Lambda triggers, SES/SNS, WAF, analytics and downstream API calls."],"optimization":["Choose user pools for identity/authorization flows and identity pools for temporary AWS credentials; combine them only when the application needs both.","Use managed login/OIDC flows, token lifetimes, refresh behavior and group/claim design to minimize custom authentication code.","Keep custom Lambda triggers bounded and idempotent; they add latency and a separate failure domain to sign-up/sign-in."],"security":["Separate user-pool authentication, app-client, groups, identity-pool role mapping and resource policies; authentication is not authorization to every backend.","Protect custom sender triggers, tokens, federation configuration and user attributes, with MFA and adaptive controls appropriate to the threat model.","Audit pool, client, identity-provider, group, trigger and identity-role changes."],"watchPoints":["A valid ID token does not prove the caller may perform a particular resource action.","User-pool and identity-pool tokens/roles have different audiences and lifecycles.","Trigger failure, federation metadata expiry, refresh-token behavior and regional availability affect sign-in."]},
"Amazon Detective":{"cost":["Cost follows behavior-graph members and data volume/retention; cross-account investigation scope changes the estimate.","Broad membership and long retention increase recurring cost.","Include GuardDuty, CloudTrail and case-management storage."],"optimization":["Use Detective for post-finding relationship/timeline analysis, not high-volume prevention or primary alerting.","Focus investigations around finding IDs, entities and time windows to avoid broad graph queries.","Export only case evidence needed for collaboration and preserve source finding references."],"security":["Restrict behavior-graph access because investigations expose identity, network and resource relationships; separate investigators from administrators.","Protect cross-account member invitations and exported case data, and confirm GuardDuty source access.","Audit graph membership, administrator changes and investigator queries."],"watchPoints":["Detective explains relationships; it does not block activity or prove root cause.","Investigation quality depends on source telemetry and the chosen time window.","Cross-account/Region graph scope determines whether relevant entities are visible."]},
"AWS Directory Service":{"cost":["Cost follows directory hours, edition, trust/connectivity, DNS, snapshots and dependent EC2/WorkSpaces/AppStream resources.","Always-on directory and cross-AZ/Region connectivity are fixed drivers.","Include VPN/Direct Connect, Route 53 Resolver, SSM and support."],"optimization":["Choose Managed Microsoft AD, AD Connector or Simple AD from trust, application compatibility and local identity requirements.","Place directory subnets/replication across AZs and design DNS/forwarding before joining workloads.","Use AD Connector when identity remains on-premises; use Managed AD when AWS-hosted domain services are required."],"security":["Separate directory administration, trust, user/group, DNS and application access; managed directory does not automatically authorize applications.","Protect directory credentials, certificates, trust relationships and snapshots, and keep domain controllers private.","Audit directory, trust, subnet, DNS and administrative changes."],"watchPoints":["Directory health and application authentication are separate; DNS/clock/trust failures often look like app failures.","Managed AD, Connector and Simple AD have different ownership and feature boundaries.","Password/replication/trust changes need recovery procedures."]},
"AWS Firewall Manager":{"cost":["FMS itself is a governance layer; underlying WAF, Shield, Network Firewall, Config and logging charges remain.","Organization-wide inspection and protection can multiply per-account resource costs.","Include remediation Lambda, Config evaluations, security logging and exception management."],"optimization":["Use FMS for centrally governed controls while allowing service teams to own workload-specific rules within defined boundaries.","Start policies in audit mode, review exceptions, then enable automatic remediation for deterministic drift.","Scope by OU, account, Region, resource tag and resource type so policies do not touch unsupported workloads."],"security":["Use delegated administration and policy-scope conditions carefully; FMS can change WAF, Shield, security-group or Network Firewall resources across accounts.","Protect policy exclusions and admin accounts, and require change approval for organization-wide enforcement.","Audit policy compliance, remediation and member-account changes."],"watchPoints":["FMS compliance status is not the same as application protection or traffic health.","Policy propagation and service support differ by resource type and Region.","An exemption can create a protection gap; document owner, expiry and compensating control."]},
"Amazon GuardDuty":{"cost":["GuardDuty cost follows enabled protection plans, data volume and account/Region coverage; broad organization scope scales cost.","Malware scanning, S3 protection and runtime monitoring have different usage drivers.","Include EventBridge, Security Hub, SIEM storage and response Lambda costs."],"optimization":["Enable protection plans and data sources against defined detection questions, then route findings by account and severity.","Automate enrichment and ticketing, but require review before isolation or destructive containment.","Use Security Hub/SIEM for aggregation while retaining GuardDuty as the detector-specific evidence source."],"security":["Centralize administration while restricting who can alter detectors, trusted lists, suppression rules or exported findings.","Protect finding exports and Malware Protection artifacts; findings may reveal workload names, identities and network context.","Use trusted-IP/threat lists narrowly and give suppressions an owner and expiry."],"watchPoints":["GuardDuty detects; it does not prevent the activity or prove root cause.","Finding type, Region, account and source data determine available evidence.","Suppression rules reduce noise but can hide a changed attack pattern after architecture changes."]},
"AWS IAM Identity Center":{"cost":["Identity Center has service/identity costs depending on features; account resources, external IdP, CloudTrail and automation add to the total.","Large assignment inventories and frequent provisioning create operational and API overhead.","Include external directory licensing, MFA, federation and break-glass monitoring."],"optimization":["Use permission sets aligned to job functions and accounts, then provision them deliberately; avoid one global administrator set for every team.","Use ABAC attributes where the identity source can provide reliable tags, and keep emergency access paths tested.","Manage session duration and account assignments from the actual operator workflow rather than granting permanent access."],"security":["Separate identity-center administration, permission-set management, account assignment and identity-source administration.","Protect the external identity source, MFA, permission-set policies and delegated account assignments; assignments can grant organization-wide access.","Audit sign-in, assignment, permission-set and identity-source changes and retain evidence outside the administrator account."],"watchPoints":["Permission-set changes may take time to provision into accounts.","An authenticated user may still lack a provisioned assignment or be blocked by an SCP.","Identity-source outages and emergency access procedures must be tested independently."]},
"AWS IAM":{"cost":["IAM has no direct hourly charge; the cost is the services, logging, analysis and automation invoked through identities.","Over-broad permissions create indirect cost by allowing unintended resources or data processing.","Include CloudTrail data events, Access Analyzer, identity-center and remediation workflows in governance estimates."],"optimization":["Use conditions, tags, paths and permission boundaries for delegated administration instead of copying AdministratorAccess.","Keep role trust policies and permission policies independently reviewable; role chaining and session duration affect the real access path.","Test changes with policy simulation and staged roles before applying organization-wide permissions."],"security":["Separate identity policies, resource policies, permission boundaries, SCPs and session policies; effective access is their intersection.","Use federation and roles for humans/workloads, require MFA for privileged paths, and eliminate long-lived access keys.","Review CloudTrail and Access Analyzer before changing permissions so least privilege does not remove recovery access."],"watchPoints":["An explicit deny in an SCP, boundary or resource policy overrides an identity allow.","IAM authorizes API actions, not business ownership of records.","Root-user controls, eventual consistency, role chaining and policy size limits are operational edge cases."]},
"Amazon Inspector":{"cost":["Inspector cost follows covered resources, scan activity and assessment scope; ECR, EC2 and Lambda coverage differ.","Broad account scanning and repeated image analysis can add cost without increasing remediation.","Include ECR storage, CI rebuilds, tickets and security-data retention."],"optimization":["Select EC2, ECR and Lambda coverage from the asset lifecycle and remediation workflow; duplicate scans without ownership create noise.","Prioritize exploitable/reachable paths and image rebuilds rather than only raw CVE counts.","Integrate findings into CI/CD and patch workflows so a closed finding corresponds to a deployed change."],"security":["Scope delegated administration, scanning roles, SBOMs and export destinations by account and workload.","Protect scan findings and SBOMs because package and network details can expose vulnerability context.","Use exclusions with owners and expiry rather than permanently dismissing findings."],"watchPoints":["A vulnerability finding depends on package, image, runtime and network context.","Coverage changes when resources leave a supported scan state.","A patched image does not remediate an already running instance until rollout is complete."]},
"AWS KMS":{"cost":["KMS cost follows key type, API requests, custom key stores and multi-Region replicas; request rate can be the hidden driver.","Disabling unused keys is not the same as deleting them; lifecycle decisions must preserve decryptability.","Include KMS requests caused by S3, EBS, RDS, Secrets Manager, logs and application encryption."],"optimization":["Choose AWS-owned, AWS-managed or customer-managed keys from control, sharing and lifecycle requirements.","Use grants for delegated service access and Multi-Region keys only where cross-Region cryptographic continuity is needed.","Use envelope encryption and data-key reuse patterns rather than a KMS request for every small payload."],"security":["Separate key administrators, key users and grant creators; key policy and IAM policy must both allow intended use.","Use encryption-context conditions and aliases to prevent a role using a key outside its data domain.","Audit policy, grant, rotation, disablement and deletion-window changes."],"watchPoints":["Scheduling deletion or disabling a key can make healthy data unreadable.","KMS request quotas can throttle high-volume encryption workflows.","Cross-account use requires permission on both the caller and key policy side."]},
"Amazon Macie":{"cost":["Macie cost follows S3 objects evaluated, discovery jobs and sensitive-data findings; scope and sampling determine spend.","Scanning archives and replicated copies may duplicate cost without adding insight.","Include S3 request, inventory, findings export and remediation automation charges."],"optimization":["Start discovery on high-value S3 data, then tune sampling and identifiers from representative matches.","Suppress known benign matches with rationale and use findings to drive S3 access, encryption and retention remediation.","Schedule jobs from data-change frequency rather than scanning every object continuously."],"security":["Limit discovery-job, finding and sample access to data owners; classification results can reveal sensitive identifiers.","Use managed/custom identifiers carefully and protect Macie jobs from scanning unintended buckets or prefixes.","Export findings to a controlled account with retention aligned to data classification."],"watchPoints":["Macie detects sensitive data in S3; it does not fix public access or retention.","Identifier changes alter finding trends and require baseline review.","New prefixes, replicas and newly uploaded objects can fall outside the expected job cadence."]},
"AWS Network Firewall":{"cost":["Network Firewall cost follows endpoint hours, firewall processing, rule groups and logs; NAT, Transit Gateway and transfer may dominate the path.","Centralized inspection can reduce duplicated appliances but add cross-AZ/Region transfer.","Include TLS inspection, CloudWatch/S3 logging, endpoint and route resources."],"optimization":["Choose centralized or distributed inspection from traffic symmetry, AZ failure domains and routing complexity.","Order stateless actions and stateful rules deliberately; use Suricata-compatible rules with a tested default action.","Size endpoint capacity and logging from observed bytes/flows; avoid forcing east-west traffic through an unnecessary bottleneck."],"security":["Use stateful/stateless rule groups, firewall policies, subnet routing and logging permissions as separate controls.","Encrypt and protect TLS inspection certificates and log destinations; restrict who can change centralized inspection policy.","Audit rule, policy, endpoint, route and logging changes across the inspection VPC."],"watchPoints":["Routing must be symmetric for stateful inspection; an accepted route does not mean a flow will return through the firewall.","A rule update can block control-plane dependencies and break deployments.","Monitor capacity/flow limits, dropped packets, endpoint health and Suricata alert volume."]},
"AWS Resource Access Manager":{"cost":["RAM usually has no separate charge; shared resource usage, data processing, transfer and centralized management remain billable.","Centralized resources can shift cost ownership and cross-AZ/Region traffic.","Include Transit Gateway, subnets, Route 53 Resolver, licenses and network services."],"optimization":["Use RAM for supported regional/global resources where centralized ownership and consumer access are needed; confirm whether the resource is shareable and whether it remains in the owner account.","Use tag-based sharing with stable governance tags and explicit exceptions.","Document lifecycle when a consumer account leaves an organization or a share is deleted."],"security":["Use resource shares, principals, tags and organization settings carefully; sharing a resource is not the same as sharing its data policy.","Restrict who can create/accept shares and prevent sensitive resources from being shared outside intended OUs/accounts.","Audit share, association, invitation and organization-sharing changes."],"watchPoints":["RAM sharing does not bypass the resource's IAM, network or service policy.","Regional versus global resource scope affects visibility.","Consumer use can continue or fail differently when organization membership changes."]},
"AWS Secrets Manager":{"cost":["Cost follows secret storage, API calls, rotation Lambdas and KMS usage; high-frequency retrieval is avoidable with client caching.","Cross-Region replication and rotation add storage, API and Lambda cost.","Include VPC endpoint/NAT, CloudTrail and consuming application retry costs."],"optimization":["Use managed rotation for supported databases/services and design application refresh around version stages rather than hard-coded values.","Cache secrets with bounded TTL to reduce API calls while still responding to rotation; do not cache indefinitely in long-lived processes.","Separate secrets by workload/environment and remove unused versions according to rollback requirements."],"security":["Use resource policies and IAM roles to separate read, write, rotate and administer permissions; applications should read only named secrets.","Use KMS key policies and VPC endpoints deliberately, and never log secret values during rotation or troubleshooting.","Audit secret versions, rotation configuration, resource policies and deletion windows."],"watchPoints":["Deleting or moving a secret can break applications even when IAM permissions remain correct.","Rotation succeeds only when the database/user/network path and application refresh logic all work.","Secret version stages such as AWSCURRENT/AWSPREVIOUS matter during rollback."]},
"AWS Security Hub":{"cost":["Cost follows enabled controls, accounts, Regions and findings; source products, EventBridge, SIEM and storage add cost.","Reduce duplicate/noisy controls only after confirming coverage.","Include CloudTrail, GuardDuty, Inspector, Macie, Config and response compute."],"optimization":["Enable standards/controls according to risk and account scope, route findings to owners and keep GuardDuty/Inspector/Macie/Config as evidence sources.","Use automation for normalization, enrichment and tickets; require review for isolation, deletion or policy changes.","Use cross-Region aggregation and custom actions only where ownership and data residency are clear."],"security":["Separate delegated administration, standards, control, finding-update and automation permissions; response roles should not suppress their own evidence.","Protect cross-Region aggregation, finding exports and workflow status and retain source-product references.","Audit suppression, status, automation and policy changes."],"watchPoints":["Security Hub aggregates/normalizes; it does not remediate or replace detector evidence.","Control status can be stale when prerequisite permissions/data sources are missing.","Suppressions need owner/expiry because they can hide recurring risk."]},
"AWS Security Token Service":{"cost":["STS API usage is generally not the main bill; downstream services, federation, CloudTrail and identity-provider costs are.","Excessive credential refresh/retry can increase API traffic and create intermittent throttling.","Include external IdP, MFA, federation proxy and logging infrastructure."],"optimization":["Use role chaining and session duration intentionally; avoid long chains that shorten credentials unexpectedly.","Use source identity and session tags for traceability and ABAC, but constrain which principals may set them.","Prefer workload identity roles and federation over static keys; test refresh before expiry under long-running jobs."],"security":["Limit AssumeRole trust policies, external IDs, session tags, source identity and role-session duration; temporary credentials still need least privilege.","Use regional STS endpoints where required by latency/data-residency design and protect federation/identity-provider metadata.","Audit AssumeRole, GetFederationToken and session-tag use through CloudTrail."],"watchPoints":["A role can be assumable but still fail because the identity policy, SCP, boundary or session policy denies the action.","Regional endpoint choice and token validity affect latency and outage behavior.","Session tags and source identity can be lost or restricted through role chaining."]},
"AWS Shield":{"cost":["Shield Standard is included for eligible services; Shield Advanced subscription/protected-resource and data-transfer economics differ.","Origin capacity, WAF, CloudFront and emergency scaling remain separate costs.","Include SRT response, logs, Route 53, ELB and failover capacity."],"optimization":["Use CloudFront, Route 53, resilient origins and autoscaling to distribute/absorb traffic before manual response.","Associate the actual public resource path and configure health checks that represent application availability.","Use DDoS response/cost-protection runbooks with clear approval and evidence."],"security":["Shield protects eligible resources but does not replace WAF, origin hardening, IAM or application controls.","Restrict Shield Advanced administration, protected-resource associations and response-team access.","Integrate Shield visibility with CloudFront/Route 53/ELB logs and incident escalation."],"watchPoints":["DDoS mitigation can preserve availability while legitimate-looking application requests still overload the origin.","Protected-resource association and DNS routing determine bypass risk.","Standard and Advanced provide different visibility and response capabilities."]},
"AWS WAF":{"cost":["Cost follows Web ACL/rule-group requests and optional logging; protected-resource traffic and WAF capacity/managed groups affect spend.","Broad body inspection and verbose logs increase processing/storage cost.","Include CloudFront/API/ALB, Shield, Kinesis Firehose, S3 and SIEM."],"optimization":["Start custom/managed rules in count mode, analyze legitimate matches, then block; use labels and rate-based rules for layered abuse control.","Place rules at the edge/regional resource that sees unwanted traffic before origin capacity is consumed.","Tune body inspection, scope-down statements and rule ordering to the actual attack surface."],"security":["Attach Web ACLs to the actual CloudFront/API/ALB/AppSync resource and scope rules by host/path/method/IP/label; WAF is not backend authorization.","Use managed rule groups with tested exclusions, rate-based rules and logging redaction; restrict who can alter rules and associations.","Protect WAF logs and sampled request data with retention and access controls."],"watchPoints":["WAF evaluates web requests, not non-HTTP paths or business authorization.","Managed rule updates can change false positives; monitor versions and exclusions.","Direct-origin or alternate-host bypasses can invalidate the protection design."]},
"AWS Backup":{"cost":["Cost follows protected-resource backup storage, lifecycle tier, requests, cross-Region copy/transfer and restore activity.","Long retention, duplicated copies and unchanged full backups can dominate.","Include KMS, S3/EFS/EBS/RDS/DynamoDB source and restore compute."],"optimization":["Define schedules, retention, lifecycle and resource assignments from RPO/RTO; backup everything is not a recovery strategy.","Use cross-account/Region copies and logically air-gapped vaults for the failure model, then test restores with application dependencies.","Tag and report protected resources, failed jobs and restore validation."],"security":["Use backup plans, vault policies, copy, restore and deletion permissions separately; protect vault access from source-account administrators.","Encrypt vaults/copies with KMS and use Vault Lock/organizational policies where immutability is required.","Audit backup, copy, restore, lifecycle and vault-policy changes."],"watchPoints":["A completed backup job does not prove the application can restore consistently.","Vault Lock and lifecycle deletion have irreversible/retention implications.","Backup coverage, restore time and dependency ordering must be tested."]},
"Amazon EBS":{"cost":["Cost follows volume GB-month, provisioned IOPS/throughput, snapshots, fast restore, transfer and public IPv4/instance resources.","Oversized volumes and old snapshots are common hidden cost.","Include KMS, backup, cross-Region copy and attached EC2."],"optimization":["Choose gp3/io2/st1/sc1 from measured IOPS, throughput, latency and durability; capacity and performance are separate choices where supported.","Use snapshots/fast snapshot restore only for a defined recovery/startup objective and delete stale copies.","Separate stateful data from instance lifecycle and test initialization behavior after restore."],"security":["Encrypt volumes/snapshots with KMS and restrict snapshot sharing, attach/detach, create/restore and copy operations.","Separate instance, volume and backup roles; protect boot/data/temp volumes according to classification.","Audit volume, snapshot, fast-restore and encryption changes."],"watchPoints":["EBS is AZ-scoped block storage, not a regional shared filesystem.","Snapshot restore/initialization can affect first-read latency and recovery time.","Multi-AZ database availability requires application/database design beyond one volume."]},
"AWS Elastic Disaster Recovery":{"cost":["Cost follows protected server replication, staging resources, snapshots, recovery compute, transfer and test drills.","Long-lived staging and frequent tests add recurring cost but may be required for RTO assurance.","Include Route 53, IAM, EBS, networking, licenses and application dependencies."],"optimization":["Choose recovery instance type, staging subnet, replication settings and launch actions from RPO/RTO and application dependency order.","Use continuous replication and recovery plans, then test drills with DNS, identity, storage and external integrations.","Automate launch settings but preserve approval for destructive failback and source cutover."],"security":["Use source-server, replication, launch, recovery and failback permissions separately; protect recovery snapshots and staging areas.","Encrypt replicated data and restrict security groups, launch templates and recovery-account access.","Audit source registration, replication, recovery, failback and cleanup changes."],"watchPoints":["Replication health is not application recovery; crash consistency and database ordering need validation.","Recovery launch can succeed while DNS, secrets, licenses or downstream services fail.","Failback changes source/target roles and must be rehearsed."]},
"Amazon EFS":{"cost":["Cost follows storage class capacity, throughput, requests, backup, replication and transfer; cross-AZ access can matter.","Lifecycle tiering and retention reduce storage cost but retrieval/access patterns change.","Include mount clients, backup, KMS, CloudWatch and cross-AZ/Region traffic."],"optimization":["Choose Regional/One Zone, throughput mode and performance mode from availability and metadata/I/O behavior.","Use lifecycle policies for inactive files and access points for multi-application isolation.","Monitor small-file metadata and client concurrency separately from large sequential I/O."],"security":["Use security groups, mount-target paths, IAM authorization/access points and POSIX permissions together.","Encrypt data at rest/in transit and restrict access-point roots and identities.","Protect backup/replication operations and audit mount-target/file-system policy changes."],"watchPoints":["EFS is shared NFS semantics, not S3 object or EBS block semantics.","Throughput mode and burst behavior affect performance over time.","A shared filesystem can become a shared failure/performance dependency."]},
"Amazon FSx":{"cost":["Cost follows file-system capacity, throughput/IOPS, storage tier, backups, data transfer and client/network resources.","Cross-AZ access and provisioned throughput can dominate shared-file workloads.","Include S3 integration, backups, directory, KMS and compute."],"optimization":["Choose FSx for Windows, Lustre, NetApp ONTAP or OpenZFS from protocol, performance, data-management and integration requirements.","Tune throughput, IOPS, cache, SSD/HDD/tiered storage, metadata and client placement for the selected file system.","Use data repositories, backups and replication according to recovery and analytics workflows."],"security":["Use file-system, client, directory, SVM/share and backup permissions separately; Windows/ONTAP/OpenZFS/Lustre semantics differ.","Encrypt file systems, backups and transit and restrict administrative endpoints and export paths.","Audit file-system, storage-tier, backup, directory and client-access changes."],"watchPoints":["FSx variants are not interchangeable; protocol, failover and data-management behavior differs.","Metadata-heavy workloads can fail performance targets despite ample capacity.","Backup/replication consistency and restore time must be tested."]},
"Amazon S3":{"cost":["Cost follows storage class GB-month, requests, retrieval, transitions, replication and transfer.","Small objects, unnecessary LIST/GET, old versions and cross-Region/internet transfer are common drivers.","Include KMS, CloudTrail, analytics, CDN and downstream compute."],"optimization":["Use object/prefix/size/format design, multipart upload, lifecycle and Intelligent-Tiering according to access pattern.","Use columnar compressed partitioned objects for Athena/Glue/EMR; reduce scan bytes before scaling analytics.","Use replication, notifications and inventory for a defined recovery/data-management requirement."],"security":["Block public access, use bucket/access-point policies deliberately and prefer roles/presigned URLs over shared credentials.","Choose SSE-S3/KMS and versioning/Object Lock from key-control and retention requirements.","Use CloudTrail data events selectively and protect logging/inventory destinations."],"watchPoints":["S3 replacement/version semantics differ from block updates.","Versioning protects recovery but requires noncurrent-version lifecycle.","Replication is not backup unless delete/version/retention behavior is tested."]},
"Amazon S3 Glacier":{"cost":["Cost follows archived GB-month, requests, retrieval volume/speed, early deletion, restore staging and transfer.","Deep Archive minimizes storage but increases retrieval delay and minimum-duration exposure.","Include S3 lifecycle, KMS, restore compute and destination storage."],"optimization":["Choose Flexible Retrieval, Deep Archive or S3 Glacier storage classes from access frequency and recovery time.","Use lifecycle transitions only when minimum-storage-duration and retrieval economics fit; keep restore workflows tested.","Maintain inventory/index metadata outside the archive so a recovery request can locate objects."],"security":["Use vault/object access policies, S3 Object Lock/lifecycle permissions and KMS controls separately; archived data can be highly sensitive.","Protect restore jobs, retrieval outputs and temporary copies with retention and access controls.","Audit archive lifecycle, restore, deletion and legal-retention changes."],"watchPoints":["Archive retrieval is asynchronous and does not equal immediate object availability.","Minimum storage durations and early deletion charges matter for changing data.","Object retention, legal hold and deletion permissions can outlive the application."]},
"AWS Storage Gateway":{"cost":["Cost follows gateway type, stored/processed data, S3/EBS/Glacier, requests, transfer and appliance infrastructure.","Cache and upload-buffer disks, cross-Region transfer and archive retrieval add cost.","Include VM/hardware, network circuits, KMS, backup and target services."],"optimization":["Choose File, Volume or Tape Gateway from application protocol and cloud data lifecycle; caching behavior differs by type.","Size cache, upload buffer, bandwidth and local disk from working set and outage duration.","Use scheduled bandwidth and upload queues where WAN constraints require predictable transfer."],"security":["Protect gateway activation, file/volume/tape shares, cache disks and storage roles; local gateway credentials and AWS access are separate.","Encrypt cached, uploaded and stored data and restrict S3/backup destinations.","Audit gateway, share, cache, bandwidth and maintenance changes."],"watchPoints":["A gateway can serve cached data while uploads are delayed or failing.","Local cache capacity and WAN health define application behavior during disconnection.","Gateway version, NTP, DNS and activation credentials affect recovery."]},
"Amazon Kinesis":{"cost":["Cost varies by stream capacity/requests, Firehose delivery, retention, enhanced fan-out, storage and transfer.","Retention extension and multiple consumers multiply cost.","Include Lambda, Glue, Flink, S3, OpenSearch, KMS and logs."],"optimization":["Choose Kinesis Data Streams, Firehose or Video Streams from retention, replay, delivery and media semantics.","Use partition keys, aggregation, batching and shard/on-demand capacity from event distribution; a hot partition is a local bottleneck.","Use enhanced fan-out for isolated low-latency consumers and Firehose when managed delivery is the real requirement."],"security":["Use producer/consumer/application roles separately and encrypt streams, delivery destinations and analytics state with controlled keys.","Protect enhanced fan-out, resharding, consumer registration and checkpoint stores.","Audit stream, consumer, application and retention changes."],"watchPoints":["Kinesis services are not interchangeable: stream records, managed delivery and video fragments have different ordering/retention.","Iterator age and expired records show consumer health better than producer success.","Partition-key skew, resharding and consumer checkpoints determine replay behavior."]},
"Amazon Quick Sight":{"cost":["Cost follows users/sessions/capacity, SPICE, refresh/query activity and source services.","Frequent refresh and direct-query scans are common drivers.","Include Athena/Redshift/RDS/S3, KMS and embedding."],"optimization":["Use SPICE for predictable interactive consumption and direct query when freshness requires source execution; optimize visuals and source SQL.","Apply row-level security and scheduled refresh by tenant/source cadence.","Use dashboard/folder ownership and avoid duplicate calculated data products."],"security":["Use namespaces, dataset permissions, row-level security, embedded sessions and data-source credentials separately.","Protect SPICE, exports and embedding tokens and audit sharing/refresh changes.","Control cross-account data-source roles."],"watchPoints":["SPICE freshness is a data product property, not just a dashboard property.","Embedded session permission and dataset permission are distinct.","Source throttling can appear as dashboard slowness."]},
"AWS AppConfig":{"cost":["Cost follows configuration requests, deployments and connected services; aggressive polling multiplies request cost.","Hosted configuration, validators, CloudWatch alarms, Lambda extensions and logs add operational cost.","Include downstream effect of flags such as extra Lambda, database or third-party calls."],"optimization":["Use validators and deployment strategies with bake time/alarms so a bad feature flag does not reach every instance immediately.","Choose hosted configuration, Secrets Manager, SSM or AppConfig extensions from data type and refresh behavior.","Use client-side caching and polling intervals appropriate to change urgency; avoid fetching configuration on every request."],"security":["Separate configuration profile, deployment strategy, environment, hosted configuration and extension permissions; application roles should read only their configuration.","Encrypt configuration data and protect validators, extensions, Secrets Manager references and deployment events.","Audit configuration versions, deployment strategies, validators and rollback changes."],"watchPoints":["A configuration deployment can be successful while the application rejects or misinterprets the value.","Rollback behavior depends on alarms and client refresh timing.","Feature flags need lifecycle ownership; stale flags become hidden architecture branches."]},
"AWS Lambda@Edge":{"cost":["Cost follows invocations and duration across edge locations plus CloudFront requests, transfer and logs.","Forwarding headers/cookies can lower cache hit ratio and increase origin cost.","Include replicated deployment, invalidation and origin services."],"optimization":["Use viewer-request/response or origin-request/response triggers according to the phase needed; keep edge code small and deterministic.","Use CloudFront Functions for lightweight header/URL logic when Lambda runtime features are unnecessary.","Avoid network calls and cold-start-heavy work at the edge; push regional business logic behind the origin."],"security":["Use the CloudFront distribution/behavior and replicated function version controls; Lambda@Edge deployment has global propagation implications.","Keep code, environment assumptions and headers/cookies free of secrets; use IAM role permissions only for the edge operation.","Protect logs across Regions and redact viewer request data."],"watchPoints":["Lambda@Edge executes in distributed locations with versioned replication; updates are not instant everywhere.","The event phase determines which request/response fields and origin behavior are available.","Region restrictions and runtime/dependency limits differ from regional Lambda."]},
"Amazon Connect":{"cost":["Cost follows contacts/minutes/messages, channels, recordings, transcription, AI/analytics and telephony; downstream integrations add cost.","Idle agents, long contacts and retained recordings are common drivers.","Include Lambda, S3, Kinesis, Lex, Polly, Transcribe and CRM."],"optimization":["Model capacity around channel concurrency, queue routing, agent availability and flow latency; adding agents does not fix routing loops.","Use flows/Lambda for bounded automation and provide human escalation/fallback.","Separate recordings, analytics and real-time assistance from the contact path."],"security":["Separate instance, queue, routing-profile, flow, recording, analytics and integration permissions; customer interaction data needs strict access.","Encrypt recordings/transcripts and configure redaction/retention; protect Lambda/CRM actions.","Audit flows, queues, users, prompts, routing and integrations."],"watchPoints":["Contact-flow success differs from customer outcome; monitor abandonment, queue delay, transfer loops and agent state.","Telephony, chat, task and AI features have different billing/availability.","A CRM/Lambda failure can break the interaction while Connect remains healthy."]},
"Amazon DynamoDB Streams":{"cost":["Cost follows stream read requests, Lambda/consumer processing, storage/exports and downstream services; item size/view type matter.","High write volume and full images multiply payload and processing cost.","Include KMS, EventBridge, OpenSearch, S3 and retry/DLQ storage."],"optimization":["Choose KEYS_ONLY, NEW_IMAGE, OLD_IMAGE or NEW_AND_OLD_IMAGES from downstream decision needs; extra images increase data volume.","Use Lambda batch/window/partial failure and checkpoint behavior for idempotent consumers.","Use streams for change capture and triggers, not arbitrary producer queues; use Kinesis when longer retention/replay is required."],"security":["Restrict stream read, Lambda/event-source, export and KMS permissions separately from table access.","Protect stream records and downstream destinations because change images may contain full item data.","Audit stream enablement, view type, consumers and event-source mappings."],"watchPoints":["Stream retention is limited; lag beyond retention loses change records.","Ordering is per partition key and retries can duplicate events.","Disabling/re-enabling streams changes continuity and consumer behavior."]},
"Kiro":{"cost":["Cost follows model usage, context/repository size, tool calls, IDE/service subscriptions and CI/deployment resources.","Large context windows and repeated agent loops can dominate usage.","Include repository hosting, build/test runners, logs, secrets and deployed AWS resources."],"optimization":["Use specifications, steering files and hooks to make requirements, tests and review repeatable; keep tool use bounded and observable.","Use agent mode for exploration and implementation, but preserve normal branch protection, CI and deployment approvals.","Separate code generation, test execution and infrastructure application so an agent cannot silently promote its own output."],"security":["Treat Kiro agent, IDE, repository, MCP/tool and deployment permissions separately; generated code must not inherit production credentials.","Protect prompts, code context, repository metadata, hooks and agent logs; restrict tool servers and command execution.","Audit agent configuration, steering files, hooks, tool connections and generated changes."],"watchPoints":["Generated code is not evidence of correctness, security or licensing compliance.","MCP/tool permissions can expand the agent's effective authority beyond the IDE.","Steering/spec changes can alter future output without changing application code."]},
"Amazon Bedrock":{"cost":["Cost follows input/output tokens, model choice, customization, provisioned throughput, guardrails and data transfer; context length is often dominant.","Cross-Region inference, repeated prompts and large retrieved context can materially change spend.","Include S3, vector/search, KMS, CloudWatch, orchestration and downstream application charges."],"optimization":["Choose model/API from quality, latency, modality, context and cost; use Converse/Responses/Invoke according to the integration contract.","Use prompt caching, batching, asynchronous invocation, inference profiles or provisioned throughput where measured workload shape supports them.","Keep retrieval, orchestration, generation and evaluation separate so scaling one layer does not hide a quality problem."],"security":["Separate model invocation, customization, guardrail, agent and knowledge-base roles; application callers should not gain model-administration rights.","Control inputs, outputs, prompts, training data, guardrails, KMS keys and invocation logs according to data classification.","Audit model access, inference profiles, custom model, guardrail and provisioned-throughput changes."],"watchPoints":["Model availability, quotas, guardrail behavior and Region support differ by model.","A guardrail is a safety layer, not a complete authorization or business-rule engine.","Token/context limits and cross-Region routing affect latency, residency and cost."]},
"Amazon Bedrock AgentCore":{"cost":["Cost follows model tokens, runtime execution, tool calls, memory/storage, observability and external services invoked by the agent.","Unbounded planning, retries and large context histories can exceed the model call cost.","Include Lambda/ECS, APIs, databases, vector stores, KMS and human-review workflows."],"optimization":["Use runtime isolation and tool gateways to keep long-running agent execution bounded; make tools deterministic and idempotent where possible.","Choose memory, browser/code execution and gateway components from the agent task rather than enabling every capability.","Set timeouts, budgets, approval steps and retry policies so an agent cannot loop through expensive actions."],"security":["Separate runtime, identity, tool, memory, gateway and observability permissions; an agent's ability to call a tool must be narrower than the human's identity.","Protect session state, prompts, tool credentials and memory stores, and use workload identities for agent-to-service calls.","Audit agent runtime, tool registry, policy, memory and deployment changes with traceable session IDs."],"watchPoints":["AgentCore orchestration success does not prove the tool action was correct or authorized.","Session memory can preserve stale or sensitive context across tasks.","Tool availability, identity federation, quotas and timeout behavior define the real failure boundary."]},
"Amazon Bedrock Knowledge Bases":{"cost":["Cost follows ingestion, embeddings, vector storage, retrieval/model tokens, source storage and downstream search.","Large chunks, repeated embeddings and broad top-k retrieval increase both cost and context noise.","Include OpenSearch/vector database, S3, KMS, CloudWatch and orchestration charges."],"optimization":["Choose parsing, chunking, embedding model, vector store, metadata filters and reranking from document structure and query quality.","Use incremental ingestion and source-change cadence instead of reprocessing unchanged corpora.","Separate ingestion and query workloads; monitor index freshness and retrieval relevance before increasing model size."],"security":["Protect connector roles, source documents, embeddings, vector stores and retrieval results; source ACLs must remain aligned with answer access.","Encrypt source, vector and generated data and keep connector credentials in Secrets Manager.","Audit ingestion, chunking, embedding-model, vector-store and retrieval configuration changes with document provenance."],"watchPoints":["A relevant-looking chunk can be stale or unauthorized if sync/metadata filtering is wrong.","Changing chunking or embeddings generally requires controlled re-ingestion and evaluation.","Vector-store backup, scaling and access policies remain part of the RAG boundary."]},
"Amazon Bedrock Prompt Management":{"cost":["Cost follows the model invocations and tokens generated by prompt variants; experimentation can multiply calls.","Prompt length, inserted context and repeated evaluation runs are primary drivers.","Include evaluation datasets, logs, guardrails and downstream tool calls."],"optimization":["Use prompt variants and versioning to compare quality, latency and token use without changing production callers implicitly.","Keep reusable prompt templates separate from runtime data and validate variables before invocation.","Evaluate prompts with representative datasets and guardrail behavior before promoting a version."],"security":["Restrict who can create, version, share and invoke prompt resources; prompt variables can contain sensitive business context.","Keep prompts free of embedded credentials and control logging/evaluation data because prompt text is often proprietary.","Audit prompt versions, variants, model parameters and deployment references."],"watchPoints":["A prompt version can change output behavior without an application code deployment.","Template variables can create injection or data-leakage paths.","Prompt quality, model choice and guardrails are separate controls."]},
"Amazon Bedrock Prompt Flows":{"cost":["Cost follows model tokens plus node invocations, Lambda/API calls, retrieval and logging; fan-out branches multiply work.","Repeated retries and parallel branches can dominate the estimate.","Include KMS, Step Functions/Lambda-like integrations, vector stores and data transfer."],"optimization":["Use flow nodes for explicit orchestration, branching and transformation; keep reusable logic in versioned components rather than hidden prompt text.","Set timeouts, retries, validation and error paths per node so one failing integration does not loop the entire flow.","Evaluate each branch and end-to-end flow with representative inputs before deployment."],"security":["Give flow nodes only the model, knowledge-base, Lambda/API and prompt permissions they need; isolate execution roles by flow.","Protect flow definitions, inputs/outputs, connections and secrets; node logs can expose complete prompts and responses.","Audit flow version, node, connection and deployment changes."],"watchPoints":["A flow can complete while a branch returns a low-quality or empty result unless validation is explicit.","Node-level timeouts and downstream throttles create partial-output behavior.","Flow version and connection configuration must be deployed together."]},
"Amazon Q Business":{"cost":["Cost follows user subscriptions, index capacity, connectors, storage and model/query usage; source and action services add cost.","Full re-ingestion, stale conflicts and large index capacity drive spend.","Include Kendra/S3/SharePoint/Salesforce connectors, IAM Identity Center, Lambda and logs."],"optimization":["Choose connectors and sync cadence from source volatility; use metadata filters/retrievers and citations to improve answer quality before increasing capacity.","Separate read-only Q&A from plugins that create side effects and require confirmation for actions.","Control whether answers use enterprise data, model knowledge or both for each application."],"security":["Use IAM Identity Center/IAM and source ACL synchronization so responses respect document permissions; indexing is not authorization.","Protect connectors, index capacity, plugins, data accessors, chat logs and action roles.","Audit connector sync, web experience, plugin, subscription and access changes."],"watchPoints":["Permission sync failures can cause leakage or empty answers.","Index capacity and user subscription are distinct dimensions.","Citations and hallucination mitigation improve trust but do not replace source governance."]},
"Amazon Q Business Apps":{"cost":["Cost follows Q subscription/index capacity plus connector, model, plugin and downstream action usage.","Public/anonymous or widely shared apps can multiply usage unexpectedly.","Include S3, Kendra, Lambda, APIs, IAM Identity Center and audit storage."],"optimization":["Use Q Business Apps for task-focused internal experiences with bounded sources and actions; separate app UX from enterprise data ownership.","Keep prompts, conversation starters and action schemas versioned and test permission-trimmed responses.","Require confirmation for actions such as tickets, requests or messages and log the actor/result."],"security":["Scope app creator, data source, user, plugin and action permissions; a shared app must not expose the creator's broad data access.","Protect uploaded data, app configuration, connectors and generated outputs with retention/encryption controls.","Audit app sharing, source, prompt, plugin and action changes."],"watchPoints":["App sharing does not override source ACLs but can create confusing empty/partial answers.","Action completion and conversation completion are separate states.","App configuration changes can alter answer/action behavior without application deployment."]},
"Amazon Q Developer":{"cost":["Cost follows user subscription/usage, model context, repository indexing, agent/tool calls and CI/CD resources.","Repeated transformations and large repositories increase context/storage work.","Include CodeBuild/CodePipeline, scanning, logs, ECR and deployed resources."],"optimization":["Use inline suggestions, chat, code reviews, transformations and agents for the workflow they fit; larger context is not automatically better.","Measure acceptance, rework, latency and token use by repository/team.","Keep generation, tests, approval and deployment as separate gates."],"security":["Scope developer, repository, transformation, agent and console permissions; generated suggestions must not access production credentials.","Protect prompts, code context, repository metadata and agent/tool logs, applying organization data-use controls.","Audit repository connections, customizations, agent actions and generated changes."],"watchPoints":["Q Developer accelerates code but does not establish correctness, license suitability or security.","Repository permissions, branch protection and CI remain authoritative.","Generated IaC can create expensive or unsafe resources; review plans/diffs."]},
"Amazon Quick":{"cost":["Cost follows users/sessions/capacity, SPICE/direct query, topic/AI usage and source services.","Frequent refresh and broad direct-query scans add cost.","Include Athena/Redshift/S3, KMS, embedding and audit services."],"optimization":["Use Quick topics/semantic modeling to define business terms and trusted fields before enabling natural-language questions.","Prefer governed datasets and row-level security over prompt instructions for data separation.","Validate generated insights against source dashboards and define fallback for ambiguous questions."],"security":["Use identity, namespace, dataset, dashboard, topic and action permissions separately; Q features must inherit the viewer's data access.","Protect semantic models, uploaded data, prompts and generated insights and keep exports controlled.","Audit dataset, topic, dashboard, sharing and Q configuration changes."],"watchPoints":["Natural-language answers depend on semantic model quality and data freshness.","Generated narrative is not a financial/control decision without source validation.","Viewer permissions, topic permissions and dataset permissions can diverge."]},
"Amazon SageMaker Clarify":{"cost":["Cost follows processing jobs, data volume, endpoint invocations and output storage; large evaluation sets and repeated explanations are expensive.","Sampling can reduce cost but may miss minority/cohort behavior.","Include S3, processing compute, endpoint, KMS and governance storage."],"optimization":["Choose pre-training bias, post-training bias, explainability or model-monitor baselines from the governance question; do not enable every analysis blindly.","Use representative datasets and feature metadata, and compare baselines across meaningful cohorts.","Run analyses as pipeline stages with approval rather than treating a report as automatic model rejection."],"security":["Give Clarify jobs access only to approved datasets, model endpoints and output locations; bias reports can contain sensitive attributes.","Encrypt analysis data and reports and restrict baseline/feature configuration changes.","Audit processing, bias, explainability and monitoring configuration."],"watchPoints":["Bias metrics depend on label, cohort and threshold definitions; different choices can produce different conclusions.","Explainability indicates feature contribution, not causation.","A report can be stale when the model, data schema or endpoint changes."]},
"Amazon SageMaker Data Wrangler":{"cost":["Cost follows Studio/compute sessions, processing jobs, storage, source scans and transfer; interactive idle time is a common driver.","Repeated full exports and high-cardinality profiling increase processing cost.","Include S3, Glue, Feature Store, VPC endpoints and downstream training."],"optimization":["Use Data Wrangler for interactive preparation and export repeatable transformations to processing/jobs; avoid making the notebook flow the only production artifact.","Push filtering/projection to the source where possible and sample interactively before processing full data.","Track schema, transform versions and validation rules when exporting to S3, Feature Store or pipelines."],"security":["Protect data connections, flow definitions, credentials, artifacts and Studio execution roles; a flow can access more data than its final dataset.","Encrypt flow artifacts, processing outputs and temporary storage, and keep connection secrets in managed stores.","Audit data-source, transform, export and job changes."],"watchPoints":["Interactive success may hide full-dataset failures, schema drift or memory pressure during export.","Source credentials and flow artifacts can expose data lineage and sensitive columns.","A transform that works in a sample may change semantics at full scale."]},
"Amazon SageMaker Ground Truth":{"cost":["Cost follows objects/pages/tasks, human workforce type, automation and storage; review and rework can exceed initial labeling.","Sampling and active learning reduce human tasks when uncertain examples are prioritized.","Include S3, Lambda, Step Functions, model inference and workforce management."],"optimization":["Choose automated data labeling, human labeling, active learning and task types from quality and cost requirements.","Use clear instructions, gold tasks, consensus and worker qualification to improve label quality before scaling volume.","Use manifest/version controls and validation before annotations enter training."],"security":["Restrict labeling-job, workforce, dataset and output roles; worker identities and annotations can contain sensitive or proprietary data.","Use private workforces, encryption and output-bucket policies appropriate to the data, and control worker access to source objects.","Audit workforce, labeling-job, template, manifest and annotation changes."],"watchPoints":["Annotation agreement and gold-task accuracy do not guarantee production-label correctness.","Worker privacy, task leakage and PII handling require explicit controls.","Manifest/schema errors can produce apparently complete but unusable training data."]},
"Amazon SageMaker JumpStart":{"cost":["Cost follows endpoint instance hours, training/fine-tuning, storage, data transfer and model downloads; idle endpoints are often dominant.","Large models require memory/accelerator capacity and may have long startup times.","Include ECR/S3, notebooks, VPC endpoints, monitoring and evaluation compute."],"optimization":["Use JumpStart to evaluate foundation/pretrained models and deploy supported artifacts, but benchmark latency, quality, licensing and customization before standardizing.","Choose hosted endpoint, batch transform, fine-tuning or local deployment from workload volume and data-residency needs.","Pin model versions and container images; record the exact artifact and parameters used in evaluation."],"security":["Review model license, artifact source, container permissions, VPC access and endpoint roles before deploying a JumpStart model.","Scan downloaded model/container artifacts, restrict model access and protect fine-tuning data and endpoint logs.","Audit model selection, deployment, fine-tuning and endpoint changes."],"watchPoints":["Model card claims and benchmark results may not match the user's domain or languages.","License and usage restrictions are separate from technical deployment success.","A model update can change output quality and token/latency behavior."]},
"Amazon SageMaker Model Monitor":{"cost":["Cost follows monitoring jobs, captured data, processing compute, endpoint capture, storage and alerts.","High-frequency monitoring of large payloads can cost more than the inference workload.","Include S3, CloudWatch, EventBridge and remediation workflows."],"optimization":["Choose data-quality, model-quality, bias or feature-attribution monitoring from the risk; enabling every monitor creates noise.","Set baselines, sampling and schedule from drift speed and ground-truth availability, and route violations to an owner.","Align endpoint capture format and monitor constraints with the actual model version."],"security":["Give monitoring jobs access only to baseline, capture and output locations; protect statistics and violations because they may contain feature values.","Encrypt monitoring output and restrict who can alter baselines, constraints, schedules and alert destinations.","Audit endpoint-capture, baseline, schedule and violation actions."],"watchPoints":["A quiet monitor can mean no capture or missing ground truth, not no drift.","Violations are investigation signals, not automatic rollback decisions.","Schema and endpoint version changes can invalidate constraints."]},
"Amazon SageMaker Model Registry":{"cost":["Registry storage is only one cost; S3/ECR artifacts, evaluation compute, pipelines, endpoints and replication drive the lifecycle.","Retained failed experiments and duplicate artifacts accumulate.","Include CI/CD, scanning, monitoring and cross-Region artifact transfer."],"optimization":["Use model groups and approval states to separate experimentation from production, and connect registry events to controlled deployment pipelines.","Store evaluation metrics and data/model/container provenance with each version; a new artifact without evidence should not be promotable.","Use cross-account model sharing deliberately and test whether the receiving account can retrieve every dependent artifact."],"security":["Restrict model-group, version, approval, package and deployment permissions; promotion should require separated approval.","Protect model artifacts, metadata, lineage and evaluation reports with encryption and controlled S3/ECR access.","Audit model-version creation, approval/status, package and deployment changes."],"watchPoints":["Approval status is governance metadata, not proof that an endpoint deployed successfully.","Model package, inference image, preprocessing code and feature schema must remain compatible.","Deleting or moving an artifact can break historical reproducibility."]},
"Amazon SageMaker Neo":{"cost":["Cost follows compilation jobs, storage, target inference hardware and transfer; compiling every model/target combination multiplies work.","Edge distribution and artifact retention add storage/transfer cost.","Include device fleet, deployment, monitoring and fallback runtime."],"optimization":["Compile for the exact target hardware/runtime only after measuring accuracy and latency; optimized binaries can behave differently from the source model.","Use representative shapes and supported operators, and compare compiled versus uncompiled output during validation.","Keep target-specific artifacts versioned and fall back to a supported runtime when a target cannot load the compiled model."],"security":["Protect compilation inputs, model artifacts, compiler jobs and target-device credentials; compiled binaries can reveal proprietary models.","Restrict compilation and deployment roles and encrypt source/output artifacts.","Audit target, compiler configuration, model and deployment changes."],"watchPoints":["Operator support and numerical differences can change output quality after compilation.","Target hardware/runtime compatibility is a release constraint.","A compiled artifact is not portable across every device type."]},
"Amazon SageMaker Processing":{"cost":["Cost follows processing instance time, storage, ECR/S3 transfer, logs and network endpoints.","Large shuffle, idle workers and repeated full-dataset processing dominate.","Include KMS, NAT/VPC endpoints, pipeline orchestration and downstream training."],"optimization":["Use Processing for repeatable preprocessing/evaluation with explicit input channels, instance counts and sharding; avoid using interactive notebooks for production transforms.","Choose framework/container and instance type from memory, I/O and parallelism, and write outputs in partitioned/compressed formats.","Use pipelines, retries and step caching where deterministic, and clean temporary outputs after downstream consumption."],"security":["Give processing jobs narrow S3, ECR, KMS, VPC and secret permissions; the processing container should not inherit a notebook's broad role.","Encrypt input, output, volume and logs and control network egress from the processing subnet.","Audit job definitions, images, inputs, outputs and role changes."],"watchPoints":["A job can succeed with partial or skewed input if manifest/partition validation is weak.","Container exit success does not prove schema, row counts or data quality.","Processing role, network path and image digest are separate failure points."]},
"Amazon SageMaker Unified Studio":{"cost":["Cost spans Studio environments, processing/training, storage, catalog, query and downstream services; idle interactive sessions are common drivers.","Shared environments can improve utilization but increase noisy-neighbor and data-isolation requirements.","Include Glue/Lake Formation, Athena, S3, SageMaker, Redshift and observability."],"optimization":["Use governed projects and reusable workflows to connect data preparation, analytics and ML without duplicating assets.","Choose shared environments, compute profiles and data products from team isolation and workload concurrency.","Keep exploratory access separate from production promotion and capture lineage across the integrated workflow."],"security":["Separate project, domain, data, model, connection and workflow roles; a shared workspace must not become shared data access.","Protect project assets, notebooks, catalogs, connections and credentials with KMS and governed data permissions.","Audit project membership, environment, connection, model and deployment changes."],"watchPoints":["Unified Studio is an integration surface; each underlying service keeps its own authorization and quota model.","A project can open successfully while a connection, catalog grant or compute environment fails.","Lineage, asset version and environment configuration must be preserved for reproducibility."]},
"Amazon Titan":{"cost":["Cost follows tokens, images, embeddings, customization, inference and vector storage; input size and repeated embedding dominate.","Re-embedding a corpus after model/dimension changes can be expensive.","Include Bedrock, S3, OpenSearch/vector store, KMS and evaluation compute."],"optimization":["Choose Titan text/image/embedding model from modality and retrieval/generation task; use embeddings with a vector store rather than treating them as text generation.","Benchmark quality, token/image size, latency and context before selecting a model for production.","Version model, prompt, embedding dimensions and index together when building RAG."],"security":["Protect Titan model invocation, customization, artifact, data and evaluation roles; model access should be narrower than account-wide Bedrock administration.","Encrypt training data, custom artifacts, prompts and outputs and control model/log retention.","Audit model version, customization, inference profile and evaluation changes."],"watchPoints":["Embedding-model changes require index rebuild/evaluation.","Model output and content moderation remain application responsibilities.","Availability, version and Region support must be checked for the chosen Titan model."]},
"AWS Chatbot":{"cost":["Chatbot cost is mainly underlying SNS, CloudWatch, EventBridge, Lambda/SSM and chat-platform operations.","High-volume alerts create notification noise and downstream processing cost.","Include logs, incident tooling and command execution."],"optimization":["Use Chatbot for bounded notifications and approved operational commands; route complex remediation through Systems Manager/Step Functions with approvals.","Filter notifications by severity/owner and avoid sending every CloudWatch event to a human channel.","Use dedicated channels and role assumptions per environment."],"security":["Use chat-client/workspace, SNS topic, IAM role and command permissions separately; chat notifications should not automatically grant mutation rights.","Protect channel membership, message content, command logs and approval paths.","Audit configuration, channel, topic and role changes."],"watchPoints":["A notification delivered to chat is not acknowledgement or remediation.","Channel membership can expand effective visibility.","Chat commands and IAM role assumptions require audit and approval."]},
"Amazon CloudWatch Synthetics":{"cost":["Cost follows canary runs, runtime, data transfer, artifacts, metrics/logs and VPC resources; high frequency/Regions multiply spend.","Screenshots/video and verbose logs add storage.","Include CloudWatch alarms, Secrets Manager, NAT/endpoints and target service."],"optimization":["Use heartbeats for availability, multi-step canaries for user journeys and frequency/Regions based on detection objectives.","Set timeouts, retries, screenshots and success assertions to distinguish transient network error from application failure.","Run canaries from public/VPC locations that match the user path and include dependency checks intentionally."],"security":["Use canary roles with only the URLs/secrets/metrics permissions needed; protect credentials and screenshots/videos from canary runs.","Encrypt and restrict artifacts, logs, code and VPC connectivity; do not place secrets in canary source.","Audit canary code, schedule, runtime, alarm and secret changes."],"watchPoints":["A canary can pass a shallow endpoint while the login/payment/data journey fails.","Synthetic credentials and test data need lifecycle and isolation.","VPC canary routing, DNS, certificates and clock skew create false failures."]},
"Elastic Load Balancing (ELB)":{"cost":["Cost follows hours, capacity units/LCU, processed bytes, listeners, public IPv4, logs and transfer; each ELB type differs.","Cross-zone, TLS and WAF processing add traffic cost.","Include targets, NAT, certificates and observability."],"optimization":["Choose ALB for HTTP routing, NLB for connection/static-IP/low-latency needs and GWLB for appliance insertion; the choice is semantic, not cosmetic.","Tune health checks, deregistration delay, cross-zone behavior and target capacity for the chosen load balancer.","Use listener routing only for supported protocol/application decisions."],"security":["Separate ALB/NLB/GWLB listener, target, security-group, certificate and WAF permissions; load balancing is not backend authorization.","Protect access/connection logs and TLS material and audit listener/target changes.","Use service-specific resource policies and cross-account roles narrowly."],"watchPoints":["Target health can be green while a dependency or business operation is broken.","ALB/NLB/GWLB connection and protocol behavior differs.","Client-IP preservation and TLS termination affect security and troubleshooting."]},
"AWS Encryption SDK":{"cost":["Cost follows KMS requests, key storage, application compute, data transfer and ciphertext/storage overhead.","Per-record KMS calls and large metadata increase cost.","Include S3/EBS/RDS/app storage, KMS and rotation operations."],"optimization":["Use envelope encryption and data-key caching only with a measured security/performance trade-off; choose algorithm suite/commitment settings deliberately.","Bind ciphertext to stable encryption context and versioned key metadata so decrypt authorization matches the data domain.","Keep SDK version/commitment-policy compatibility tested during upgrades."],"security":["Separate encryption-key, keyring, commitment-policy and decrypt permissions; SDK configuration must not expose plaintext or keys.","Use KMS/Raw/AWS KMS keyrings according to custody requirements and protect encryption context from untrusted mutation.","Audit key use, commitment-policy, algorithm-suite and decrypt failures."],"watchPoints":["Commitment policies can make old/new ciphertext incompatible if rollout is not staged.","Encryption context is authenticated metadata, not a secret.","Decrypt failure can be key policy, context, algorithm, SDK or corrupted data."]},
"IAM":{"cost":["IAM has no direct hourly charge; identity governance, CloudTrail, Access Analyzer and downstream actions create cost.","Over-permission can enable unintended resource creation or data processing.","Include Identity Center, external IdP, logging and remediation."],"optimization":["Use conditions, tags, paths and boundaries for delegated administration, and keep workload roles purpose-specific.","Test policy changes with simulation/staged roles and make recovery access independent.","Use ABAC only when identity/resource tags are reliable and governed."],"security":["Treat IAM user/role/trust/identity/resource policies, boundaries, SCPs and session policies as separate layers; an allow in one layer is not enough.","Use federation/roles/MFA and eliminate long-lived keys; protect break-glass/root controls.","Audit AssumeRole, policy, key/secret and resource-policy changes with CloudTrail."],"watchPoints":["Explicit deny in SCP/boundary/resource policy overrides an allow.","IAM action authorization is not business ownership.","Policy size, role chaining, session expiry and eventual consistency affect operations."]},
"IAM Access Analyzer":{"cost":["Cost follows analyzers, analyzed resources, findings, policy generation and downstream exports; organization scope increases volume.","Repeated analysis and broad log/data collection add operational cost.","Include CloudTrail, Security Hub, IAM and ticketing."],"optimization":["Use external-access analyzers for resource-policy review, unused-access analyzers for cleanup and policy validation for pre-deployment checks; they answer different questions.","Archive known-intended findings with rationale/expiry and generate policies from observed access only after review.","Run analyzers across relevant accounts/Regions and include resource types actually used."],"security":["Protect analyzer, unused-access, policy-generation and finding-update permissions; analyzer output exposes external access paths.","Restrict organization-wide analyzer administration and exported findings.","Audit analyzer, archive-rule, policy-validation and finding changes."],"watchPoints":["A finding means a possible access path, not necessarily a vulnerability or required removal.","Unused access analysis needs observation time; immediate cleanup can break dormant recovery paths.","Analyzer Region/account scope can leave blind spots."]},
"IAM Identity Center":{"cost":["Cost follows identity/feature plan, external IdP/MFA, CloudTrail and account automation; downstream account resources are separate.","Large assignment/provisioning inventories add operational overhead.","Include federation, directory, break-glass monitoring and audit storage."],"optimization":["Use permission sets aligned to roles/accounts and provision them deliberately; use ABAC only with reliable identity attributes.","Set session duration and account assignment from actual operator workflow and test emergency access.","Keep workload roles separate from human permission sets."],"security":["Separate identity-source, permission-set, account-assignment and delegated administration rights; assignment can grant organization-wide access.","Protect external IdP, MFA, permission-set policies and break-glass access.","Audit sign-ins, assignments, permission sets and identity-source changes."],"watchPoints":["Permission-set updates may take time to provision.","Authenticated does not mean assigned or permitted by SCP.","Identity-source outage and emergency access need independent testing."]},
"Amazon S3 Intelligent-Tiering":{"cost":["Cost follows object storage tier, monitoring/automation fee, retrieval/archive access, requests and transfer; tiny objects may not benefit.","Monitoring/archive tiers and noncurrent versions affect long-tail cost.","Include S3 requests, KMS, analytics scans and replication."],"optimization":["Use Intelligent-Tiering for objects with unknown/changing access; choose monitoring/archive tiers and minimum object-size economics deliberately.","Do not apply it to predictable hot/cold data where explicit lifecycle classes are clearer and cheaper.","Combine tiering with version/lifecycle cleanup and analytics format design."],"security":["Use S3 bucket/access-point/KMS/lifecycle permissions with tiering configuration; automatic tier movement does not change object authorization.","Protect monitoring metadata, archive tiers and restore/retrieval paths and audit configuration changes.","Use CloudTrail data events selectively for tier/lifecycle investigations."],"watchPoints":["Tier transitions are based on access patterns and are not instantaneous.","Archive access introduces retrieval delay/fees and must fit the application.","Intelligent-Tiering is not backup or retention policy by itself."]},
"Amazon S3 Lifecycle policies":{"cost":["Lifecycle reduces storage cost but transitions, retrieval, early deletion, requests and noncurrent versions have charges.","Small/short-lived objects may cost more to transition than retain.","Include Glacier retrieval, replication, KMS, inventory and audit."],"optimization":["Order transitions/expiration rules from object age, version status, storage class minimums and recovery needs.","Use prefixes/tags to target workload classes and test lifecycle behavior with representative objects.","Combine lifecycle with versioning/Object Lock and replication deliberately; each protects a different failure."],"security":["Restrict lifecycle configuration, versioning, Object Lock and deletion permissions; lifecycle can delete or transition regulated data.","Protect rule review, retention tags and legal-hold assumptions and audit policy changes.","Use separate access controls for current/noncurrent versions and delete markers."],"watchPoints":["Lifecycle actions are asynchronous and can be hard to reverse.","Object Lock/legal hold overrides deletion and requires governance-mode planning.","A lifecycle rule can affect noncurrent versions even when current objects look healthy."]},
"Amazon S3 Cross-Region Replication":{"cost":["Cost follows replicated bytes, PUT/replication requests, destination storage, KMS, RTC and cross-Region transfer.","Versioned objects and delete-marker replication increase destination growth.","Include inventory, monitoring, backup and replica analytics."],"optimization":["Choose live, batch, same-account/cross-account and delete-marker/version behavior from the recovery/data-distribution objective.","Use prefixes/tags, replication metrics and RTC only where the SLA justifies the cost.","Keep destination lifecycle/retention independent enough to provide recovery from source mistakes."],"security":["Use replication role, destination bucket policy, KMS grants, Object Ownership and delete-marker permissions separately.","Encrypt source/destination and protect replication metrics, failure reports and replica access.","Audit replication configuration, rule priority, filters, KMS and destination changes."],"watchPoints":["Replication is asynchronous; success of source PUT does not mean replica availability.","KMS, ownership, versioning and destination policy can cause failed replication.","Replicated deletes/overwrites can reproduce source mistakes unless retention/version controls differ."]}
};

export function getServiceLearningInsights(service:string,category:string):ServiceLearningInsights{
  const insightAliases:Record<string,string>={
    "Audit Manager":"AWS Audit Manager",
    "AWS Resource Access Manager (RAM)":"AWS Resource Access Manager",
    "AWS Cost and Usage Reports":"AWS Cost and Usage Report",
  };
  const specific=serviceSpecificInsights[service] || serviceSpecificInsights[insightAliases[service] || ""];
  if(specific)return specific;
  const rule=rules.find(x=>x.match.test(service));
  if(rule)return {security:rule.security,optimization:rule.optimization,cost:rule.cost,watchPoints:rule.watchPoints};
  // Course categories are contextual only; unmatched services use the safe fallback below.
return {
    security:[`Identify the exact ${service} control-plane and data-plane permissions rather than granting broad category-level access.`,`Protect the data, credentials and integration points that pass through ${service}; use encryption and managed identities where the service supports them.`,`Collect the service-native audit/health signals that explain configuration changes, failed operations and downstream impact.`],
    optimization:[`Tune ${service} from its native throughput, concurrency, storage, connection or request model—not from a generic “scale everything” rule.`,`Use the architecture examples above to keep state, asynchronous work and failure isolation in the services designed to own them.`,`Measure the service-specific bottleneck before changing capacity, caching, batching or retry behavior.`],
    cost:[`Start with ${service}'s documented billing unit, then map how architecture volume turns into that unit.`,`Add the resources ${service} causes to run—storage, transfer, logs, encryption, compute and downstream API calls—so the estimate reflects the whole path.`,`Optimize the dominant measured driver first; removing unnecessary work usually matters more than small unit-price differences.`],
    watchPoints:[`Know what ${service} owns and what remains the responsibility of adjacent services in the architecture.`,`Identify its failure/retry boundary so an outage does not silently become duplicate work or data loss.`,`Remember the service-specific quota or scaling dimension most likely to constrain production before raw account-wide capacity.`]
  };
}
